from dataclasses import dataclass, field
from pathlib import Path
from typing import Dict, List, Optional, Tuple


class Linkage:
    AUTOMATIC = "automatic"
    DYNAMIC = "dynamic"
    STATIC = "static"
    EXECUTABLE = "executable"  # not a library product, but parsed for completeness
    PLUGIN = "plugin"
    SNIPPET = "snippet"
    UNKNOWN = "unknown"  # the dump-package payload was a shape we don't recognize

    _VALUES = (AUTOMATIC, DYNAMIC, STATIC, EXECUTABLE, PLUGIN, SNIPPET, UNKNOWN)


class TargetKind:
    REGULAR = "regular"
    TEST = "test"
    SYSTEM = "system"
    BINARY = "binary"
    PLUGIN = "plugin"
    MACRO = "macro"
    EXECUTABLE = "executable"
    UNKNOWN = "unknown"

    _VALUES = (REGULAR, TEST, SYSTEM, BINARY, PLUGIN, MACRO, EXECUTABLE, UNKNOWN)


class Language:
    """Per-target source-language classification, derived by walking the
    target's source tree under WORK_DIR/staged."""

    SWIFT = "Swift"
    OBJC = "ObjC"
    MIXED = "Mixed"
    NA = "N/A"  # system / binary / plugin / unknown — nothing to scan

    _VALUES = (SWIFT, OBJC, MIXED, NA)


@dataclass
class Platform:
    name: str            # "ios", "macos", "tvos", ...
    version: str         # "15.0"


@dataclass
class Product:
    name: str
    linkage: str         # one of Linkage._VALUES
    targets: List[str]   # backing target names


@dataclass
class Target:
    name: str
    kind: str            # one of TargetKind._VALUES
    path: Optional[str]  # relative to package root; None means SPM default
    public_headers_path: Optional[str]
    dependencies: List[str]
    exclude: List[str]
    language: str = Language.NA  # filled in by scan_target_languages()
    source_file_count: int = 0   # diagnostics; len(describe.targets[i].sources)


@dataclass
class TransitivePackageInfo:
    """A directly-referenced external dependency package: its SPM identity
    (as used in `.product(name: X, package: identity)` from the root's
    targets), the resolved checkout path under `<staged>/.build/checkouts/`,
    and its dumped library products.

    Populated by Inspect for every package identity that any REGULAR target
    in the root package references via `.product(name:, package:)`. The
    planner reads from this pre-computed data so it stays subprocess-free
    (Plan purity contract).
    """

    identity: str                    # SPM identity, e.g. "swift-clocks"
    checkout_path: Path              # absolute, under .build/checkouts/
    products: List["Product"]        # parsed via _parse_dump on the checkout
    tools_version: str               # for active-manifest selection in Prepare
    # The exact product names the root's REGULAR targets imported from this
    # identity via `.product(name: X, package: <identity>)`. Order preserved;
    # duplicates removed. The orchestrator passes these to the child run as
    # `Config.product_filters` so the child only builds what the umbrella
    # actually consumes, and the child's manifest pruner uses them to
    # compute the closure of external `.package(url:)` deps that must be
    # kept in the pre-staged Package.swift. The orchestrator may further
    # trim this list to only those products imported by IN-CLOSURE root
    # targets before handing it to the child.
    referenced_products: List[str] = field(default_factory=list)
    # Root-package target names that reference this transitive identity via
    # `.product(name:, package:)`. The orchestrator intersects this set with
    # the user's selected-target closure (product_filters + target_filters,
    # expanded by internal dep edges) to drop transitives reached only from
    # unrelated regular helper/example targets — avoiding fail-fast aborts on
    # external dependencies that the umbrella product would never link.
    referencing_root_targets: List[str] = field(default_factory=list)
    # Per-product attribution: product name -> ordered list of root REGULAR
    # target names that reference that specific product. Populated by Inspect
    # so the orchestrator can trim `referenced_products` down to only those
    # products an IN-CLOSURE root target actually imports — without this, a
    # package referenced by two different root targets via two different
    # products would force the child to build BOTH products even if only one
    # caller is in the user's selection.
    product_to_root_targets: Dict[str, List[str]] = field(default_factory=dict)


@dataclass
class Package:
    """Typed snapshot of `swift package dump-package` for the staged
    package. Read-only after Inspect; the planner consumes it."""

    name: str
    tools_version: str
    platforms: List[Platform]
    products: List[Product]
    targets: List[Target]
    schemes: List[str]              # from xcodebuild -list -json against staged
    raw_dump: dict                  # untouched dump-package JSON, for debugging
    staged_dir: Path
    # Direct (1st-level) external dependency packages whose products the
    # root's REGULAR targets reference via `.product(name:, package:)`.
    # Populated by Inspect when the root has external product deps, empty
    # for self-contained packages. Consumed by the top-level orchestrator
    # `_run_source_mode_with_transitives` to drive in-process recursion —
    # one child `_run_source_mode` call per identity, building each
    # transitive checkout as its own xcframework alongside the umbrella.
    transitive_packages: List["TransitivePackageInfo"] = field(default_factory=list)

    def target_by_name(self, name: str) -> Optional[Target]:
        for t in self.targets:
            if t.name == name:
                return t
        return None

    def transitive_package_by_identity(
        self, identity: str
    ) -> Optional["TransitivePackageInfo"]:
        """Case-insensitive lookup: SPM normalises identities to lowercase
        in `dump-package`'s `.product` shape, but the value the manifest
        passes to `package:` is whatever the author wrote in their
        `.package(...)` declaration.
        """
        target_lower = identity.lower()
        for tp in self.transitive_packages:
            if tp.identity.lower() == target_lower:
                return tp
        return None


# --- Plan, BuildUnit, StageSpec, PackageSwiftEdit ----------------------------
#
# These are stubs for Session 2; defined here so Session 1's code already
# imports the right type names and the file structure stays stable.


@dataclass
class StageSpec:
    """Inclusion-by-default + exclusion-list staging rules. The actual
    list of toxic top-level entries lives in TOXIC_TOP_LEVEL below; this
    type exists so the planner can override per-package if it ever needs
    to. (Not used in session 1, but referenced by REWRITE_DESIGN.md §5.2.)"""

    exclude_globs: List[str] = field(default_factory=list)


@dataclass
class PackageSwiftEdit:
    """Whitelisted Package.swift edit, produced by Plan and consumed by
    Prepare. Two source-mode kinds (a third kind, replace_with_binary_target,
    is generated and applied dynamically inside Execute for dedup-overlap
    and never travels through this struct):

      - "synth_dynamic_library"   — add a new `.library(name: P, type:
                                    .dynamic, targets: [...])` to wrap an
                                    existing product whose source-mode
                                    linkage we want flipped to dynamic.
                                    `product_name` is the synthetic
                                    product name written into the manifest
                                    (collision-avoided by the planner;
                                    often differs from the rename target
                                    on BuildUnit.framework_name).
      - "synth_library"           — add a new `.library(name: T, type:
                                    .dynamic, targets: [T])` for the
                                    `--target T` escape hatch. By
                                    construction T is not an existing
                                    product name, so no rename is needed
                                    and `BuildUnit.scheme ==
                                    BuildUnit.framework_name`.

    Both kinds are implemented by Prepare as a `swift package add-product`
    subprocess invocation, then a round-trip dump-package validation that
    the new product appears with linkage DYNAMIC and the requested target
    list.
    """

    kind: str  # "synth_dynamic_library" | "synth_library"
    product_name: str
    targets: List[str] = field(default_factory=list)


@dataclass
class BuildUnit:
    """One unit of work the executor will run.

    `archive_strategy` discriminates the execute path:
      - "archive"         — run `xcodebuild archive` against the scheme.
                            Source-mode default; the post-archive rename
                            handles `synth_dynamic_library` units whose
                            scheme name differs from the final framework
                            name.
      - "copy-artifact"   — binary mode: the xcframework already exists on
                            disk at `artifact_path`; Execute just copies it.

    (Pre-B there was a third "static-promote" strategy for the source path
    where xcodebuild emitted a `.a` instead of a `.framework`; that path
    was removed when the synthetic-dynamic-library product trick made it
    unnecessary. The clang `-dynamiclib` re-link still exists, but only
    inside `binary_promote.promote_binary_xcframework_static_to_dynamic`
    for vendor-shipped binary xcframeworks — it doesn't flow through the
    archive_strategy enum.)
    """

    name: str
    scheme: str
    framework_name: str
    language: str
    archive_strategy: str
    source_targets: List[str] = field(default_factory=list)
    # True iff this unit exists because of `--target T` — i.e. the plan
    # injects a synthetic `.library()` entry for it. Affects dry-run labels
    # and Verify's per-unit error messages.
    synthetic: bool = False
    # Populated only for archive_strategy == "copy-artifact". Absolute path
    # to the xcframework discovered under `.build/artifacts/` by Fetch.
    artifact_path: Optional[Path] = None


@dataclass
class BinaryArtifact:
    """A pre-built xcframework discovered via binary-mode SPM resolve.

    The planner takes a list of these (from `discover_binary_artifacts`)
    and filters by --product. Each surviving record becomes a build unit
    whose execute strategy is "copy-artifact".
    """

    product_name: str  # the xcframework name without the .xcframework suffix
    path: Path         # absolute path to the .xcframework directory


@dataclass
class Plan:
    """Output of the planner: a typed description of what the downstream
    phases will do. Pure data — no side effects, no filesystem handles
    beyond what inspect already gave us."""

    stage: StageSpec = field(default_factory=StageSpec)
    package_swift_edits: List[PackageSwiftEdit] = field(default_factory=list)
    build_units: List[BuildUnit] = field(default_factory=list)
    # Products the planner dropped, with a human-readable reason. Printed
    # by --dry-run and surfaced in the final run summary.
    skipped: List[Tuple[str, str]] = field(default_factory=list)
    # Planner diagnostics that aren't errors — surfaced to stderr by the
    # caller after planning completes. Kept as data so the planner stays
    # a pure function (§5.2 contract).
    warnings: List[str] = field(default_factory=list)
    # --include-deps flag forwarded to Execute. The planner can't enumerate
    # transitive deps ahead of time (they only exist after xcodebuild runs),
    # so this is just a gate.
    include_deps: bool = False
    # True for binary-mode plans. Execute uses this to skip xcodebuild
    # entirely. The planner is the only thing that sets it.
    binary_mode: bool = False


@dataclass
class PreparedPlan:
    """Output of Prepare. Wraps the original Plan together with the typed
    Package model that resulted from re-parsing the edited active manifest.

    Existence of a PreparedPlan is a contract: the active manifest under
    `package.staged_dir` (`Package.swift` or whichever
    `Package@swift-X.Y.swift` SPM picks for the toolchain) parses cleanly
    through `swift package dump-package` and every planner-requested edit
    appears in the dumped output the way the planner expected. Execute can
    rely on that invariant — it never re-validates the manifest itself.
    """

    plan: Plan
    package: Package


@dataclass
class ArchiveSlice:
    """One (build unit, slice) pair's outputs from xcodebuild archive.

    A "slice" is one (platform, arch-class) build, e.g. ios-arm64, the
    iOS simulator fat archive, macos, mac-catalyst. All slices for a
    unit archive in parallel via `_archive_all_parallel`; the located
    framework path is recorded here so Execute's rename and injection
    passes don't need to re-walk the archive.
    """

    arch_suffix: str              # slice id (e.g. "ios-arm64", "macos")
    sdk_name: str                 # "iphoneos" / "iphonesimulator" / "macosx"
    archive_path: Path            # .xcarchive directory
    dd_path: Path                 # derived data path
    log_path: Path                # build log
    result_bundle_path: Path      # xcresult bundle
    framework_path: Optional[Path] = None


@dataclass
class DependencyXcframework:
    """One dependency xcframework built alongside a primary unit via
    `--include-deps`.

    Pairs the on-disk path with the expected language classification
    (derived from the matching target in the Package model, if one
    exists) so that `_finalize_with_verify` can thread the same
    plan-time expected-language signal into Verify for deps that the
    primary build units already get. Without this, dependency artifacts
    would fall back to post-hoc detection and the mixed-language
    silent-pass hole would still apply to them.
    """

    path: Path
    expected_language: str = ""  # Language._VALUES; "" / "N/A" → post-hoc fallback


@dataclass
class ExecutedUnit:
    """Output of Execute for a single build unit.

    Holds the archive slices produced for this unit (one per enabled
    platform-arch pair) and the final xcframework path the merge step
    produced. `slices` is empty for binary-mode units (`copy-artifact`),
    where only `xcframework_path` is set, pointing at the copied artifact
    in `<output_dir>/`.
    """

    name: str                     # build unit name (matches plan.build_units[i].name)
    slices: List[ArchiveSlice] = field(default_factory=list)
    xcframework_path: Optional[Path] = None
    framework_name: Optional[str] = None  # the resolved <fw_name>, may differ from unit.name
    framework_type: str = ""              # "Swift" / "ObjC" / "Mixed" / "Unknown" — post-hoc detection from disk, for summary printing
    # Language the planner said this unit was supposed to produce. One of
    # Language._VALUES ("Swift" / "ObjC" / "Mixed" / "N/A"). Carried through
    # from `BuildUnit.language` so Verify can gate its language-specific
    # fatal checks on what the plan intended, not on what survived in the
    # partially-built artifact. Empty string for legacy callers; Verify
    # treats empty / "N/A" as "fall back to post-hoc detection".
    expected_language: str = ""
    # Per-(platform, variant) slice coverage the user asked for. Variants
    # are "device" / "simulator" / "maccatalyst". Verify enforces that the
    # xcframework's AvailableLibraries carries an entry for every pair —
    # critical for binary mode where we copy a vendor artifact unchanged
    # and have no other way to know whether the requested coverage is
    # actually present (e.g. an iOS-device-only artifact would otherwise
    # silently satisfy `--min-ios`). Empty list is the legacy default and
    # disables the check.
    expected_slice_classes: List[Tuple[str, str]] = field(default_factory=list)
    is_binary_copy: bool = False
    dependency_xcframeworks: List[DependencyXcframework] = field(default_factory=list)


@dataclass
class VerifyResult:
    """One xcframework's strict-verify outcome (REWRITE_DESIGN.md §5.5).

    Verify is per-unit. A unit either `passed` (every fatal check cleared)
    or it didn't (one or more entries in `fatal_issues`). `warnings` are
    advisory and never cause `passed=False`. `framework_type` is reported
    for the summary printer's `[Swift|ObjC|Mixed|Unknown]` label.

    Verify never raises for "the user's xcframework is broken" — it
    records the failure here and lets `main()` translate the aggregate
    into an exit code. The only thing that surfaces as a `VerifyError`
    exception is verify code itself crashing (e.g. unreadable output
    directory) — see REWRITE_DESIGN.md §7.
    """

    unit_name: str
    framework_name: str
    xcframework_path: Path
    framework_type: str            # "Swift" | "ObjC" | "Mixed" | "Unknown"
    size_bytes: int
    passed: bool
    fatal_issues: List[str] = field(default_factory=list)
    warnings: List[str] = field(default_factory=list)


# --- TargetKind helpers ------------------------------------------------------


def _default_target_path(target_name: str, target_kind: str) -> Optional[str]:
    """SPM's default path for a target when `path:` isn't set.

    Only returns a path for kinds that actually have a buildable source
    tree under `Sources/` or `Tests/`. System / binary / plugin / macro
    targets either point at host headers, prebuilt artifacts, or compiler
    plugins, so they have no default source path and we return None.

    For regular and executable targets it's `Sources/<name>`; for tests
    it's `Tests/<name>`. We don't try to resolve the case where SPM picks
    an alternate `Source/<name>` (Alamofire) — those targets always
    declare `path:` explicitly, so dump-package returns the value verbatim.
    """
    if not target_name:
        return None
    if target_kind == TargetKind.TEST:
        return f"Tests/{target_name}"
    if target_kind in (TargetKind.REGULAR, TargetKind.EXECUTABLE):
        return f"Sources/{target_name}"
    return None


# ============================================================================
# --- platforms.py ----------------------------------------------------------
# ============================================================================


from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple



@dataclass(frozen=True)
class PlatformSlice:
    platform: str                   # "ios", "macos", "maccatalyst", "tvos", "watchos", "visionos"
    slice_id: str                   # unique key: "ios-arm64", "ios-simulator", "macos", ...
    sdk_name: str                   # `xcodebuild -showsdks` short name
    destination: str                # xcodebuild -destination value
    deployment_target_var: str      # build setting name passed as `<var>=<version>`
    clang_min_flag_template: str    # `{version}`-formatted single clang arg for binary-mode static→dynamic re-link


_PLATFORM_SLICES: Dict[str, Tuple[PlatformSlice, ...]] = {
    "ios": (
        PlatformSlice("ios", "ios-arm64", "iphoneos",
                      "generic/platform=iOS",
                      "IPHONEOS_DEPLOYMENT_TARGET",
                      "-miphoneos-version-min={version}"),
        PlatformSlice("ios", "ios-simulator", "iphonesimulator",
                      "generic/platform=iOS Simulator",
                      "IPHONEOS_DEPLOYMENT_TARGET",
                      "-mios-simulator-version-min={version}"),
    ),
    "macos": (
        PlatformSlice("macos", "macos", "macosx",
                      "generic/platform=macOS",
                      "MACOSX_DEPLOYMENT_TARGET",
                      "-mmacosx-version-min={version}"),
    ),
    "maccatalyst": (
        PlatformSlice("maccatalyst", "maccatalyst", "macosx",
                      "generic/platform=macOS,variant=Mac Catalyst",
                      "IPHONEOS_DEPLOYMENT_TARGET",
                      "-mtargetos=ios{version}-macabi"),
    ),
    "tvos": (
        PlatformSlice("tvos", "tvos-arm64", "appletvos",
                      "generic/platform=tvOS",
                      "TVOS_DEPLOYMENT_TARGET",
                      "-mtvos-version-min={version}"),
        PlatformSlice("tvos", "tvos-simulator", "appletvsimulator",
                      "generic/platform=tvOS Simulator",
                      "TVOS_DEPLOYMENT_TARGET",
                      "-mtvos-simulator-version-min={version}"),
    ),
    "watchos": (
        PlatformSlice("watchos", "watchos-arm64", "watchos",
                      "generic/platform=watchOS",
                      "WATCHOS_DEPLOYMENT_TARGET",
                      "-mwatchos-version-min={version}"),
        PlatformSlice("watchos", "watchos-simulator", "watchsimulator",
                      "generic/platform=watchOS Simulator",
                      "WATCHOS_DEPLOYMENT_TARGET",
                      "-mwatchos-simulator-version-min={version}"),
    ),
    "visionos": (
        PlatformSlice("visionos", "visionos-arm64", "xros",
                      "generic/platform=visionOS",
                      "XROS_DEPLOYMENT_TARGET",
                      "-mtargetos=xros{version}"),
        PlatformSlice("visionos", "visionos-simulator", "xrsimulator",
                      "generic/platform=visionOS Simulator",
                      "XROS_DEPLOYMENT_TARGET",
                      "-mtargetos=xros{version}-simulator"),
    ),
}


# Fixed iteration order so dry-run output, the slice merge command, and
# all parallel-build scheduling consume slices in a stable order across
# runs. iOS first (matches today's behaviour); subsequent platforms in
# the same order as the CLI flags appear in --help.
_PLATFORM_ORDER: Tuple[str, ...] = (
    "ios", "macos", "maccatalyst", "tvos", "watchos", "visionos",
)


def _selected_slices(config: "Config") -> List[Tuple[PlatformSlice, str]]:
    """Walk every `min_<platform>` field on `config` and return the
    ordered list of (slice, deployment_target_version) pairs the rest
    of the pipeline should drive xcodebuild against.

    Returns an empty list when no platform is enabled — the caller
    (`main()`) validates that ≥1 platform is enabled before reaching
    Execute, so an empty return from here is a programmer error.
    """
    out: List[Tuple[PlatformSlice, str]] = []
    versions: Dict[str, Optional[str]] = {
        "ios": config.min_ios,
        "macos": config.min_macos,
        "maccatalyst": config.min_maccatalyst,
        "tvos": config.min_tvos,
        "watchos": config.min_watchos,
        "visionos": config.min_visionos,
    }
    for plat in _PLATFORM_ORDER:
        version = versions.get(plat)
        if not version:
            continue
        for s in _PLATFORM_SLICES[plat]:
            out.append((s, version))
    return out


def _autodetect_min_versions(config: "Config", package: "Package") -> Dict[str, str]:
    """Fill in `config.min_<platform>` fields from `Package.platforms[]`
    when the user passed zero --min-* flags.

    Returns the dict of `{platform: version}` that was applied (empty
    when no auto-detect ran — i.e., the user provided explicit flags).
    Mutates `config` in place.

    Two policy choices, both deliberate:

    1. Explicit-vs-auto is all-or-nothing. If the user passed any
       --min-* flag, we honor exactly that set; no mixing with derived
       platforms. Keeps the mental model "what I typed is what I got."

    2. When the package declares NO platforms at all (`platforms:` array
       absent or empty), fall back to iOS 15.0 — today's pre-auto-detect
       default. Many small library packages omit `platforms:` entirely
       and rely on SPM's implicit minima; the tool's downstream (.NET
       binding generation) almost always wants iOS, so the fallback
       preserves the most common case.

    `--no-ios` is respected: if it was passed, auto-detect skips the iOS
    entry from the package even when the package declares iOS. The
    other declared platforms still get filled in. A `--no-ios`-only
    invocation against an iOS-only package therefore yields zero
    platforms; the caller's post-autodetect validator surfaces that as a
    clear error.
    """
    user_provided_any = any([
        config.min_ios, config.min_macos, config.min_maccatalyst,
        config.min_tvos, config.min_watchos, config.min_visionos,
    ])
    if user_provided_any:
        return {}

    derived: Dict[str, str] = {}
    for p in package.platforms:
        if p.name not in _PLATFORM_ORDER or not p.version:
            continue
        if p.name == "ios" and config.no_ios:
            continue
        derived[p.name] = p.version

    if not derived and not config.no_ios:
        config.min_ios = "15.0"
        return {"ios": "15.0"}

    for plat, ver in derived.items():
        setattr(config, f"min_{plat}", ver)
    return derived


def _enabled_platforms(config: "Config") -> List[str]:
    """Platforms the user requested via `--min-*` flags, in fixed order.
    Pure data — no side effects."""
    versions: Dict[str, Optional[str]] = {
        "ios": config.min_ios,
        "macos": config.min_macos,
        "maccatalyst": config.min_maccatalyst,
        "tvos": config.min_tvos,
        "watchos": config.min_watchos,
        "visionos": config.min_visionos,
    }
    return [p for p in _PLATFORM_ORDER if versions.get(p)]


# SPM `PackageDescription` platform case names, keyed by our internal
# platform identifier. Used by the binary-resolve shim to build the
# manifest's `platforms:` array. The string-version form
# (`.iOS("15.0")`) sidesteps the `.v<major>` enum table — which is
# wrong for macOS minima like 10.15 (`.v10` would be `.v10_0`).
_SPM_PLATFORM_CASE: Dict[str, str] = {
    "ios": "iOS",
    "macos": "macOS",
    "maccatalyst": "macCatalyst",
    "tvos": "tvOS",
    "watchos": "watchOS",
    "visionos": "visionOS",
}


def _platform_from_library_identifier(lid: str) -> Optional[str]:
    """Map an xcframework `AvailableLibraries[*].LibraryIdentifier` to one
    of our internal platform IDs. Apple's convention for these strings
    (per `man xcodebuild -create-xcframework` + observed real-world
    xcframeworks): `<platform>-<archs>[-<variant>]`, where `variant` is
    `simulator` or `maccatalyst`. visionOS uses the SDK prefix `xros`,
    not `visionos`. Returns None for shapes we don't recognise — callers
    treat unknown identifiers as not contributing to coverage.
    """
    if lid.endswith("-maccatalyst"):
        return "maccatalyst"
    if lid.startswith("ios-") or lid == "ios":
        return "ios"
    if lid.startswith("macos-") or lid == "macos":
        return "macos"
    if lid.startswith("tvos-") or lid == "tvos":
        return "tvos"
    if lid.startswith("watchos-") or lid == "watchos":
        return "watchos"
    if lid.startswith("xros-") or lid == "xros":
        return "visionos"
    return None


def _variant_from_library_identifier(lid: str) -> str:
    """Classify the device/simulator/maccatalyst flavour of a
    LibraryIdentifier. Pairs with `_platform_from_library_identifier`
    so Verify can assert (platform, variant) coverage — not just family
    coverage — against `unit.expected_slice_classes`."""
    if lid.endswith("-maccatalyst"):
        return "maccatalyst"
    if lid.endswith("-simulator"):
        return "simulator"
    return "device"


def _variant_for_platform_slice(s: "PlatformSlice") -> str:
    """Same taxonomy as `_variant_from_library_identifier`, but applied
    to our internal `PlatformSlice` (whose `slice_id` we control). Keeps
    the expected-set construction in lockstep with the covered-set
    construction inside `_verify_one_unit`."""
    if s.platform == "maccatalyst":
        return "maccatalyst"
    if s.slice_id.endswith("-simulator"):
        return "simulator"
    return "device"


def _expected_slice_classes(config: "Config") -> List[Tuple[str, str]]:
    """Per-(platform, variant) coverage requirement derived from the
    enabled `--min-*` flags. e.g. `--min-ios 15 --min-macos 11` yields
    `[("ios", "device"), ("ios", "simulator"), ("macos", "device")]`."""
    return [
        (s.platform, _variant_for_platform_slice(s))
        for s, _ in _selected_slices(config)
    ]


def _spm_platform_entries(config: "Config") -> List[str]:
    """Render one `.iOS("15.0")`-style entry per enabled platform, in
    fixed order. Used by the binary-resolve shim manifest emitter."""
    versions: Dict[str, Optional[str]] = {
        "ios": config.min_ios,
        "macos": config.min_macos,
        "maccatalyst": config.min_maccatalyst,
        "tvos": config.min_tvos,
        "watchos": config.min_watchos,
        "visionos": config.min_visionos,
    }
    entries: List[str] = []
    for plat in _PLATFORM_ORDER:
        v = versions.get(plat)
        if not v:
            continue
        entries.append(f'.{_SPM_PLATFORM_CASE[plat]}("{v}")')
    return entries


# ============================================================================
# --- fetch.py --------------------------------------------------------------
# ============================================================================


import os
import re
import shutil
import subprocess
from pathlib import Path
from typing import List, Sequence, Tuple


# Top-level (and any-depth) artifact directories that are unsafe to leave
# in the staged tree. Two reasons:
#   - .git, .build, DerivedData, node_modules: huge and not needed for SPM build
#   - *.xcodeproj, *.xcworkspace: cause `xcodebuild -list` and
#     `xcodebuild archive` to refuse to pick a project (bug 4 in
#     SPM_TO_XCFRAMEWORK_NOTES.md). The design always builds against
#     SPM-auto-generated schemes, so we never want these in staged.
TOXIC_NAMES = {
    ".git",
    ".build",
    "DerivedData",
    "node_modules",
}
TOXIC_SUFFIXES = (".xcodeproj", ".xcworkspace")


def _is_toxic_entry(name: str) -> bool:
    if name in TOXIC_NAMES:
        return True
    for sfx in TOXIC_SUFFIXES:
        if name.endswith(sfx):
            return True
    return False


def _git(args: Sequence[str], **kwargs) -> subprocess.CompletedProcess:
    """Thin wrapper around git so the call sites stay readable."""
    return subprocess.run(
        ["git", *args],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        **kwargs,
    )


# Allowed remote URL prefixes. Local filesystem paths are accepted
# separately (they must resolve to an existing directory).
_REMOTE_URL_PREFIXES = ("http://", "https://", "git@", "ssh://")

# Permissive but bounded tag pattern: letters, digits, dots, hyphens,
# underscores, plus signs, and slashes (for `refs/heads/...`-style tags
# that sometimes leak through). Length-capped so a pathological input
# can't OOM the tool. Real-world tags in the wild almost always fit.
_TAG_PATTERN = re.compile(r"[A-Za-z0-9._+/\-]+")
_MAX_TAG_LENGTH = 200


def _validate_package_source(source: str) -> None:
    """Argument-injection hardening for `config.package_source`.

    Raises `FetchError` for shapes that could be misinterpreted as a
    command-line option (leading `-`) or inject through shell / git
    metacharacters (newline, carriage return, null byte).

    Accepts either:
      - a supported remote URL scheme (`http://`, `https://`, `git@`,
        `ssh://`), or
      - a local filesystem path that resolves to an existing directory.

    Called from `main()` so the error surfaces at argument-parse time,
    not after Execute has already done work. Remote / local detection
    here stays consistent with `Config.is_remote`.
    """
    if not source:
        raise FetchError("package source is empty")
    if any(ch in source for ch in ("\n", "\r", "\x00")):
        raise FetchError(
            "package source contains newline, carriage return, or null byte"
        )
    if source.startswith("-"):
        raise FetchError(
            f"package source {source!r} starts with `-` and would be "
            "misinterpreted as a command-line option"
        )
    if source.startswith(_REMOTE_URL_PREFIXES):
        return
    # Local path: must resolve to an existing directory.
    try:
        local = Path(source).expanduser()
    except (OSError, ValueError) as exc:
        raise FetchError(f"package source {source!r} is not a valid path: {exc}") from exc
    if not local.is_dir():
        raise FetchError(
            f"package source {source!r} is neither a supported remote URL "
            f"(http://, https://, git@, ssh://) nor an existing local directory"
        )


def _validate_git_ref(ref: str, *, field: str) -> None:
    """Reject git refs that would be misparsed as CLI options or that
    contain shell / git metacharacters. Used for `--version`,
    `--revision` resolution output, and any other user-supplied ref.

    `field` is a short label ("version", "tag", "revision") used in the
    error message so the user can tell which input tripped the check.
    """
    if not ref:
        return
    if any(ch in ref for ch in ("\n", "\r", "\x00")):
        raise FetchError(
            f"{field} contains newline, carriage return, or null byte"
        )
    if ref.startswith("-"):
        raise FetchError(
            f"{field} {ref!r} starts with `-` and would be "
            "misinterpreted as a command-line option"
        )
    if len(ref) > _MAX_TAG_LENGTH:
        raise FetchError(
            f"{field} {ref!r} is longer than {_MAX_TAG_LENGTH} characters"
        )
    if not _TAG_PATTERN.fullmatch(ref):
        raise FetchError(
            f"{field} {ref!r} contains characters outside the allowed "
            f"tag set (letters, digits, `._+/-`)"
        )


def normalize_version_tag(url: str, version: str) -> Tuple[str, bool]:
    """Resolve a user-supplied version string to an actual tag on the remote.

    Returns (resolved_tag, was_rewritten). The caller stores both the
    user-supplied value (for SPM `exact:`) and the resolved tag (for git
    operations). This is the bug-1 fix from SPM_TO_XCFRAMEWORK_NOTES.md.

    If neither `<version>` nor `v<version>` matches, returns the original
    version unchanged so downstream `git clone` produces a clear error.

    Note: we require an *exact* `refs/tags/<name>` match in the parsed
    `git ls-remote --tags` output. Earlier drafts trusted any non-empty
    output, but git's pattern matching can return sibling refs (e.g.
    asking for `1.2` matches `1.2.0`), which would silently leak the
    wrong version downstream.
    """
    if not version:
        return version, False

    if _exact_tag_exists(url, version):
        return version, False

    v_prefixed = f"v{version}"
    if _exact_tag_exists(url, v_prefixed):
        return v_prefixed, True

    return version, False


def _exact_tag_exists(url: str, tag: str) -> bool:
    """True iff `git ls-remote --tags <url>` reports an exact `refs/tags/<tag>`
    or `refs/tags/<tag>^{}` ref. Strict equality — no glob/prefix matching.
    """
    # `--` separates git's options from positional URL/ref arguments so
    # a future `url` or `tag` beginning with `-` can't be parsed as a flag.
    cp = _git(["ls-remote", "--tags", "--", url, f"refs/tags/{tag}", f"refs/tags/{tag}^{{}}"])
    if cp.returncode != 0:
        return False
    wanted = {f"refs/tags/{tag}", f"refs/tags/{tag}^{{}}"}
    for line in cp.stdout.splitlines():
        parts = line.split(maxsplit=1)
        if len(parts) == 2 and parts[1] in wanted:
            return True
    return False


def verify_revision(url: str, tag: str, expected_sha: str) -> None:
    """Verify a git tag resolves to the expected commit SHA *before* cloning.

    Annotated tags need ^{}-dereference to compare to a commit SHA, so we
    query both refs and prefer the dereferenced one.
    """
    if not re.fullmatch(r"[0-9a-f]{40}", expected_sha):
        raise FetchError(
            f"--revision requires a full 40-character SHA (got: {expected_sha})"
        )

    info(f"Verifying tag '{tag}' resolves to {expected_sha}...")
    # See `_exact_tag_exists` for the `--` rationale.
    cp = _git(["ls-remote", "--tags", "--", url, f"refs/tags/{tag}", f"refs/tags/{tag}^{{}}"])
    if cp.returncode != 0:
        raise FetchError(f"Failed to query remote tags from {url}: {cp.stderr.strip()}")

    lines = [ln for ln in cp.stdout.splitlines() if ln.strip()]
    if not lines:
        raise FetchError(f"Tag '{tag}' not found in {url}")

    deref_line = next((ln for ln in lines if ln.endswith("^{}")), None)
    sha_source = deref_line if deref_line else lines[0]
    actual_sha = sha_source.split()[0]

    if actual_sha != expected_sha:
        raise FetchError(
            f"Revision mismatch for tag '{tag}':\n"
            f"  Expected: {expected_sha}\n"
            f"  Actual:   {actual_sha}\n"
            f"The tag may have been force-pushed. Aborting for safety."
        )

    success("  Revision verified ✓")


def fetch_source(config: Config) -> Path:
    """Clone or copy the package into WORK_DIR/source.

    Returns the source directory. Does NOT stage — that's stage_source().
    """
    assert config.work_dir is not None
    source_dir = config.work_dir / "source"

    if config.is_remote:
        if not config.user_version:
            raise FetchError("Version (--version) is required for remote package URLs.")

        if config.revision:
            verify_revision(
                config.package_source, config.resolved_version, config.revision
            )

        info(f"Cloning {config.package_source} @ {config.resolved_version}")
        # `--` separates git-clone's options from the positional
        # <repo>/<dir> pair so a user-supplied URL or directory beginning
        # with `-` can't be parsed as a flag. The remaining defence is
        # the argparse-time validation in `_validate_package_source`
        # and `_validate_git_ref` — both hit before we ever reach the
        # clone call.
        cp = _git(
            [
                "clone",
                "--depth",
                "1",
                "--branch",
                config.resolved_version,
                "--",
                config.package_source,
                str(source_dir),
            ]
        )
        if cp.returncode != 0:
            raise FetchError(
                f"Failed to clone {config.package_source} at version "
                f"{config.resolved_version}\n{cp.stderr.strip()}"
            )
    else:
        # Local path. Resolve through Path so trailing slashes / `.` work.
        local_path = Path(config.package_source).expanduser().resolve()
        if not local_path.is_dir():
            raise FetchError(f"Local path not found: {config.package_source}")
        if not (local_path / "Package.swift").is_file():
            raise FetchError(f"No Package.swift found at {local_path}")

        info(f"Copying local package from {local_path}")
        # shutil.copytree refuses if dest exists; source_dir is freshly created
        # by main() so this is fine.
        shutil.copytree(local_path, source_dir, symlinks=True)

    if not (source_dir / "Package.swift").is_file():
        raise FetchError("No Package.swift found in package source")

    return source_dir


def _copy_excluding_toxic(src: Path, dst: Path) -> None:
    """Copy `src` → `dst`, dropping TOXIC_NAMES / TOXIC_SUFFIXES at every
    level. Implemented as a manual recursive walk so we can prune at the
    *directory* level (not just at the leaf), which matters for
    `.git/`-style trees with millions of objects.
    """
    dst.mkdir(parents=True, exist_ok=True)
    for entry in os.scandir(src):
        if _is_toxic_entry(entry.name):
            continue
        src_path = Path(entry.path)
        dst_path = dst / entry.name
        if entry.is_symlink():
            # Preserve symlinks verbatim. SPM packages occasionally use them
            # for vendored sources; following would copy the wrong tree.
            link_target = os.readlink(src_path)
            os.symlink(link_target, dst_path)
        elif entry.is_dir(follow_symlinks=False):
            _copy_excluding_toxic(src_path, dst_path)
        else:
            shutil.copy2(src_path, dst_path, follow_symlinks=False)


def stage_source(config: Config, source_dir: Path) -> Path:
    """Stage `source_dir` into WORK_DIR/staged.

    Two-pass per REWRITE_DESIGN.md §5.0:
      1. Copy everything except TOXIC_NAMES / TOXIC_SUFFIXES.
      2. Run `swift package dump-package` on the staged copy to learn the
         package's own `exclude:` paths, then delete those from staged.

    The second pass is best-effort: if dump-package can't parse yet (e.g.
    the package needs a newer swift toolchain), the inspect phase will
    surface that error directly. Staging only does the first pass and
    leaves the per-target excludes alone.
    """
    # Local import keeps the fetch ↔ inspect cycle broken — inspect.py
    # imports model._default_target_path, but the dump-package helper is
    # only needed once and at runtime, never at import time.

    assert config.work_dir is not None
    staged_dir = config.work_dir / "staged"
    if staged_dir.exists():
        shutil.rmtree(staged_dir)

    info("Staging package into clean working tree...")
    _copy_excluding_toxic(source_dir, staged_dir)

    # Sanity: at minimum the staged dir must contain Package.swift, otherwise
    # the inclusion-by-default rule has already gone wrong.
    if not (staged_dir / "Package.swift").is_file():
        raise FetchError(
            "Stage produced no Package.swift — staging exclusion list dropped "
            "the manifest. This is a bug in spm-to-xcframework."
        )

    # Pass 2: drop the package's own `exclude:` paths. We do this best-effort
    # — failure to dump-package here is the inspect phase's job to surface,
    # not ours. The exclude pass is purely a hygiene measure (it stops
    # excluded files from leaking into the staged tree where they could
    # confuse later phases that walk the source tree).
    try:
        dump = _swift_dump_package(staged_dir)
    except InspectError:
        # Can't enumerate excludes — the next phase will fail loudly. Leave
        # the staged tree as-is.
        return staged_dir

    removed_count = 0
    for tgt in dump.get("targets", []):
        target_path_str = tgt.get("path") or _default_target_path(
            tgt.get("name", ""), tgt.get("type", "")
        )
        if not target_path_str:
            continue
        for ex in tgt.get("exclude", []) or []:
            ex_rel = Path(target_path_str) / ex
            # Lexical containment check: refuse anything that escapes
            # the staged tree at the path level (`..` traversal, absolute
            # path) BEFORE touching the filesystem. This is symlink-safe:
            # we never call `.resolve()` because the staged tree may
            # contain vendored symlinks pointing outside, and resolving
            # through them could let an exclude path escape the tree.
            try:
                # Path.is_absolute() catches `/etc/passwd`-style escapes;
                # the parts check catches `..` traversal.
                if ex_rel.is_absolute() or ".." in ex_rel.parts:
                    continue
            except (TypeError, ValueError):
                continue
            ex_path = staged_dir / ex_rel
            if ex_path.is_symlink():
                # Drop the link, not its target.
                ex_path.unlink()
                removed_count += 1
                continue
            if ex_path.is_dir():
                shutil.rmtree(ex_path)
                removed_count += 1
            elif ex_path.exists():
                ex_path.unlink()
                removed_count += 1

    # SPM resolve. Per design §5.0 step 5: pre-resolve dependencies on the
    # staged tree so downstream xcodebuild calls don't need network or
    # racy parallel resolution. Failure here is user-facing — the package
    # likely declares a dependency we can't fetch.
    info("  Resolving package dependencies...")
    cp = subprocess.run(
        ["swift", "package", "resolve"],
        cwd=str(staged_dir),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    if cp.returncode != 0:
        # Surface the last 5 lines of stderr — same shape as the bash tool.
        tail = "\n".join((cp.stderr or "").rstrip().splitlines()[-5:])
        raise FetchError(
            "swift package resolve failed on the staged package:\n" + (tail or "  (no stderr)")
        )

    if removed_count and config.verbose:
        verbose_log(config.verbose, f"  Removed {removed_count} excluded path(s) from staged tree")

    return staged_dir


def discover_binary_artifacts(config: Config) -> List[BinaryArtifact]:
    """Resolve a binary-mode SPM shim and walk `.build/artifacts/` for
    xcframeworks. Used by binary mode instead of fetch_source + stage.

    Side effects: writes a shim Package.swift under
    `WORK_DIR/binary-resolve/`, runs `swift package resolve`, walks the
    resulting `.build/artifacts/` tree. The planner that consumes the
    returned list is still a pure function.

    Two structural fixes live here (bugs 1 and 3 in
    SPM_TO_XCFRAMEWORK_NOTES.md):

      1. The shim's `exact:` string is `config.user_version` with a
         leading "v" stripped. That's the bare semver SPM's resolver
         requires, regardless of whether the user typed "7.6.2" or
         "v7.6.2".
      2. `os.walk` prunes any `__MACOSX` directories before descending,
         so AppleDouble ghost xcframeworks never make it into the
         returned list.

    Session 2 only needs this for `--dry-run`. Session 4 will call it
    from the real Execute path; the function is intentionally shaped
    so the return value feeds straight into `plan_binary_build`.
    """
    assert config.work_dir is not None
    if not config.is_remote:
        raise FetchError("--binary requires a remote package URL.")
    if not config.user_version:
        raise FetchError("--binary requires --version.")

    shim_dir = config.work_dir / "binary-resolve"
    shim_dir.mkdir(parents=True, exist_ok=True)

    # Bug 1 fix: feed the bare semver, not the git-tag form. Strip a
    # leading "v" so `--version v7.6.2` also resolves cleanly.
    exact_version = config.user_version[1:] if config.user_version.startswith("v") else config.user_version

    # SPM resolve doesn't actually care about the version, but the
    # manifest needs to be self-consistent: one platform entry per
    # `--min-*` flag the user set, using the exact version string. The
    # string-form `.iOS("15.0")` sidesteps the `.v<major>` enum table
    # (`.macOS(.v10)` is not a real case for 10.15). Tools-version 5.9
    # is the floor that allows declaring `visionOS`.
    platform_entries = _spm_platform_entries(config)
    platforms_array = ", ".join(platform_entries) if platform_entries else ".iOS(\"15.0\")"

    manifest = (
        "// swift-tools-version:5.9\n"
        "import PackageDescription\n"
        "\n"
        "let package = Package(\n"
        '    name: "binary-resolver",\n'
        f"    platforms: [{platforms_array}],\n"
        "    dependencies: [\n"
        f'        .package(url: "{config.package_source}", exact: "{exact_version}"),\n'
        "    ],\n"
        "    targets: [\n"
        '        .target(name: "Dummy", path: "Sources"),\n'
        "    ]\n"
        ")\n"
    )
    (shim_dir / "Package.swift").write_text(manifest)
    sources_dir = shim_dir / "Sources"
    sources_dir.mkdir(parents=True, exist_ok=True)
    (sources_dir / "Dummy.swift").write_text("// placeholder\n")

    info(f"Resolving binary artifacts from {config.package_source} @ {exact_version}...")
    cp = subprocess.run(
        ["swift", "package", "resolve"],
        cwd=str(shim_dir),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    if cp.returncode != 0:
        tail = "\n".join((cp.stderr or "").rstrip().splitlines()[-10:])
        raise FetchError(
            "Failed to resolve binary package dependencies:\n"
            + (tail or "  (no stderr)")
        )

    artifacts_root = shim_dir / ".build" / "artifacts"
    if not artifacts_root.is_dir():
        raise FetchError(
            "No .build/artifacts directory after resolve — this package "
            "may not ship binary xcframeworks."
        )

    found: List[BinaryArtifact] = []
    for dirpath, dirnames, _filenames in os.walk(artifacts_root):
        # Bug 3 fix: prune __MACOSX ghosts before descending or matching.
        dirnames[:] = [d for d in dirnames if d != "__MACOSX"]
        # Collect .xcframework directories at the current level without
        # descending into them (they have their own internal structure
        # that we don't want to walk).
        remaining: List[str] = []
        for d in dirnames:
            if d.endswith(".xcframework"):
                name = d[: -len(".xcframework")]
                found.append(BinaryArtifact(product_name=name, path=Path(dirpath) / d))
            else:
                remaining.append(d)
        dirnames[:] = remaining

    if not found:
        raise FetchError(
            "No xcframeworks discovered under .build/artifacts/. "
            "Is this actually a binary-target SPM package?"
        )

    return found


# ============================================================================
# --- inspect.py ------------------------------------------------------------
# ============================================================================


import json
import subprocess
from pathlib import Path
from typing import Iterable, List, Optional, Tuple



def _swift_dump_package(staged_dir: Path) -> dict:
    """Run `swift package dump-package` against the staged dir and return
    the parsed JSON. Raises InspectError on any failure.
    """
    cp = subprocess.run(
        ["swift", "package", "dump-package"],
        cwd=str(staged_dir),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    if cp.returncode != 0:
        raise InspectError(
            "swift package dump-package failed:\n"
            + (cp.stderr or "  (no stderr)").rstrip()
            + "\nIs the swift-tools-version supported by your toolchain?"
        )
    try:
        return json.loads(cp.stdout)
    except json.JSONDecodeError as exc:
        raise InspectError(f"Could not parse dump-package JSON: {exc}") from exc


def _parse_tools_version(raw: object) -> str:
    """`toolsVersion` is a struct: {'_version': '6.1.0'}. Be lenient about
    older shapes that might have been a flat string."""
    if isinstance(raw, dict):
        v = raw.get("_version")
        if isinstance(v, str):
            return v
    if isinstance(raw, str):
        return raw
    return "unknown"


def _parse_platforms(raw: object) -> List[Platform]:
    out: List[Platform] = []
    if not isinstance(raw, list):
        return out
    for entry in raw:
        if not isinstance(entry, dict):
            continue
        out.append(
            Platform(
                name=str(entry.get("platformName", "")),
                version=str(entry.get("version", "")),
            )
        )
    return out


def _parse_linkage(type_field: object) -> Optional[str]:
    """SPM products have several shapes:
        {'library': ['automatic']}
        {'library': ['dynamic']}
        {'library': ['static']}
        {'executable': None}
        {'plugin': None}
        {'snippet': None}
    Returns the linkage as one of Linkage._VALUES, or None for non-library
    products (which we deliberately drop from the model since the tool only
    builds libraries).
    """
    if isinstance(type_field, dict):
        if "library" in type_field:
            inner = type_field["library"]
            if isinstance(inner, list) and inner:
                v = str(inner[0])
                if v in Linkage._VALUES:
                    return v
                return Linkage.UNKNOWN
            return Linkage.AUTOMATIC
        # Non-library product types — explicitly excluded from the model.
        if "executable" in type_field:
            return None
        if "plugin" in type_field:
            return None
        if "snippet" in type_field:
            return None
    # Older / unknown shape — log via UNKNOWN so the planner can decide.
    return Linkage.UNKNOWN


def _parse_target_kind(raw: object) -> str:
    if not isinstance(raw, str):
        return TargetKind.UNKNOWN
    return raw if raw in TargetKind._VALUES else TargetKind.UNKNOWN


def _parse_dependencies(raw: object) -> List[str]:
    """Targets list dependencies in several union shapes. We only need names
    here (the planner doesn't currently care about kind), so flatten and
    return string names. Unknown shapes are silently dropped."""
    out: List[str] = []
    if not isinstance(raw, list):
        return out
    for d in raw:
        if not isinstance(d, dict):
            continue
        # Common shapes:
        #   {"byName": ["X", null]}
        #   {"target": ["X", null]}
        #   {"product": ["X", "PkgName", null, null]}
        for key in ("byName", "target", "product"):
            v = d.get(key)
            if isinstance(v, list) and v and isinstance(v[0], str):
                out.append(v[0])
                break
    return out


def _raw_internal_dep_names(raw_target: dict) -> List[str]:
    """Return the first-level INTERNAL target-name deps of a raw dump-package
    target entry. "Internal" means same-package targets — i.e. the
    `byName` and `target` shapes, NOT the `product` shape (which refers
    to another package entirely and whose targets we can't reach).

    Used by dependency-walking code that needs to scan raw dump entries
    directly (e.g. `_find_objc_headers_dir`) rather than the typed
    `Target.dependencies` list. Those callers need the raw entries for
    other fields (settings, publicHeadersPath, …), so they can't just
    reuse `_parse_dependencies` on the typed model.

    Order-preserving; duplicates are kept in source order because both
    callers iterate and de-dupe with their own `scanned` sets.
    """
    out: List[str] = []
    for dep in raw_target.get("dependencies", []) or []:
        if not isinstance(dep, dict):
            continue
        for key in ("byName", "target"):
            v = dep.get(key)
            if isinstance(v, list) and v and isinstance(v[0], str):
                out.append(v[0])
                break
    return out


def dump_package(staged_dir: Path) -> Tuple[dict, List[Product], List[Target], List[Platform], str, str]:
    """Run dump-package and parse it into typed shards. Returns
    (raw_dump, products, targets, platforms, name, tools_version).

    Splitting this from build_package() lets the self-test fixtures feed
    in pre-canned dump payloads without invoking the swift toolchain.
    """
    raw = _swift_dump_package(staged_dir)
    return _parse_dump(raw)


def _parse_dump(raw: dict) -> Tuple[dict, List[Product], List[Target], List[Platform], str, str]:
    name = str(raw.get("name") or "")
    tools_version = _parse_tools_version(raw.get("toolsVersion"))
    platforms = _parse_platforms(raw.get("platforms"))

    products: List[Product] = []
    for prod in raw.get("products", []) or []:
        if not isinstance(prod, dict):
            continue
        linkage = _parse_linkage(prod.get("type"))
        if linkage is None:
            # Non-library product — skip entirely. Plan only ever builds libraries.
            continue
        targets = [str(t) for t in (prod.get("targets") or []) if isinstance(t, str)]
        products.append(Product(name=str(prod.get("name") or ""), linkage=linkage, targets=targets))

    targets: List[Target] = []
    for t in raw.get("targets", []) or []:
        if not isinstance(t, dict):
            continue
        targets.append(
            Target(
                name=str(t.get("name") or ""),
                kind=_parse_target_kind(t.get("type")),
                path=t.get("path") if isinstance(t.get("path"), str) else None,
                public_headers_path=(
                    t.get("publicHeadersPath")
                    if isinstance(t.get("publicHeadersPath"), str)
                    else None
                ),
                dependencies=_parse_dependencies(t.get("dependencies")),
                exclude=[str(e) for e in (t.get("exclude") or []) if isinstance(e, str)],
            )
        )

    return raw, products, targets, platforms, name, tools_version


# SPM `describe --type json` reports each target's classification as
# `module_type`. This is the same enum SwiftPM uses internally to drive
# the build, so it's strictly more authoritative than walking the
# source tree: a target declared with `.target()` is SwiftTarget even
# when the directory contains a stub umbrella `.h` Xcode auto-generated,
# which is exactly the umbrella-stub case the old FS scanner needed
# heuristics to avoid mis-classifying as Mixed.
#
# Module types not in this map (BinaryTarget, SystemLibraryTarget,
# PluginTarget, MacroTarget, …) collapse to Language.NA — none of them
# are candidate source-build units. MixedLanguageTarget is the shape
# SwiftPM accepts for the experimental mixed-language feature; today
# the SPM frontend rejects mixed-language source dirs outright, but the
# mapping is here so the moment SwiftPM enables it for real we already
# classify correctly.
_MODULE_TYPE_LANGUAGE = {
    "SwiftTarget": Language.SWIFT,
    "ClangTarget": Language.OBJC,
    "MixedLanguageTarget": Language.MIXED,
}


def _swift_describe_package(staged_dir: Path) -> dict:
    """Run `swift package describe --type json` against the staged dir
    and return the parsed JSON. Raises InspectError on any failure.

    describe is SPM's own per-target view of the resolved package —
    `module_type` and `sources` come from the same code path that drives
    the build, so the classification matches what `xcodebuild` will see.
    """
    cp = subprocess.run(
        ["swift", "package", "describe", "--type", "json"],
        cwd=str(staged_dir),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    if cp.returncode != 0:
        raise InspectError(
            "swift package describe failed:\n"
            + (cp.stderr or "  (no stderr)").rstrip()
        )
    try:
        return json.loads(cp.stdout)
    except json.JSONDecodeError as exc:
        raise InspectError(f"Could not parse describe JSON: {exc}") from exc


def scan_target_languages(staged_dir: Path, targets: Iterable[Target]) -> None:
    """Label each target's `language` and `source_file_count` from the
    output of `swift package describe --type json`.

    Mutates the Target instances in place. Targets with kind SYSTEM /
    BINARY / PLUGIN / MACRO / TEST keep Language.NA — none of them are
    candidate source-build units. Targets describe doesn't enumerate
    (or whose `module_type` falls outside `_MODULE_TYPE_LANGUAGE`)
    also stay at NA.
    """
    described = _swift_describe_package(staged_dir)
    by_name: dict = {}
    for entry in described.get("targets", []) or []:
        if isinstance(entry, dict) and isinstance(entry.get("name"), str):
            by_name[entry["name"]] = entry

    for tgt in targets:
        if tgt.kind in (
            TargetKind.SYSTEM,
            TargetKind.BINARY,
            TargetKind.PLUGIN,
            TargetKind.MACRO,
            TargetKind.TEST,
        ):
            tgt.language = Language.NA
            continue
        entry = by_name.get(tgt.name)
        if not entry:
            tgt.language = Language.NA
            continue
        module_type = entry.get("module_type")
        tgt.language = _MODULE_TYPE_LANGUAGE.get(module_type, Language.NA)
        sources = entry.get("sources")
        tgt.source_file_count = len(sources) if isinstance(sources, list) else 0


def discover_schemes(staged_dir: Path, verbose: bool = False) -> List[str]:
    """Run `xcodebuild -list -json` against the staged dir.

    Because staging strips xcodeproj/xcworkspace, this returns the SPM
    auto-generated scheme list with no multi-project ambiguity (bug 4 in
    SPM_TO_XCFRAMEWORK_NOTES.md). On any failure, returns an empty list
    and lets the planner fall back to product-name schemes — Inspect
    never raises here, since some packages legitimately have nothing
    xcodebuild can list (very old swift-tools-version, etc.).

    `verbose=True` logs the xcodebuild stderr tail so users can tell the
    difference between "no schemes" and "scheme discovery failed".
    """
    cp = subprocess.run(
        ["xcodebuild", "-list", "-json"],
        cwd=str(staged_dir),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    if cp.returncode != 0:
        if verbose:
            tail = "\n".join((cp.stderr or "").rstrip().splitlines()[-5:])
            verbose_log(verbose, f"  xcodebuild -list failed: {tail}")
        return []

    try:
        data = json.loads(cp.stdout)
    except json.JSONDecodeError as exc:
        verbose_log(verbose, f"  xcodebuild -list returned non-JSON: {exc}")
        return []

    container = data.get("workspace") or data.get("project") or {}
    schemes = container.get("schemes") or []
    return [str(s) for s in schemes if isinstance(s, str)]


def _collect_referenced_package_products(
    raw_dump: dict, targets: List[Target]
) -> "dict[str, dict]":
    """Enumerate the `.product(name:, package:)` references that any
    REGULAR target in the root package makes against external packages,
    keyed by SPM identity.

    Filtering to REGULAR targets matches what the planner ultimately builds
    — test/macro/plugin targets are never built as xcframeworks, so we
    don't want their transitive product deps to drive patching of foreign
    checkouts. The dump-package shape we look for is:

        {"product": ["ProductName", "package-identity", null, null]}

    Returns an ordered dict keyed by identity. Each value is a dict with:
      - "products": ordered list of distinct product names the root
        referenced from this identity (used to scope the child build via
        `Config.product_filters` and to drive prune_child's needed-
        identity closure).
      - "root_targets": ordered list of distinct root REGULAR target
        names that reference this identity (used by the orchestrator to
        drop transitives reachable only from helper/example targets
        outside the user's selected-target closure).
      - "product_to_root_targets": dict from product name to ordered
        list of root REGULAR target names that reference that specific
        product. Preserves the fine-grained edge attribution the two
        aggregate lists above lose, so the orchestrator can trim
        `referenced_products` down to only the products imported by
        in-closure root targets.
    """
    target_kind_by_name = {t.name: t.kind for t in targets}
    by_identity: "dict[str, dict]" = {}
    for t in raw_dump.get("targets", []) or []:
        if not isinstance(t, dict):
            continue
        name = t.get("name")
        if not isinstance(name, str):
            continue
        if target_kind_by_name.get(name) != TargetKind.REGULAR:
            continue
        for dep in t.get("dependencies", []) or []:
            if not isinstance(dep, dict):
                continue
            prod = dep.get("product")
            if not isinstance(prod, list) or len(prod) < 2:
                continue
            product_name = prod[0]
            identity = prod[1]
            if not isinstance(identity, str) or not isinstance(product_name, str):
                continue
            entry = by_identity.setdefault(
                identity,
                {"products": [], "root_targets": [], "product_to_root_targets": {}},
            )
            if product_name not in entry["products"]:
                entry["products"].append(product_name)
            if name not in entry["root_targets"]:
                entry["root_targets"].append(name)
            per_product = entry["product_to_root_targets"].setdefault(
                product_name, []
            )
            if name not in per_product:
                per_product.append(name)
    return by_identity


def _show_dependencies(staged_dir: Path, verbose: bool) -> Optional[dict]:
    """Run `swift package show-dependencies --format json` to get the
    resolved dependency tree (each entry has identity, version, and the
    on-disk `path` to the checkout). Returns the parsed JSON or None on
    failure (treated as "no transitive packages" — Plan/Prepare gracefully
    no-op).
    """
    cp = subprocess.run(
        ["swift", "package", "show-dependencies", "--format", "json"],
        cwd=str(staged_dir),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    if cp.returncode != 0:
        verbose_log(
            verbose,
            f"  swift package show-dependencies failed: "
            f"{(cp.stderr or '').rstrip().splitlines()[-3:]}",
        )
        return None
    try:
        return json.loads(cp.stdout)
    except json.JSONDecodeError as exc:
        verbose_log(verbose, f"  show-dependencies JSON parse failed: {exc}")
        return None


def _flatten_dependency_tree(tree: dict) -> dict:
    """Walk the `show-dependencies` JSON (which is recursive) and return a
    flat dict mapping identity → checkout path string for every node
    reachable from the root. The root itself is excluded — only its
    transitive deps appear.
    """
    flat: dict = {}

    def walk(node: dict) -> None:
        deps = node.get("dependencies") or []
        for dep in deps:
            if not isinstance(dep, dict):
                continue
            identity = dep.get("identity")
            path = dep.get("path")
            if isinstance(identity, str) and isinstance(path, str):
                if identity not in flat:
                    flat[identity] = path
            walk(dep)

    walk(tree)
    return flat


def _discover_transitive_packages(
    staged_dir: Path,
    raw_dump: dict,
    targets: List[Target],
    verbose: bool,
) -> List[TransitivePackageInfo]:
    """Enumerate the direct external-package deps of the root's REGULAR
    targets, look up each one's resolved checkout, and dump-package the
    checkout to get its products list. Returns one
    `TransitivePackageInfo` per directly-referenced identity; packages
    pulled in only by test/macro/plugin paths are skipped at the source.

    Failure modes (each results in skipping the affected identity, never
    a hard error):
      - show-dependencies returns no entry for the identity (e.g. the
        package wasn't fully resolved)
      - the checkout's `dump-package` fails (rare — would mean the
        package author shipped a broken manifest)
    """
    referenced_by_identity = _collect_referenced_package_products(raw_dump, targets)
    if not referenced_by_identity:
        return []

    tree = _show_dependencies(staged_dir, verbose=verbose)
    if tree is None:
        return []
    flat = _flatten_dependency_tree(tree)
    if not flat:
        return []

    # Case-insensitive identity lookup so root manifests that write
    # `package: "Swift-Clocks"` still match the SPM-normalised
    # "swift-clocks" identity.
    flat_ci = {k.lower(): (k, v) for k, v in flat.items()}

    out: List[TransitivePackageInfo] = []
    for ref, ref_entry in referenced_by_identity.items():
        ref_products = ref_entry["products"]
        ref_root_targets = ref_entry["root_targets"]
        ref_p2rt = ref_entry["product_to_root_targets"]
        match = flat_ci.get(ref.lower())
        if match is None:
            verbose_log(
                verbose,
                f"  transitive: identity {ref!r} referenced by root but "
                f"not present in show-dependencies output (skipping)",
            )
            continue
        identity, checkout_str = match
        checkout_path = Path(checkout_str)
        if not (checkout_path / "Package.swift").is_file() and not any(
            checkout_path.glob("Package@swift-*.swift")
        ):
            verbose_log(
                verbose,
                f"  transitive: {identity!r} at {checkout_path} has no "
                f"Package.swift (skipping)",
            )
            continue
        try:
            t_raw, t_products, _t_targets, _t_platforms, _t_name, t_tools = (
                dump_package(checkout_path)
            )
        except Exception as exc:  # noqa: BLE001 — Inspect must not crash
            verbose_log(
                verbose,
                f"  transitive: dump-package failed for {identity!r}: {exc}",
            )
            continue
        out.append(
            TransitivePackageInfo(
                identity=identity,
                checkout_path=checkout_path,
                products=t_products,
                tools_version=t_tools,
                referenced_products=list(ref_products),
                referencing_root_targets=list(ref_root_targets),
                product_to_root_targets={
                    p: list(rts) for p, rts in ref_p2rt.items()
                },
            )
        )
    return out


def inspect_package(config: Config, staged_dir: Path) -> Package:
    """Top-level Inspect entry point. Reads only — no filesystem mutations
    on the staged tree. Wires together dump_package + scan + scheme list."""
    info("Inspecting package...")
    raw, products, targets, platforms, name, tools_version = dump_package(staged_dir)
    scan_target_languages(staged_dir, targets)
    schemes = discover_schemes(staged_dir, verbose=config.verbose)
    transitive = _discover_transitive_packages(
        staged_dir, raw, targets, verbose=config.verbose
    )
    return Package(
        name=name,
        tools_version=tools_version,
        platforms=platforms,
        products=products,
        targets=targets,
        schemes=schemes,
        raw_dump=raw,
        staged_dir=staged_dir,
        transitive_packages=transitive,
    )


def print_package(pkg: Package) -> None:
    """Human-readable Package summary, used by --inspect-only."""
    bold(f"\n=== {pkg.name} ===")
    print(f"  tools-version: {pkg.tools_version}")
    if pkg.platforms:
        plats = ", ".join(f"{p.name} {p.version}" for p in pkg.platforms)
        print(f"  platforms:     {plats}")
    print(f"  staged dir:    {pkg.staged_dir}")
    print(f"  schemes:       {', '.join(pkg.schemes) if pkg.schemes else '(none discovered)'}")

    bold(f"\nProducts ({len(pkg.products)}):")
    if not pkg.products:
        print("  (none)")
    for p in pkg.products:
        # Cross-reference each product's backing targets to flag system /
        # already-dynamic shapes the planner will care about.
        kinds = []
        for tname in p.targets:
            t = pkg.target_by_name(tname)
            kinds.append(t.kind if t else "?")
        notes = []
        if p.linkage == Linkage.DYNAMIC:
            notes.append("already dynamic")
        if all(k == TargetKind.SYSTEM for k in kinds) and kinds:
            notes.append("system-only — will be skipped")
        note_s = f"  [{', '.join(notes)}]" if notes else ""
        print(
            f"  - {p.name}  linkage={p.linkage}  targets={p.targets}{note_s}"
        )

    bold(f"\nTargets ({len(pkg.targets)}):")
    for t in pkg.targets:
        path_disp = t.path or "(default)"
        hdr = f" headers={t.public_headers_path}" if t.public_headers_path else ""
        print(
            f"  - {t.name}  kind={t.kind}  language={t.language}"
            f"  path={path_disp}{hdr}  files={t.source_file_count}"
        )


# ============================================================================
# --- plan.py ---------------------------------------------------------------
# ============================================================================


import os
from typing import Dict, List, Optional, Sequence, Set, Tuple



def resolve_scheme(product_name: str, schemes: Sequence[str]) -> str:
    """Pick the best scheme for `product_name` out of the discovered list.

    Resolution order (design §5.2 rule 4, plus the session-1 inversion
    noted in the Session 2 brief: prefer the literal name over the
    `-Package` form when both exist):

      1. exact match
      2. case-insensitive exact match
      3. `<product>-Package`
      4. `<product> iOS`, `<product>-iOS`, `<product> (iOS)`
      5. fall back to `product_name` unchanged — xcodebuild will
         auto-generate the SPM scheme at build time, which works
         against our clean staged directory.
    """
    if not schemes:
        return product_name
    # 1. exact
    if product_name in schemes:
        return product_name
    # 2. case-insensitive exact
    lowered = {s.lower(): s for s in schemes}
    if product_name.lower() in lowered:
        return lowered[product_name.lower()]
    # 3. <product>-Package
    pkg_form = f"{product_name}-Package"
    if pkg_form in schemes:
        return pkg_form
    # 4. iOS-suffix variants
    for suffix in (" iOS", "-iOS", " (iOS)"):
        candidate = product_name + suffix
        if candidate in schemes:
            return candidate
    # 5. fall back to product name
    return product_name


def _derive_product_language(product: Product, package: Package) -> str:
    """Union of all backing target languages → one of Language._VALUES.

    Rules (design §5.2 item 6):
      Swift + Swift        → Swift
      ObjC  + ObjC         → ObjC
      Swift + ObjC         → Mixed
      anything + Mixed     → Mixed
      nothing classified   → N/A
    """
    has_swift = False
    has_objc = False
    has_mixed = False
    for tname in product.targets:
        t = package.target_by_name(tname)
        if t is None:
            continue
        if t.language == Language.SWIFT:
            has_swift = True
        elif t.language == Language.OBJC:
            has_objc = True
        elif t.language == Language.MIXED:
            has_mixed = True
    if has_mixed or (has_swift and has_objc):
        return Language.MIXED
    if has_swift:
        return Language.SWIFT
    if has_objc:
        return Language.OBJC
    return Language.NA


def _is_system_only_product(product: Product, package: Package) -> bool:
    """True iff every backing target of `product` is TargetKind.SYSTEM.

    This is the rule for dropping a product entirely (design §5.2 rule 2 +
    bug 5 in SPM_TO_XCFRAMEWORK_NOTES.md). An empty target list is NOT
    considered system-only — that's a malformed product, not a system
    wrapper, and we leave it to xcodebuild to complain.
    """
    if not product.targets:
        return False
    for tname in product.targets:
        t = package.target_by_name(tname)
        if t is None or t.kind != TargetKind.SYSTEM:
            return False
    return True


def _is_binary_only_product(product: Product, package: Package) -> bool:
    """True iff every backing target of `product` is TargetKind.BINARY.

    Such a product is backed entirely by `binaryTarget(...)` entries —
    SPM does not allow an explicit `type: .dynamic` on it ("invalid type
    for binary product; products referencing only binary targets must be
    executable or automatic library products"). The source-mode planner
    uses this to suppress the synthetic-dynamic-library injection for
    those products, and `_package_is_binary_only` uses it to recognise
    packages that
    should be handled by `--binary` mode instead of source mode.
    Empty target list returns False — same convention as
    `_is_system_only_product` (treat malformed products as not-binary
    and let xcodebuild surface the real problem).
    """
    if not product.targets:
        return False
    for tname in product.targets:
        t = package.target_by_name(tname)
        if t is None or t.kind != TargetKind.BINARY:
            return False
    return True


def _package_is_binary_only(package: Package) -> bool:
    """True iff every (non-system) product in `package` is backed only by
    binaryTarget targets.

    Source-mode planning for such a package would fail at SPM resolve
    time because the unconditional synthetic-dynamic-library injection
    produces `.library(..., type: .dynamic, targets: [<binary>])`, which
    SPM rejects. The caller switches transparently to `--binary` mode when
    this returns True. System-only products are skipped from the check
    (the planner drops them anyway), so a package with one binary
    library + one system-shim library still counts as binary-only.
    Packages with zero products return False — there's nothing for
    binary mode to discover either.
    """
    binary_products = 0
    for product in package.products:
        if _is_system_only_product(product, package):
            continue
        if not _is_binary_only_product(product, package):
            return False
        binary_products += 1
    return binary_products > 0


def compute_internal_target_deps(package: Package) -> Dict[str, Set[str]]:
    """For every target in `package`, return the set of TRANSITIVELY
    reachable internal target names — i.e. names that are also defined
    as targets in the same `Package.swift`.

    Walks the raw `dump-package` payload (`package.raw_dump`) rather
    than the typed `Target.dependencies` list, because the typed
    flattening (`_parse_dependencies`) collapses `byName`, `target`,
    AND `product` shapes into a single name list. That collapse loses
    the kind information we need here: a `.product("Foo", ...)`
    cross-package import has the same flat-name shape as a
    `.byName("Foo")` internal sibling, so a name collision between an
    external SPM product and a local target name would silently
    register a false internal edge. (Codex P2 regression.)

    Internal-only walk: only `byName` and `target` shapes from the raw
    dump count — those are the SPM dependency expressions that
    definitionally point inside the same package. `product` deps are
    skipped even if their name happens to match an internal target.
    External non-collision `product` deps are also filtered by virtue
    of the membership check against `internal_names`.

    Cycles are tolerated (the dump-package model shouldn't permit
    them, but the visited set guards against bad inputs anyway). The
    reflexive self-edge is excluded from the returned set so callers
    can iterate `deps_map[T]` without a separate "is this myself"
    check.

    Pure function over typed inputs — used by `topo_order_units` and
    the Execute-time dedup-overlap substitution loop.
    """
    internal_names = {t.name for t in package.targets}

    raw_targets_by_name: Dict[str, dict] = {}
    for raw_t in package.raw_dump.get("targets", []) or []:
        if not isinstance(raw_t, dict):
            continue
        nm = raw_t.get("name")
        if isinstance(nm, str):
            raw_targets_by_name[nm] = raw_t

    direct: Dict[str, List[str]] = {}
    for t in package.targets:
        raw_t = raw_targets_by_name.get(t.name)
        if raw_t is None:
            # Target was in the typed list but not in the raw dump — a
            # synthetic-library injection or test-fixture quirk. Treat
            # as having no internal deps; planner-driven sibling
            # discovery happens elsewhere.
            direct[t.name] = []
            continue
        deps: List[str] = []
        seen: Set[str] = set()
        for name in _raw_internal_dep_names(raw_t):
            if name == t.name:
                continue
            if name not in internal_names:
                continue
            if name in seen:
                continue
            seen.add(name)
            deps.append(name)
        direct[t.name] = deps

    cache: Dict[str, Set[str]] = {}

    def reachable(name: str, stack: Set[str]) -> Set[str]:
        if name in cache:
            return cache[name]
        if name in stack:
            return set()
        stack.add(name)
        out: Set[str] = set()
        for d in direct.get(name, []):
            out.add(d)
            out |= reachable(d, stack)
        stack.discard(name)
        out.discard(name)
        cache[name] = out
        return out

    return {t.name: reachable(t.name, set()) for t in package.targets}


def topo_order_units(
    units: Sequence[BuildUnit], package: Package
) -> List[BuildUnit]:
    """Order `units` so each one comes after every sibling unit it
    transitively depends on (via internal target deps). Stable on
    original index — units with no dependency relation between them keep
    their planner-assigned order.

    Unit-level dependency relation: unit U depends on unit V iff some
    target name in `V.source_targets` is in the transitive internal
    target dep closure of `U.source_targets`. Derived from
    `compute_internal_target_deps(package)`.

    This is the order Execute walks for dedup-overlap substitution: leaf
    products (StripeCore) build first, umbrella products (Stripe) build
    last with their already-built sibling targets swapped to
    `.binaryTarget`. See REWRITE_DESIGN.md §5.4 dedup-overlap.

    On a cycle in the unit graph (which would indicate a bad
    dump-package payload), remaining units are appended in original
    order so behavior stays deterministic instead of raising.
    """
    deps_map = compute_internal_target_deps(package)
    n = len(units)
    if n <= 1:
        return list(units)

    target_to_unit_idx: Dict[str, int] = {}
    for idx, u in enumerate(units):
        for t in u.source_targets:
            target_to_unit_idx[t] = idx

    # Edge i -> j  means unit i must come before unit j.
    children: List[List[int]] = [[] for _ in range(n)]
    in_degree: List[int] = [0] * n
    edges_seen: Set[Tuple[int, int]] = set()
    for j, u in enumerate(units):
        reach: Set[str] = set()
        for t in u.source_targets:
            reach |= deps_map.get(t, set())
        for t in reach:
            i = target_to_unit_idx.get(t)
            if i is None or i == j:
                continue
            if (i, j) in edges_seen:
                continue
            edges_seen.add((i, j))
            children[i].append(j)
            in_degree[j] += 1

    ready = sorted(i for i in range(n) if in_degree[i] == 0)
    out: List[BuildUnit] = []
    while ready:
        i = ready.pop(0)
        out.append(units[i])
        for j in children[i]:
            in_degree[j] -= 1
            if in_degree[j] == 0:
                # Insert j keeping `ready` sorted by original index.
                lo, hi = 0, len(ready)
                while lo < hi:
                    mid = (lo + hi) // 2
                    if ready[mid] < j:
                        lo = mid + 1
                    else:
                        hi = mid
                ready.insert(lo, j)

    if len(out) < n:
        seen = {id(u) for u in out}
        for u in units:
            if id(u) not in seen:
                out.append(u)
    return out


def _allocate_synthetic_product_name(
    base: str, taken: Set[str]
) -> str:
    """Compute a non-colliding synthetic product name for the dynamic
    re-export of `base`.

    Tries `f"{base}Dynamic"` first. If that collides with an existing or
    already-allocated product name (Alamofire ships both `Alamofire` and
    `AlamofireDynamic`, the latter would clash), falls back to
    `f"{base}__Dynamic"`, then `f"{base}__Dynamic2"`, `__Dynamic3`, … —
    the double-underscore disambiguator is unusual enough that it will
    almost never trip a real package's product list, and the numeric
    tail handles the pathological case where even that exists.

    Mutates `taken` in place — callers should pass the same set across
    all emissions in a single planning pass so two products that would
    each prefer `XDynamic` don't both allocate it.
    """
    primary = f"{base}Dynamic"
    if primary not in taken:
        taken.add(primary)
        return primary
    candidate = f"{base}__Dynamic"
    if candidate not in taken:
        taken.add(candidate)
        return candidate
    i = 2
    while True:
        candidate = f"{base}__Dynamic{i}"
        if candidate not in taken:
            taken.add(candidate)
            return candidate
        i += 1


def _validate_requested_platforms(config: Config, package: Package) -> None:
    """Fail fast if the user asked for a platform the package doesn't
    declare. SPM treats an empty `platforms:` array as "all platforms",
    so we only enforce when the package's list is non-empty.
    """
    if not package.platforms:
        return
    declared = {p.name.lower() for p in package.platforms}
    requested = _enabled_platforms(config)
    missing = [p for p in requested if p not in declared]
    if missing:
        decl = ", ".join(sorted(declared)) or "(none)"
        raise PlanError(
            f"Requested platform(s) not declared by the package: "
            f"{', '.join(missing)}. Package declares: {decl}."
        )


def plan_source_build(config: Config, package: Package) -> Plan:
    """Pure planner for source-mode builds.

    Takes the inspected Package and the user's Config and returns a Plan
    describing (a) the Package.swift edits Prepare should apply, (b) the
    list of build units Execute should run, and (c) the list of products
    the planner consciously skipped with a reason. See REWRITE_DESIGN.md
    §5.2 for the full rule set.
    """
    _validate_requested_platforms(config, package)
    plan = Plan()
    plan.include_deps = config.include_deps

    product_filter: Optional[Set[str]] = (
        set(config.product_filters) if config.product_filters else None
    )
    product_filter_matches: Set[str] = set()

    # Names that are off-limits for synthetic product allocation: every
    # existing product (the static + already-dynamic sibling case), plus
    # any synthetic name we hand out earlier in this pass.
    taken_product_names: Set[str] = {p.name for p in package.products}

    # First pass: walk the package products. Three possible outcomes per
    # product: (a) filtered out by --product, (b) dropped because it's a
    # system-library wrapper, (c) promoted to a build unit.
    for product in package.products:
        if product_filter is not None and product.name not in product_filter:
            continue
        if product_filter is not None:
            product_filter_matches.add(product.name)

        if _is_system_only_product(product, package):
            plan.skipped.append((product.name, "system-library product"))
            continue

        # Binary-only products in a *mixed* package are skipped entirely
        # from source-mode planning. The pure-binary whole-package case is
        # already auto-routed to --binary mode by `_run_source_mode` (we
        # never enter this loop for that input). What's left is the rarer
        # mixed shape — e.g. one .library backed by `binaryTarget` plus
        # other .libraries backed by Swift/ObjC source — where:
        #   - Adding a synthetic dynamic library against a binaryTarget
        #     would trigger SPM's "invalid type for binary product" error
        #     and abort the whole package.
        #   - Emitting an `archive` BuildUnit would push xcodebuild at a
        #     scheme that produces no source artefact; it can't build
        #     a binaryTarget-backed product as a fresh framework, only
        #     consume the prebuilt artefact as a dependency.
        # Source mode therefore can't service the binary product. We drop
        # it with a clear reason; users who want it should switch to
        # --binary or consume the upstream xcframework directly.
        if _is_binary_only_product(product, package):
            plan.skipped.append(
                (product.name, "binary-only product (use --binary mode)")
            )
            continue

        # Source-mode dynamic strategy — only when the product isn't
        # already dynamic. The Alamofire/GRDB-dynamic invariant from
        # Session 2: planning both GRDB and GRDB-dynamic is correct;
        # adding a synthetic dynamic library for the already-dynamic
        # sibling is not.
        language = _derive_product_language(product, package)
        if product.linkage != Linkage.DYNAMIC:
            # Add a synthetic dynamic .library that re-exports the same
            # targets, then build it and rename the output framework to
            # the original product name. Replaces the legacy
            # force_dynamic surgery; lets us drive everything through
            # `swift package add-product` instead of regex editing.
            synthetic_name = _allocate_synthetic_product_name(
                product.name, taken_product_names
            )
            plan.package_swift_edits.append(
                PackageSwiftEdit(
                    kind="synth_dynamic_library",
                    product_name=synthetic_name,
                    targets=list(product.targets),
                )
            )
            scheme = synthetic_name
        else:
            scheme = resolve_scheme(product.name, package.schemes)
        plan.build_units.append(
            BuildUnit(
                name=product.name,
                scheme=scheme,
                framework_name=product.name,
                language=language,
                archive_strategy="archive",
                source_targets=list(product.targets),
                synthetic=False,
            )
        )

    # Second pass: --target escape hatch. For each requested target we
    # synthesize a fresh .library() entry unless one already exists with
    # the same name (in which case we use the existing one and warn).
    existing_product_names = {p.name for p in package.products}
    existing_planned_names = {bu.name for bu in plan.build_units}
    for target_name in config.target_filters:
        tgt = package.target_by_name(target_name)
        if tgt is None:
            raise PlanError(
                f"--target {target_name!r}: no such target in package "
                f"(available: {sorted(t.name for t in package.targets)})"
            )
        if tgt.kind in (TargetKind.SYSTEM, TargetKind.BINARY,
                        TargetKind.PLUGIN, TargetKind.MACRO):
            raise PlanError(
                f"--target {target_name!r}: target kind is {tgt.kind!r}; "
                "only regular source targets can be synthesized into a "
                ".library() product."
            )
        if tgt.kind == TargetKind.TEST:
            raise PlanError(
                f"--target {target_name!r}: test targets cannot be built "
                "as xcframeworks."
            )
        if tgt.kind == TargetKind.EXECUTABLE:
            # Reject up front so this turns into a clean PlanError instead
            # of dying later inside Prepare when the synthesized
            # .library(…, targets: [executable]) fails the round-trip
            # dump-package validation. Matches the other excluded kinds
            # above and gives a clearer error message (Codex [P2]).
            raise PlanError(
                f"--target {target_name!r}: target kind is {tgt.kind!r}; "
                "executable targets cannot be built as xcframeworks. "
                "Pass a regular source target instead."
            )

        if target_name in existing_product_names:
            plan.warnings.append(
                f"--target {target_name}: already exposed as a .library() "
                "product; using the existing product instead of synthesizing "
                "a duplicate."
            )
            # If the existing product wasn't already planned (e.g. it was
            # filtered out by --product), surface it now — the user's
            # explicit --target is a stronger signal than --product.
            if target_name not in existing_planned_names:
                existing = next(p for p in package.products if p.name == target_name)
                if _is_system_only_product(existing, package):
                    raise PlanError(
                        f"--target {target_name!r}: existing product has "
                        "only system targets and cannot be built."
                    )
                if _is_binary_only_product(existing, package):
                    # Mirrors the first-pass skip above: an existing
                    # binary-only product surfaced via --target cannot be
                    # source-built. Record the skip and continue so the
                    # rest of the --target pass still processes other
                    # requested targets.
                    plan.skipped.append(
                        (existing.name, "binary-only product (use --binary mode)")
                    )
                    continue
                language = _derive_product_language(existing, package)
                if existing.linkage != Linkage.DYNAMIC:
                    synthetic_name = _allocate_synthetic_product_name(
                        existing.name, taken_product_names
                    )
                    plan.package_swift_edits.append(
                        PackageSwiftEdit(
                            kind="synth_dynamic_library",
                            product_name=synthetic_name,
                            targets=list(existing.targets),
                        )
                    )
                    scheme = synthetic_name
                else:
                    scheme = resolve_scheme(existing.name, package.schemes)
                plan.build_units.append(
                    BuildUnit(
                        name=existing.name,
                        scheme=scheme,
                        framework_name=existing.name,
                        language=language,
                        archive_strategy="archive",
                        source_targets=list(existing.targets),
                        synthetic=False,
                    )
                )
                existing_planned_names.add(existing.name)
                if product_filter is not None:
                    product_filter_matches.add(existing.name)
            continue

        # Repeated --target T on the command line must not synthesize
        # the same .library() twice — the second pass would produce a
        # duplicate PackageSwiftEdit and a duplicate BuildUnit that
        # later phases would either trip over or silently double-build.
        # Record a warning and move on. (Codex [P2] coverage gap.)
        if target_name in existing_planned_names:
            plan.warnings.append(
                f"--target {target_name}: specified more than once; "
                "ignoring the duplicate."
            )
            continue

        # Synthesize. Package.swift edit + build unit, both tagged with
        # synthetic=True for display purposes. The build unit's language
        # comes from the target itself (there's no "union" — it's one
        # target).
        # By construction `target_name` is NOT an existing product name
        # (the existing-product branch above already returned), so a
        # direct add-product call won't collide; record the allocation in
        # `taken_product_names` so a later first-pass synthetic doesn't
        # try to reuse it.
        taken_product_names.add(target_name)
        plan.package_swift_edits.append(
            PackageSwiftEdit(
                kind="synth_library",
                product_name=target_name,
                targets=[target_name],
            )
        )
        language = tgt.language if tgt.language in (
            Language.SWIFT, Language.OBJC, Language.MIXED
        ) else Language.NA
        plan.build_units.append(
            BuildUnit(
                name=target_name,
                scheme=target_name,
                framework_name=target_name,
                language=language,
                archive_strategy="archive",
                source_targets=[target_name],
                synthetic=True,
            )
        )
        existing_planned_names.add(target_name)

    # --product filter validation: if the user asked for something we
    # never saw, fail loudly. The synthetic pass may have broadened the
    # effective match set, so do this check last.
    if product_filter is not None:
        unmatched = sorted(product_filter - product_filter_matches)
        if unmatched:
            available = sorted(p.name for p in package.products)
            raise PlanError(
                f"--product filter matched no products: {unmatched}\n"
                f"Available products: {available}"
            )

    # Third pass: auto-discover statically-linked sibling targets. For
    # each planned unit, compute the transitive internal-target-dep
    # closure; any target in that closure that isn't already owned by a
    # planned unit gets its own build unit (and Package.swift edit).
    # Dedup-overlap (Execute) then rewrites the umbrella's manifest to
    # consume the siblings as `.binaryTarget`s, so the umbrella's
    # framework dynamically links to them instead of statically embedding
    # them. Without this, an umbrella that `@_exported import`s siblings
    # (swift-collections: Collections re-exports BitCollections,
    # DequeModule, ...) emits an xcframework whose `.swiftinterface`
    # references siblings whose `.swiftmodule` isn't anywhere on the
    # consumer's module search path, so `import Collections` fails to
    # type-check.
    #
    # Wrapper-style manifests (`CustomTarget`/`.toTarget()` —
    # canonical: swift-collections) used to bail here because the
    # textual dedup-overlap rewriter couldn't distinguish
    # `Target.target(...)` from `CustomTarget.target(...)`. They now
    # take an alternate Execute-time path (`edit_inject_or_extend_overlay_binary_targets`)
    # that intervenes at the `Package(targets: <expr>)` boundary
    # instead — sidestepping the wrapper entirely. So planning
    # proceeds the same way for both shapes.
    _auto_synth_sibling_units(plan, package, taken_product_names)

    if not plan.build_units:
        raise PlanError(
            "Plan produced zero build units. Did --product filter out "
            "everything, or does this package declare only non-library "
            "products?"
        )

    # Transitive `.product(name:, package:)` references that need their own
    # sibling xcframework are handled by the top-level orchestrator
    # `_run_source_mode_with_transitives`: each `TransitivePackageInfo`
    # turns into a fresh `_run_source_mode` call against the resolved
    # checkout. Plan stays single-package and subprocess-free.

    return plan


_CUSTOM_TARGET_WRAPPER_SIGNALS = (
    "func toTarget(",   # canonical: swift-collections' CustomTarget.toTarget
    ": [CustomTarget]",  # typed array of a non-Target helper
)


def _manifest_uses_custom_target_wrapper_text(text: str) -> bool:
    """True iff `text` (a `Package.swift` body) declares its targets
    through a user-supplied helper type whose own `.target(...)` static
    method shadows `Target.target`. Pure-string predicate so callers
    can run the check against either an on-disk manifest (Plan) or the
    in-memory text being edited (Execute's dedup-overlap router).

    See `_manifest_uses_custom_target_wrapper` for the rationale.
    """
    return any(sig in text for sig in _CUSTOM_TARGET_WRAPPER_SIGNALS)


def _manifest_uses_custom_target_wrapper(package: Package) -> bool:
    """True iff the package's Package.swift defines its targets through
    a user-supplied helper type whose own `.target(...)` static method
    shadows `Target.target`.

    The textual dedup-overlap rewriter (`edit_replace_with_binary_target`)
    can't distinguish between `Target.target(name: T, ...)` and
    `CustomTarget.target(name: T, ...)` at the call site, since both
    appear as `.target(name: T, ...)` in source. When this returns
    True, Execute's dedup-overlap routes through
    `edit_inject_or_extend_overlay_binary_targets` instead — an
    overlay edit at the `Package(targets:)` boundary that's
    well-typed regardless of wrapper presence.

    Detection scans the active manifest text for either of the two
    canonical signals listed in `_CUSTOM_TARGET_WRAPPER_SIGNALS`.
    Missing-file / unreadable-manifest cases conservatively return
    False so well-formed packages aren't forced onto the overlay
    path.
    """
    if package.staged_dir is None:
        return False
    candidates = (
        package.staged_dir / "Package.swift",
        package.staged_dir / f"Package@swift-{package.tools_version}.swift",
    )
    for manifest_path in candidates:
        if not manifest_path.is_file():
            continue
        try:
            text = manifest_path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        if _manifest_uses_custom_target_wrapper_text(text):
            return True
    return False


def _target_declares_linker_settings(package: Package, target_name: str) -> bool:
    """True iff `target_name`'s entry in the raw `dump-package` output
    declares at least one `tool: "linker"` setting (`linkedFramework`,
    `linkedLibrary`, or linker-tooled unsafe flags).

    Heuristic for "this internal helper depends on its umbrella's link
    context and won't build standalone as a `.library(type: .dynamic)`".
    The canonical false-positive we're avoiding: WCDB's `bridge`,
    `common`, and `objc-core` helpers, which `.linkedFramework`
    CoreFoundation via WCDBSwift's settings and fail at link with
    `Undefined symbol: _CFAllocatorGetDefault` when promoted to their
    own dynamic library.

    Returns False if the target isn't found in the raw dump (best-effort
    — caller's behaviour matches "no linker settings" since promoting
    a phantom target is itself a no-op).
    """
    for raw_t in package.raw_dump.get("targets", []) or []:
        if not isinstance(raw_t, dict):
            continue
        if raw_t.get("name") != target_name:
            continue
        for setting in raw_t.get("settings") or []:
            if isinstance(setting, dict) and setting.get("tool") == "linker":
                return True
        return False
    return False


def _auto_synth_sibling_units(
    plan: Plan, package: Package, taken_product_names: Set[str]
) -> None:
    """Walk planned build units, find statically-linked internal sibling
    targets not yet owned by any unit, and add a unit + manifest edit
    for each so they ship as their own xcframeworks.

    Behaviour per discovered sibling T:

      - T matches an existing `.library(name: T, ...)` product → reuse
        the product. If currently non-dynamic, emit a
        `synth_dynamic_library` edit (planner re-exports it as a dynamic
        sibling product). The build unit's name is the original product
        name so consumers depend on it by the same identifier.
      - T is internal-only (no matching product) → auto-promote IFF
        it looks safe to build standalone:
          * `tgt.language == Language.SWIFT` — Swift's autolink
            machinery handles Foundation/CoreFoundation without
            explicit linker flags, so a pure-Swift helper builds
            cleanly as `.library(type: .dynamic)`. The canonical
            need here is swift-collections'
            `InternalCollectionsUtilities` (the hidden helper whose
            symbols other siblings' `.swiftinterface` reference).
          * No `tool: "linker"` settings declared on the target —
            even on Swift, a target that explicitly declares
            `.linkedFramework` / `.linkedLibrary` probably depends
            on umbrella-level link context.
        Anything else (ObjC/Mixed/N/A language, or any explicit
        linker settings) → SKIP, leaving the umbrella to statically
        embed the target. Canonical SKIP case: WCDB's `bridge`,
        `common`, and `objc-core` ObjC helpers — they call
        CoreFoundation but the `.linkedFramework("CoreFoundation")`
        lives on the WCDBSwift umbrella's `linkerSettings`. Promoting
        them standalone would fail at link with `Undefined symbol:
        _CFAllocatorGetDefault` and friends. The `--target T` escape
        hatch is still the explicit opt-in.

    Skipped (won't produce a unit):
      - Non-regular targets (system / binary / executable / test /
        plugin / macro): system targets are bundled by
        `inject_system_clang_modules`; binary targets are already
        xcframeworks via SPM resolve; the rest can't be built as
        xcframeworks.
      - Existing products that are system-only or binary-only.
    """
    if not plan.build_units:
        return

    deps_map = compute_internal_target_deps(package)

    # Snapshot of targets already covered by SOME planned unit. Targets
    # added by this pass go into `covered` too so we don't double-emit
    # within one invocation.
    covered: Set[str] = set()
    for bu in plan.build_units:
        for t in bu.source_targets:
            covered.add(t)

    # Walk planned units in stable order and collect uncovered siblings,
    # preserving order so the resulting build_units list is deterministic.
    siblings_to_add: List[str] = []
    for bu in list(plan.build_units):
        for src_t in bu.source_targets:
            for sibling in sorted(deps_map.get(src_t, set())):
                if sibling in covered:
                    continue
                tgt = package.target_by_name(sibling)
                if tgt is None or tgt.kind != TargetKind.REGULAR:
                    continue
                covered.add(sibling)
                siblings_to_add.append(sibling)

    if not siblings_to_add:
        return

    existing_product_names = {p.name for p in package.products}
    existing_planned_names = {bu.name for bu in plan.build_units}

    for sibling in siblings_to_add:
        if sibling not in existing_product_names:
            # Internal helper target with no public product wrapper.
            # Auto-promote only when it looks safe to build standalone.
            # We need this for pure-Swift helpers (canonical:
            # swift-collections' `InternalCollectionsUtilities`): they
            # link cleanly as their own dynamic library and MUST ship
            # as their own xcframework so a sibling's `.swiftinterface`
            # can resolve its `import` line at consumer build time.
            #
            # Two guards keep WCDB-style ObjC helpers out:
            #   (a) language: we only promote Swift-language helpers.
            #       ObjC helpers (canonical: WCDB's `bridge` /
            #       `common` / `objc-core`) almost always rely on
            #       system frameworks (CoreFoundation, Foundation)
            #       linked through the UMBRELLA target's
            #       `.linkedFramework(...)` settings — those flags
            #       don't propagate when SPM builds the sibling as
            #       its own `.library(type: .dynamic)`, so the link
            #       fails with `Undefined symbol: _CFAllocatorGetDefault`
            #       and friends. Swift's autolink machinery covers
            #       Foundation/CoreFoundation for pure-Swift helpers
            #       so the same trap doesn't apply there.
            #   (b) explicit linker settings: even on Swift, a helper
            #       that declares its own `.linkedLibrary`/
            #       `.linkedFramework` likely needs umbrella-level
            #       link context the standalone build won't have.
            #
            # Users can still opt skipped helpers in explicitly via
            # `--target T`.
            tgt = package.target_by_name(sibling)
            if tgt is None:
                continue
            if tgt.language != Language.SWIFT:
                continue
            if _target_declares_linker_settings(package, sibling):
                continue
            language = Language.SWIFT
            taken_product_names.add(sibling)
            plan.package_swift_edits.append(
                PackageSwiftEdit(
                    kind="synth_library",
                    product_name=sibling,
                    targets=[sibling],
                )
            )
            plan.build_units.append(
                BuildUnit(
                    name=sibling,
                    scheme=sibling,
                    framework_name=sibling,
                    language=language,
                    archive_strategy="archive",
                    source_targets=[sibling],
                    synthetic=True,
                )
            )
            existing_planned_names.add(sibling)
            continue
        existing = next(p for p in package.products if p.name == sibling)
        if _is_system_only_product(existing, package):
            continue
        if _is_binary_only_product(existing, package):
            continue
        language = _derive_product_language(existing, package)
        if existing.linkage != Linkage.DYNAMIC:
            synthetic_name = _allocate_synthetic_product_name(
                existing.name, taken_product_names
            )
            plan.package_swift_edits.append(
                PackageSwiftEdit(
                    kind="synth_dynamic_library",
                    product_name=synthetic_name,
                    targets=list(existing.targets),
                )
            )
            scheme = synthetic_name
        else:
            scheme = resolve_scheme(existing.name, package.schemes)
        plan.build_units.append(
            BuildUnit(
                name=existing.name,
                scheme=scheme,
                framework_name=existing.name,
                language=language,
                archive_strategy="archive",
                source_targets=list(existing.targets),
                synthetic=False,
            )
        )
        existing_planned_names.add(existing.name)


def plan_binary_build(config: Config, artifacts: Sequence[BinaryArtifact]) -> Plan:
    """Pure planner for binary-mode builds.

    Input is the list of artifacts discovered by Fetch (see
    `discover_binary_artifacts`). This function just applies the
    --product filter and turns each surviving artifact into a build unit
    whose strategy is "copy-artifact" — Execute will literally `cp -R`
    it into the output directory.
    """
    if config.target_filters:
        raise PlanError(
            "--target is a source-build escape hatch and cannot be used "
            "with --binary."
        )

    plan = Plan()
    plan.binary_mode = True
    plan.include_deps = config.include_deps

    product_filter: Optional[Set[str]] = (
        set(config.product_filters) if config.product_filters else None
    )

    # Dedupe: a vendor artifactbundle can contain the same-named
    # xcframework in multiple locations (usually a bug — cf. the
    # `__MACOSX` ghost already pruned in Fetch), but even legit
    # multi-slice packages occasionally list duplicates. Keep the first
    # occurrence, record the rest on plan.skipped so --dry-run explains
    # why they disappeared from the plan.
    seen_names: Set[str] = set()
    for art in artifacts:
        if art.product_name in seen_names:
            plan.skipped.append(
                (art.product_name, f"duplicate artifact at {art.path}")
            )
            continue
        seen_names.add(art.product_name)
        if product_filter is not None and art.product_name not in product_filter:
            continue
        plan.build_units.append(
            BuildUnit(
                name=art.product_name,
                scheme="",  # n/a — nothing to archive
                framework_name=art.product_name,
                language=Language.NA,  # binary — we don't inspect the bytes
                archive_strategy="copy-artifact",
                source_targets=[],
                synthetic=False,
                artifact_path=art.path,
            )
        )

    if product_filter is not None:
        matched = {bu.name for bu in plan.build_units}
        unmatched = sorted(product_filter - matched)
        if unmatched:
            available = sorted(a.product_name for a in artifacts)
            raise PlanError(
                f"--product filter matched no binary artifacts: {unmatched}\n"
                f"Available artifacts: {available}"
            )

    if not plan.build_units:
        raise PlanError(
            "Binary plan produced zero build units. Did the vendor package "
            "actually ship xcframeworks under .build/artifacts/?"
        )

    return plan


def _derive_package_label(src: str) -> str:
    """Return a human label for a package source URL/path.

    Handles the three shapes we see in practice:
      - https/ssh URLs ending in `.git`  → repo name without .git
      - SCP-style `git@host:org/repo.git` → repo name without .git
      - local filesystem paths           → basename
    """
    src = src.rstrip("/")
    if ":" in src and "@" in src and not src.startswith(("http://", "https://", "ssh://")):
        # SCP-style: `git@github.com:org/repo.git`
        after_colon = src.rsplit(":", 1)[-1]
        base = os.path.basename(after_colon)
    else:
        base = os.path.basename(src)
    if base.endswith(".git"):
        base = base[:-4]
    return base or "(unknown)"


def print_plan(
    plan: Plan,
    *,
    package: Optional[Package],
    config: Config,
) -> None:
    """Render a Plan in the human-readable dry-run format.

    Matches the shape documented in the Session 2 brief. One horizontal
    rule per section; sections are elided when empty. Keeps alignment
    tidy by computing column widths up front so the output stays readable
    even for 12-target Stripe runs.
    """
    if package is not None:
        name = package.name
    else:
        # Binary mode has no Package model — derive the label from the
        # package source URL's basename. Handle SCP-style `git@host:org/repo.git`
        # specially because os.path.basename returns the whole string for it.
        name = _derive_package_label(config.package_source or "(unknown)")

    version = config.user_version or "(unversioned)"
    mode = "binary" if plan.binary_mode else "source"
    bold(f"\nPlan for {name} @ {version}  ({mode} mode)")

    if plan.package_swift_edits:
        print("  Package edits:")
        for edit in plan.package_swift_edits:
            if edit.kind == "synth_dynamic_library":
                tgts = ", ".join(edit.targets)
                print(
                    f"    - synth_dynamic_library: {edit.product_name} "
                    f"→ targets=[{tgts}]"
                )
            elif edit.kind == "synth_library":
                tgts = ", ".join(edit.targets)
                print(
                    f"    - synth_library: {edit.product_name} "
                    f"→ targets=[{tgts}]"
                )
            else:
                print(f"    - {edit.kind}: {edit.product_name}")
    elif not plan.binary_mode:
        print("  Package edits: (none)")

    if plan.build_units:
        print("  Build units:")
        name_w = max(len(bu.name) for bu in plan.build_units)
        scheme_w = max(len(bu.scheme or "-") for bu in plan.build_units)
        lang_w = max(len(bu.language or "-") for bu in plan.build_units)
        name_w = max(name_w, 10)
        scheme_w = max(scheme_w, 8)
        lang_w = max(lang_w, 5)
        for i, bu in enumerate(plan.build_units, start=1):
            markers = []
            if bu.synthetic:
                markers.append("[synthetic library]")
            if bu.archive_strategy == "copy-artifact":
                markers.append("[binary artifact]")
            marker = ("  " + " ".join(markers)) if markers else ""
            scheme_disp = bu.scheme or "-"
            print(
                f"    [{i}] {bu.name:<{name_w}}  "
                f"scheme={scheme_disp:<{scheme_w}}  "
                f"language={bu.language:<{lang_w}}  "
                f"→ {bu.framework_name}.xcframework{marker}"
            )
    else:
        print("  Build units: (none)")

    selected = _selected_slices(config)
    if selected:
        ids = ", ".join(s.slice_id for s, _ in selected)
        print(f"  Selected slices: {ids}")

    if plan.skipped:
        print("  Skipped:")
        for sname, reason in plan.skipped:
            print(f"    - {sname} ({reason})")

    if plan.include_deps:
        print("  Note: --include-deps is enabled; transitive frameworks will "
              "be discovered after Execute runs.")


# ============================================================================
# --- prepare.py ------------------------------------------------------------
# ============================================================================


import re
import subprocess
from pathlib import Path
from typing import Dict, List, Optional, Sequence, Tuple



def _strip_swift_comments(text: str) -> str:
    """Return `text` with `//` line comments and `/* */` block comments
    replaced by equal-length spans of spaces (preserving newlines). The
    length/offset preservation keeps any downstream index math valid,
    and preserving newlines keeps line-counting error messages honest.

    This is NOT a full Swift tokenizer — it only tracks double-quoted
    string state so comment markers inside a regular string literal
    don't trigger. The file-wide `_assert_no_unsupported_swift_constructs`
    gate runs AFTER this stripper and guards against the advanced
    string shapes (raw strings, triple-quotes, interpolation) that
    could otherwise fool the state machine.

    Behavior on unterminated comments / strings: we stop stripping at
    the unterminated boundary and keep the rest of the text verbatim.
    This conservative fall-through means a weird-shaped file is still
    checked against the unsupported-construct triggers in both its
    stripped-comment view and whatever trailing span the stripper
    couldn't classify.
    """
    n = len(text)
    out: List[str] = []
    i = 0
    while i < n:
        c = text[i]
        # Double-quoted string: copy verbatim, honoring `\\` escapes.
        if c == '"':
            out.append(c)
            i += 1
            while i < n:
                cc = text[i]
                out.append(cc)
                if cc == "\\" and i + 1 < n:
                    out.append(text[i + 1])
                    i += 2
                    continue
                if cc == '"':
                    i += 1
                    break
                if cc == "\n":
                    # Unterminated string — bail out. Copy the rest
                    # verbatim so the trigger-token scanner still sees
                    # anything suspicious downstream.
                    i += 1
                    break
                i += 1
            continue
        # Line comment: replace span with spaces up to (but not including)
        # the newline.
        if c == "/" and i + 1 < n and text[i + 1] == "/":
            end = text.find("\n", i + 2)
            if end == -1:
                end = n
            out.append(" " * (end - i))
            i = end
            continue
        # Block comment: replace span with spaces, but preserve newlines
        # so line numbers don't shift. Swift block comments NEST, so we
        # track depth rather than stopping at the first `*/`.
        if c == "/" and i + 1 < n and text[i + 1] == "*":
            depth = 1
            j = i + 2
            while j < n and depth > 0:
                if j + 1 < n and text[j] == "/" and text[j + 1] == "*":
                    depth += 1
                    j += 2
                    continue
                if j + 1 < n and text[j] == "*" and text[j + 1] == "/":
                    depth -= 1
                    j += 2
                    continue
                j += 1
            if depth > 0:
                # Unterminated (possibly nested) block comment.
                # Conservative fallthrough: copy the rest as-is and
                # let the trigger-token scan re-check.
                out.append(text[i:])
                i = n
                break
            stop = j
            for ch in text[i:stop]:
                out.append("\n" if ch == "\n" else " ")
            i = stop
            continue
        out.append(c)
        i += 1
    return "".join(out)


def _make_code_token_view(text: str) -> str:
    """Return `text` with `//` line comments, `/* */` block comments,
    AND `"..."` string-literal spans (delimiters + body) replaced by
    equal-length spans of spaces. Newlines are preserved so line
    counters stay honest, and every offset in the returned string
    indexes the same Swift construct as in `text`.

    Use this when searching for top-level code tokens like `.target(`
    or `.binaryTarget(` that must NOT match inside any non-code region
    of a Package.swift. Stripping comments alone (via
    `_strip_swift_comments`) is not enough — a valid string literal
    whose body contains `.target(name: \"X\", ...)` text would
    otherwise be picked up as a candidate, the rewrite would refuse
    to land because the body's `name:` doesn't sit at depth 0 of a
    real call, and the user sees a spurious PrepareUserError on a
    well-formed manifest.

    Limitations match `_strip_swift_comments`: only `"..."` strings are
    tracked. `#\"...\"#` raw strings and `\"\"\"...\"\"\"` multi-line
    strings aren't supported here — they would be rejected upstream by
    `_assert_no_unsupported_swift_constructs` before any prepare-time
    edit runs. `\\(...)` string interpolation IS handled by recursing
    through `_balanced_close` to find the closing `)` of the embedded
    expression, then resuming string mode — matching what
    `_balanced_close` itself does, so the two views agree on where
    strings end.

    On an unterminated string or block comment, falls through
    conservatively: copies the suspicious tail verbatim. The trigger
    scanner upstream is the layer that turns this into a hard error,
    so a soft fall-through here keeps the helper a pure offset-faithful
    view rather than another error site.
    """
    n = len(text)
    out: List[str] = []
    i = 0
    while i < n:
        c = text[i]
        # Double-quoted string: blank delimiters + body with spaces, keep newlines.
        # Honors `\(...)` interpolation via recursion through `_balanced_close`,
        # so a string like `"Sources/\(name + "Tests")"` doesn't mis-terminate
        # on the inner `"` of the interpolation expression.
        if c == '"':
            j = i + 1
            terminated = False
            while j < n:
                cc = text[j]
                if cc == "\\" and j + 1 < n:
                    if text[j + 1] == "(":
                        close_idx = _balanced_close(text, j + 1)
                        if close_idx == -1:
                            # Unterminated interpolation — bail conservatively.
                            break
                        j = close_idx + 1
                        continue
                    j += 2
                    continue
                if cc == '"':
                    j += 1
                    terminated = True
                    break
                if cc == "\n":
                    # Unterminated — stop the string here, leave the
                    # newline for outer processing.
                    break
                j += 1
            if not terminated and j < n and text[j] == "\n":
                # Blank the string opener through j-1 (the chars before \n);
                # leave the newline itself untouched so the line ends.
                for k in range(i, j):
                    out.append("\n" if text[k] == "\n" else " ")
                i = j
                continue
            for k in range(i, j):
                out.append("\n" if text[k] == "\n" else " ")
            i = j
            continue
        # Line comment: blank up to (but not including) the newline.
        if c == "/" and i + 1 < n and text[i + 1] == "/":
            end = text.find("\n", i + 2)
            if end == -1:
                end = n
            out.append(" " * (end - i))
            i = end
            continue
        # Block comment: blank delimiters + body with spaces, preserving newlines.
        if c == "/" and i + 1 < n and text[i + 1] == "*":
            depth = 1
            j = i + 2
            while j < n and depth > 0:
                if j + 1 < n and text[j] == "/" and text[j + 1] == "*":
                    depth += 1
                    j += 2
                    continue
                if j + 1 < n and text[j] == "*" and text[j + 1] == "/":
                    depth -= 1
                    j += 2
                    continue
                j += 1
            if depth > 0:
                out.append(text[i:])
                i = n
                break
            stop = j
            for ch in text[i:stop]:
                out.append("\n" if ch == "\n" else " ")
            i = stop
            continue
        out.append(c)
        i += 1
    return "".join(out)


def _assert_no_unsupported_swift_constructs(text: str) -> None:
    """Fail loudly if `text` contains Swift constructs the balanced-paren
    walker can't reason about.

    The walker handles double-quoted strings (with backslash escapes),
    line comments (//), block comments, and string interpolation
    (`\\(...)` via recursion through the walker). It does NOT handle
    Swift raw strings (`#"..."#`) or multi-line triple-quoted strings:
    unescaped quotes inside a raw string would confuse the string-skip
    state, and triple-quotes use a different terminator.

    To avoid flagging false positives on doc comments that legitimately
    mention these constructs (e.g. `/// Uses #"..."# internally`), we
    scan a comment-stripped view of the manifest. Real code uses of
    the constructs still fire; mentions inside `//`, `/* */`, or `///`
    doc comments pass through untouched.

    The check remains a heuristic gate, not a full parser. Known
    limitations:
      - Doc comments inside regular strings are stripped, since the
        stripper follows the string-state machine. This is the same
        behavior as the downstream `_balanced_close` walker.
      - A string literal like `let s = "#\\"hi\\"#"` looks the same
        to the scanner as a real raw-string use, so the check will
        reject it. Real manifests don't write strings like this.
    """
    scanned = _strip_swift_comments(text)
    if '#"' in scanned:
        raise PrepareUserError(
            "Package.swift uses Swift raw string literals (`#\"...\"#`), "
            "which the balanced-paren walker doesn't understand. "
            "File a bug if this needs to be supported."
        )
    if '"""' in scanned:
        raise PrepareUserError(
            "Package.swift uses Swift triple-quoted strings (`\"\"\"`), "
            "which the balanced-paren walker doesn't understand. "
            "File a bug if this needs to be supported."
        )
    # Swift string interpolation (`\\(...)`) used to be rejected here but
    # the walker now handles it via recursion through itself in the
    # string-skip path. Real-world manifests use it heavily (e.g.
    # swift-collections' Package.swift builds path strings from target
    # names via `"Sources/\\(name)"`).


def _balanced_close(text: str, open_idx: int) -> int:
    """Walk text from `open_idx` (which must point at one of `(`, `[`, `{`)
    to the matching closing bracket, returning its index. Skips over Swift
    string literals (`"..."` with `\\"` escapes), `// ...` line comments, and
    `/* ... */` block comments. Returns -1 if no matching close is found.

    Does NOT handle Swift multi-line triple-quoted strings or raw
    strings. `\\(...)` string interpolation IS handled by recursing
    through this same walker to find the closing `)` of the interpolation
    expression, then resuming string mode. Callers should still run
    `_assert_no_unsupported_swift_constructs` on the full manifest text
    so the unsupported constructs that remain fail loudly with a targeted
    PrepareError instead of being silently mis-parsed.
    """
    if open_idx < 0 or open_idx >= len(text):
        return -1
    open_ch = text[open_idx]
    pair = {"(": ")", "[": "]", "{": "}"}
    if open_ch not in pair:
        return -1
    close_ch = pair[open_ch]

    depth = 0
    i = open_idx
    n = len(text)
    while i < n:
        c = text[i]
        # Line comment: skip to end-of-line.
        if c == "/" and i + 1 < n and text[i + 1] == "/":
            nl = text.find("\n", i + 2)
            if nl == -1:
                return -1
            i = nl + 1
            continue
        # Block comment: skip past the matched close. Swift block
        # comments NEST, so we track depth rather than stopping at
        # the first `*/`.
        if c == "/" and i + 1 < n and text[i + 1] == "*":
            block_depth = 1
            i += 2
            while i < n and block_depth > 0:
                if i + 1 < n and text[i] == "/" and text[i + 1] == "*":
                    block_depth += 1
                    i += 2
                    continue
                if i + 1 < n and text[i] == "*" and text[i + 1] == "/":
                    block_depth -= 1
                    i += 2
                    continue
                i += 1
            if block_depth > 0:
                return -1
            continue
        # String literal: skip to closing quote, honoring `\\"` escapes
        # and `\(...)` interpolation. Interpolation embeds an arbitrary
        # Swift expression (which itself can contain strings, comments,
        # nested interpolation, and brackets) — we recurse through this
        # same walker to find the closing `)`, then resume string mode.
        if c == '"':
            i += 1
            while i < n:
                cc = text[i]
                if cc == "\\" and i + 1 < n:
                    if text[i + 1] == "(":
                        close_idx = _balanced_close(text, i + 1)
                        if close_idx == -1:
                            return -1
                        i = close_idx + 1
                        continue
                    i += 2
                    continue
                if cc == '"':
                    i += 1
                    break
                if cc == "\n":
                    # Unterminated string — give up rather than misparse.
                    return -1
                i += 1
            continue
        if c == open_ch:
            depth += 1
        elif c == close_ch:
            depth -= 1
            if depth == 0:
                return i
        i += 1
    return -1


def _swift_string_literal(s: str) -> str:
    """Quote `s` as a Swift string literal that's safe inside Package.swift.

    Escapes the two characters that can break a `"..."` literal — backslash
    and double-quote. Newlines, raw strings, and interpolation are
    deliberately not handled: Package.swift values that need them aren't
    inputs we'll ever pass through here (target names and on-disk
    xcframework paths).
    """
    return '"' + s.replace("\\", "\\\\").replace('"', '\\"') + '"'


_TARGET_CALL_KIND_RE = re.compile(r"\.(target|executableTarget|testTarget)\s*\(")
_BINARY_TARGET_CALL_RE = re.compile(r"\.binaryTarget\s*\(")
_LIBRARY_CALL_RE = re.compile(r"\.library\s*\(")
_TOP_LEVEL_NAME_LABEL_RE = re.compile(
    r'\bname\s*:\s*"((?:[^"\\\n]|\\.)*)"'
)


def _flatten_to_top_level(span: str) -> str:
    """Collapse `span` to a string preserving only its depth-0
    characters. Nested paren / bracket / brace bodies (including their
    delimiters) are replaced with a single space, while strings and
    comments at depth 0 are kept verbatim so a regex looking for a
    labelled string argument still sees its literal value.

    The returned string has different offsets from `span`. Callers that
    need offsets back into the original buffer must do their own
    bookkeeping; the helper is only meant for "does the top-level
    argument list say `name: \"X\"`?" style queries.

    This is the depth-0 sieve underpinning `_top_level_name_label`,
    which `_find_target_call_for_name` and `_has_binary_target_with_name`
    use to ignore `name:` references nested inside a target's
    `dependencies:` array (e.g. `.target(name: "Dep")` expressions).
    """
    out: List[str] = []
    i = 0
    n = len(span)
    while i < n:
        c = span[i]
        if c == "/" and i + 1 < n and span[i + 1] == "/":
            nl = span.find("\n", i + 2)
            i = nl + 1 if nl != -1 else n
            continue
        if c == "/" and i + 1 < n and span[i + 1] == "*":
            block_depth = 1
            i += 2
            while i < n and block_depth > 0:
                if i + 1 < n and span[i] == "/" and span[i + 1] == "*":
                    block_depth += 1
                    i += 2
                    continue
                if i + 1 < n and span[i] == "*" and span[i + 1] == "/":
                    block_depth -= 1
                    i += 2
                    continue
                i += 1
            continue
        if c == '"':
            j = i + 1
            while j < n:
                cc = span[j]
                if cc == "\\" and j + 1 < n:
                    if span[j + 1] == "(":
                        close_idx = _balanced_close(span, j + 1)
                        if close_idx == -1:
                            break
                        j = close_idx + 1
                        continue
                    j += 2
                    continue
                if cc == '"':
                    j += 1
                    break
                if cc == "\n":
                    break
                j += 1
            out.append(span[i:j])
            i = j
            continue
        if c in "([{":
            close = _balanced_close(span, i)
            if close == -1:
                # Malformed nested scope — bail out cleanly so the
                # caller's regex sees what we collected so far rather
                # than raising. `_balanced_close == -1` already implies
                # a manifest the rest of the pipeline will reject.
                break
            out.append(" ")
            i = close + 1
            continue
        out.append(c)
        i += 1
    return "".join(out)


def _top_level_name_label(span: str) -> Optional[str]:
    """Return the value of the `name:` keyword argument at the top
    level of `span`, or None if no such top-level label is present.

    "Top level" means depth 0 — not inside any nested
    paren/bracket/brace. So a call body like
    `name: "A", dependencies: [.target(name: "Foo")]` returns "A",
    not "Foo": the inner `name:` is at depth 2 (`[` then `(`) and
    gets stripped by `_flatten_to_top_level` before the regex runs.

    Used by `_find_target_call_for_name` and
    `_has_binary_target_with_name` to verify a candidate call's OWN
    name argument before accepting the match. Regression for the bug
    where the planner's substitution edited the wrong target because
    a sibling's `dependencies:` list happened to mention the target's
    name as a `.target(name: "X")` expression.
    """
    flat = _flatten_to_top_level(span)
    m = _TOP_LEVEL_NAME_LABEL_RE.search(flat)
    if not m:
        return None
    return m.group(1)


def _find_target_call_for_name(
    text: str, target_name: str
) -> Tuple[int, int, str]:
    """Locate the `.target(name: "<target_name>", ...)` call (or
    `.executableTarget` / `.testTarget`) whose own top-level `name:`
    argument matches exactly.

    Returns `(call_start_idx, close_paren_idx, kind_used)` where
    `call_start_idx` is the offset of the leading `.` and
    `close_paren_idx` is the offset of the matching `)`. `kind_used` is
    one of `"target"`, `"executableTarget"`, `"testTarget"`.

    Returns `(-1, -1, "")` if no matching call is found. Deliberately
    skips `.binaryTarget(...)` and `.systemLibrary(...)` — substituting
    them is either pointless (already binary) or unsupported (not a real
    target we can build into an xcframework).

    Two filtering disciplines are stacked:

    1. Candidate discovery runs against a code-only view of the
       manifest (`_make_code_token_view`, which blanks `//` line
       comments, `/* */` block comments, AND `"..."` string-literal
       spans into equal-length spaces while preserving offsets). A
       commented-out OR string-literal-embedded `.target(name: "X")`
       cannot match — its leading `.target(` was blanked. (Codex P2
       round-2 regression: a commented decl before the real one
       caused the edit to rewrite the comment. Codex P2 round-3
       regression: a string literal whose body contained
       `.target(name: "X", ...)` text caused the finder to stop on
       the string and raise a spurious PrepareUserError.)

    2. The match's own top-level `name:` argument is verified via
       `_top_level_name_label`. A sibling target whose `dependencies:`
       array contains `.target(name: "Foo")` would otherwise falsely
       match when searching for "Foo". (Codex P1 regression.)
    """
    code_view = _make_code_token_view(text)
    pos = 0
    while True:
        m = _TARGET_CALL_KIND_RE.search(code_view, pos)
        if not m:
            return -1, -1, ""
        kind = m.group(1)
        kind_start = m.start()
        open_idx = m.end() - 1
        close_idx = _balanced_close(text, open_idx)
        if close_idx == -1:
            raise PrepareUserError(
                f"Could not find balanced `)` for .{kind}( at offset "
                f"{open_idx}; the manifest may be malformed."
            )
        span = text[open_idx + 1 : close_idx]
        if _top_level_name_label(span) == target_name:
            return kind_start, close_idx, kind
        pos = close_idx + 1


def _has_binary_target_with_name(text: str, target_name: str) -> bool:
    """True iff `text` contains a `.binaryTarget(name: "<target_name>", ...)`
    call whose top-level `name:` argument matches exactly. Same
    code-only + depth-0 discipline as `_find_target_call_for_name`:
    a stray `.binaryTarget(name: "X")` mentioned inside another call's
    body, sitting inside a `//`/`/* */` comment, or embedded in a
    `"..."` string literal can't false-positive the idempotency check.
    """
    code_view = _make_code_token_view(text)
    pos = 0
    while True:
        m = _BINARY_TARGET_CALL_RE.search(code_view, pos)
        if not m:
            return False
        open_idx = m.end() - 1
        close_idx = _balanced_close(text, open_idx)
        if close_idx == -1:
            return False
        span = text[open_idx + 1 : close_idx]
        if _top_level_name_label(span) == target_name:
            return True
        pos = close_idx + 1


_PACKAGE_CALL_RE = re.compile(r"\bPackage\s*\(")
_PRODUCTS_LABEL_RE = re.compile(r"\bproducts\s*:")
_TARGETS_LABEL_RE = re.compile(r"\btargets\s*:")
_OVERLAY_BINARY_TARGET_RE = re.compile(r"\bTarget\s*\.\s*binaryTarget\s*\(")

# Sentinel comments wrap the auto-generated overlay block so a later
# dedup-overlap pass can find, parse, and extend its own previous
# output without trying to re-parse free-form Swift.
_OVERLAY_SENTINEL_BEGIN = (
    "// spm-to-xcframework dedup-overlap overlay — begin "
    "(auto-generated, do not edit)"
)
_OVERLAY_SENTINEL_END = "// spm-to-xcframework dedup-overlap overlay — end"
_OVERLAY_TARGETS_VAR = "_SPM2XC_OVERLAY_TARGETS"
_OVERLAY_NAMES_VAR = "_SPM2XC_OVERLAY_NAMES"


def edit_append_synth_product_to_package(
    manifest_text: str, product_name: str, targets: Sequence[str]
) -> str:
    """Append `.library(name: <product_name>, type: .dynamic, targets:
    [<targets>])` to the top-level `Package(...)` call's `products:`
    argument by rewriting `products: <expr>` to `products: <expr> +
    [<synth>]`.

    Fallback for `swift package add-product` failures when the manifest's
    `products:` argument is not a literal array. Real example:
    swift-collections 1.1.4 builds its product list programmatically
    (`products: _products`), which SPM rejects with "unable to find
    array literal for 'products' argument".

    The `(<expr>) + [<synth>]` rewrite is well-typed both for literal
    arrays and for any `[Product]`-typed expression, so we don't need
    to locate the closing `]` of an array — we just splice at the
    expression's end (next top-level comma or the closing `)` of the
    Package call). The original expression is wrapped in parens to defend
    against precedence surprises: a manifest written as
    `products: cond ? a : b` would, without the wrap, parse as
    `products: cond ? a : (b + [<synth>])` because `+` binds tighter than
    `?:`. The same hazard applies to `??`. The synthetic entry's type is
    always `.dynamic` because that's the only kind of synthetic library
    we currently emit via this path; `synth_library` (non-dynamic) goes
    through add-product on packages whose manifest shape allows it.
    """
    code_view = _make_code_token_view(manifest_text)
    m = _PACKAGE_CALL_RE.search(code_view)
    if not m:
        raise PrepareUserError(
            "synth-product fallback: no top-level `Package(` call found "
            "in the manifest."
        )
    pkg_open = m.end() - 1
    pkg_close = _balanced_close(manifest_text, pkg_open)
    if pkg_close == -1:
        raise PrepareUserError(
            "synth-product fallback: unmatched `(` for `Package(`; "
            "manifest may be malformed."
        )
    body_start = pkg_open + 1
    body_end = pkg_close
    body = manifest_text[body_start:body_end]
    body_dz = _depth_zero_view(body)
    lm = _PRODUCTS_LABEL_RE.search(body_dz)
    if not lm:
        raise PrepareUserError(
            "synth-product fallback: no top-level `products:` argument "
            "inside the Package(...) call. The manifest shape is not "
            "supported by this fallback."
        )
    # Bound the products expression: from just after `products:` (skipping
    # any leading horizontal whitespace) to the next top-level comma or
    # the end of the Package body. Walk back over trailing whitespace so
    # the closing `)` lands flush against the expression instead of
    # swallowing pre-comma indentation.
    expr_start_in_body = lm.end()
    while (
        expr_start_in_body < len(body)
        and body[expr_start_in_body] in " \t"
    ):
        expr_start_in_body += 1
    comma_idx = body_dz.find(",", expr_start_in_body)
    expr_end_in_body = comma_idx if comma_idx != -1 else len(body)
    while (
        expr_end_in_body > expr_start_in_body
        and body[expr_end_in_body - 1] in " \t\n"
    ):
        expr_end_in_body -= 1

    expr_start_offset = body_start + expr_start_in_body
    expr_end_offset = body_start + expr_end_in_body

    targets_list = ", ".join(_swift_string_literal(t) for t in targets)
    synth_tail = (
        f") + [.library(name: {_swift_string_literal(product_name)}, "
        f"type: .dynamic, targets: [{targets_list}])]"
    )
    # Wrap the original expression in parens, then append `+ [<synth>]`.
    # Done as a single splice so the two edits don't disturb each other's
    # offsets.
    return (
        manifest_text[:expr_start_offset]
        + "("
        + manifest_text[expr_start_offset:expr_end_offset]
        + synth_tail
        + manifest_text[expr_end_offset:]
    )


def edit_replace_with_binary_target(
    manifest_text: str, target_name: str, xcframework_path: str
) -> str:
    """Rewrite the `.target(name: T, ...)` (or `.executableTarget` /
    `.testTarget`) declaration for `target_name` to a
    `.binaryTarget(name: T, path: P)` referring to `xcframework_path`.

    This is the dedup-overlap edit (REWRITE_DESIGN.md §5.4): when an
    umbrella product depends on a sibling target that we've already
    built into a dynamic xcframework, swap the source target for a
    binary one. SPM then resolves the umbrella's link to that
    pre-existing dylib instead of re-compiling and statically embedding
    every sibling's symbols.

    Idempotent: if the manifest already declares `.binaryTarget(name: T,
    ...)` and no remaining `.target(name: T, ...)`, the function
    returns the text unchanged. The reverse asymmetry — both shapes
    present for the same name — is treated as a malformed manifest
    (likely corruption from a half-applied prior edit) and raises
    `PrepareUserError`.

    Parameters:
      manifest_text     — full Package.swift text to edit
      target_name       — exact name of the target to substitute
      xcframework_path  — path the new `.binaryTarget` will point at;
                          may be absolute or relative to the package
                          root (SPM accepts both)

    Returns the edited manifest text. Caller writes it back.
    """
    binary_present = _has_binary_target_with_name(manifest_text, target_name)
    kind_start, close_idx, _kind = _find_target_call_for_name(
        manifest_text, target_name
    )

    if kind_start == -1:
        if binary_present:
            return manifest_text  # already a binaryTarget; idempotent no-op
        raise PrepareUserError(
            f"replace_with_binary_target: no `.target(name: {target_name!r}, "
            f"...)` (or .executableTarget/.testTarget) found in the manifest. "
            f"There is also no existing `.binaryTarget(name: {target_name!r}, "
            f"...)` — nothing matches the substitution request."
        )

    if binary_present:
        raise PrepareUserError(
            f"replace_with_binary_target: manifest contains BOTH a source "
            f"target and a `.binaryTarget` for {target_name!r}. The manifest "
            f"is in a half-edited state — a prior dedup-overlap run likely "
            f"failed mid-edit. Restore from .original-Package.swift and try "
            f"again."
        )

    name_literal = _swift_string_literal(target_name)
    path_literal = _swift_string_literal(xcframework_path)
    replacement = f".binaryTarget(name: {name_literal}, path: {path_literal})"
    return manifest_text[:kind_start] + replacement + manifest_text[close_idx + 1 :]


def _parse_overlay_entries(block_text: str) -> Dict[str, str]:
    """Parse `Target.binaryTarget(name: "N", path: "P")` entries out of
    an overlay block's array literal. Returns name → path. Strict by
    design — the block is sentinel-bounded auto-generated text whose
    shape we fully control, so any parse failure indicates corruption.
    """
    entries: Dict[str, str] = {}
    pos = 0
    while True:
        m = _OVERLAY_BINARY_TARGET_RE.search(block_text, pos)
        if not m:
            return entries
        open_idx = m.end() - 1
        close_idx = _balanced_close(block_text, open_idx)
        if close_idx == -1:
            raise PrepareUserError(
                "overlay edit: malformed Target.binaryTarget(...) call in "
                "the existing overlay block (unbalanced parens)."
            )
        span = block_text[open_idx + 1 : close_idx]
        flat = _flatten_to_top_level(span)
        name_m = re.search(
            r'\bname\s*:\s*"((?:[^"\\\n]|\\.)*)"', flat
        )
        path_m = re.search(
            r'\bpath\s*:\s*"((?:[^"\\\n]|\\.)*)"', flat
        )
        if not name_m or not path_m:
            raise PrepareUserError(
                "overlay edit: Target.binaryTarget entry inside the overlay "
                "block is missing `name:` or `path:`."
            )
        entries[name_m.group(1)] = path_m.group(1)
        pos = close_idx + 1


def _render_overlay_block(entries: Dict[str, str]) -> str:
    """Render an overlay block from `entries` (name → path), with stable
    sort order (by name). Sentinel-wrapped so subsequent calls can find
    and rewrite it. Trailing newline ensures the block sits on its own
    lines.
    """
    lines = [_OVERLAY_SENTINEL_BEGIN]
    lines.append(f"let {_OVERLAY_TARGETS_VAR}: [Target] = [")
    for name in sorted(entries):
        lines.append(
            f"  Target.binaryTarget("
            f"name: {_swift_string_literal(name)}, "
            f"path: {_swift_string_literal(entries[name])}),"
        )
    lines.append("]")
    lines.append(
        f"let {_OVERLAY_NAMES_VAR}: Set<String> = "
        f"Set({_OVERLAY_TARGETS_VAR}.map {{ $0.name }})"
    )
    lines.append(_OVERLAY_SENTINEL_END)
    return "\n".join(lines) + "\n"


def edit_inject_or_extend_overlay_binary_targets(
    manifest_text: str, substitutions: Sequence[Tuple[str, str]]
) -> str:
    """Dedup-overlap edit for wrapper-style manifests.

    Used in place of `edit_replace_with_binary_target` when the
    manifest's target list is built through a user-defined wrapper
    (e.g. swift-collections' `CustomTarget` + `.toTarget()`), where the
    textual `.target(name: T, ...)` finder would match wrapper calls
    that have no `.binaryTarget` static method.

    The overlay intervenes one level higher: at the top-level
    `Package(targets: <expr>)` boundary. The wrapper's output is always
    a `[Target]`, so we filter same-named entries out of it and
    concatenate our own `Target.binaryTarget(...)` entries — producing
    a well-typed `[Target]` that SPM accepts.

    Two-state idempotency:
      1. First call (no sentinel block present): injects the overlay
         block immediately before the top-level `Package(...)` call AND
         wraps the `targets:` argument expression as
         `targets: (<orig>).filter { !_SPM2XC_OVERLAY_NAMES.contains($0.name) } + _SPM2XC_OVERLAY_TARGETS`.
      2. Subsequent calls (sentinel block present): parses the existing
         entries, merges with `substitutions` (last-wins by target
         name), and re-renders the block in place. The `targets:`
         wrap is left alone since it already references the overlay
         vars.

    `substitutions` is `[(target_name, xcframework_rel_path), ...]`.
    Paths must be relative to the package root — SPM rejects absolute
    paths in `.binaryTarget(path:)`. Caller is responsible for the
    relpath computation (same as the literal-list path in
    `_apply_dedup_overlap_substitutions`).

    Returns the edited manifest text. A call with zero substitutions
    AND no pre-existing overlay block is a no-op. A call that produces
    no net change (every substitution already in the existing block
    with the same path) returns `manifest_text` unchanged.

    Raises `PrepareUserError` if the manifest has no `Package(...)`
    call, no top-level `targets:` argument, or a malformed existing
    overlay block.
    """
    code_view = _make_code_token_view(manifest_text)

    # Locate any existing sentinel-bounded overlay block. We scan the
    # raw text rather than the code view: comments are blanked out in
    # the code view, so a sentinel COMMENT wouldn't appear there. Use
    # the raw text directly.
    block_start = manifest_text.find(_OVERLAY_SENTINEL_BEGIN)
    overlay_present = block_start != -1
    existing: Dict[str, str] = {}
    block_end = -1
    if overlay_present:
        sentinel_end = manifest_text.find(_OVERLAY_SENTINEL_END, block_start)
        if sentinel_end == -1:
            raise PrepareUserError(
                "overlay edit: found overlay begin sentinel without a "
                "matching end sentinel; the manifest is in a half-edited "
                "state."
            )
        block_end = sentinel_end + len(_OVERLAY_SENTINEL_END)
        if block_end < len(manifest_text) and manifest_text[block_end] == "\n":
            block_end += 1
        existing = _parse_overlay_entries(manifest_text[block_start:block_end])

    merged = dict(existing)
    for name, rel_path in substitutions:
        merged[name] = rel_path

    if not merged:
        # Nothing to do: no existing entries AND no new substitutions.
        return manifest_text

    if overlay_present:
        if merged == existing:
            return manifest_text
        new_block = _render_overlay_block(merged)
        return manifest_text[:block_start] + new_block + manifest_text[block_end:]

    # First-time injection: build the block, find the Package(...) call,
    # wrap its `targets:` argument expression, and splice the block in
    # immediately before the line containing `Package(`.
    new_block = _render_overlay_block(merged)

    m = _PACKAGE_CALL_RE.search(code_view)
    if not m:
        raise PrepareUserError(
            "overlay edit: no top-level `Package(` call found in the "
            "manifest."
        )
    pkg_open = m.end() - 1
    pkg_close = _balanced_close(manifest_text, pkg_open)
    if pkg_close == -1:
        raise PrepareUserError(
            "overlay edit: unmatched `(` for `Package(`; the manifest "
            "may be malformed."
        )
    body_start = pkg_open + 1
    body_end = pkg_close
    body = manifest_text[body_start:body_end]
    body_dz = _depth_zero_view(body)
    lm = _TARGETS_LABEL_RE.search(body_dz)
    if not lm:
        raise PrepareUserError(
            "overlay edit: no top-level `targets:` argument inside the "
            "Package(...) call. The manifest shape is not supported by "
            "the overlay edit."
        )
    expr_start_in_body = lm.end()
    while (
        expr_start_in_body < len(body)
        and body[expr_start_in_body] in " \t"
    ):
        expr_start_in_body += 1
    comma_idx = body_dz.find(",", expr_start_in_body)
    expr_end_in_body = comma_idx if comma_idx != -1 else len(body)
    while (
        expr_end_in_body > expr_start_in_body
        and body[expr_end_in_body - 1] in " \t\n"
    ):
        expr_end_in_body -= 1
    expr_start_offset = body_start + expr_start_in_body
    expr_end_offset = body_start + expr_end_in_body

    # Find the insertion point for the overlay block — the start of the
    # statement that opens the Package(...) call. Walk back from
    # pkg_open to the most recent newline + 1 (or BOF).
    line_start = manifest_text.rfind("\n", 0, pkg_open) + 1

    wrap_prefix = "("
    wrap_suffix = (
        f").filter {{ !{_OVERLAY_NAMES_VAR}.contains($0.name) }} "
        f"+ {_OVERLAY_TARGETS_VAR}"
    )

    # Splice three regions in order from the end of the text so earlier
    # offsets stay valid:
    #   1. wrap_suffix immediately AFTER the targets-arg expression
    #   2. wrap_prefix immediately BEFORE it
    #   3. new_block immediately BEFORE the Package(...) statement
    # Done as a single concatenation to avoid offset drift.
    return (
        manifest_text[:line_start]
        + new_block
        + manifest_text[line_start:expr_start_offset]
        + wrap_prefix
        + manifest_text[expr_start_offset:expr_end_offset]
        + wrap_suffix
        + manifest_text[expr_end_offset:]
    )


_DEPENDENCIES_LABEL_RE = re.compile(r"\bdependencies\s*:")


def _strip_comments_to_spaces(span: str) -> str:
    """Return a string the same length as `span` with line and block
    comment characters (delimiters + body) replaced by spaces. Strings
    and other code are preserved verbatim; newlines are preserved both
    inside and outside comments so per-line offsets stay aligned.

    Comment detection is string-aware: a `//` or `/*` that sits inside
    a string literal isn't treated as a comment start. Block comments
    nest, matching Swift's grammar.

    Used as the stripped view for the backwards tail-shape scan in
    `edit_augment_target_dependencies` so a trailing comment after the
    last element doesn't cause the splice to land inside the comment.
    """
    out = list(span)
    n = len(span)
    i = 0
    while i < n:
        c = span[i]
        if c == "/" and i + 1 < n and span[i + 1] == "/":
            nl = span.find("\n", i + 2)
            end = nl if nl != -1 else n
            for j in range(i, end):
                out[j] = " "
            i = end
            continue
        if c == "/" and i + 1 < n and span[i + 1] == "*":
            block_depth = 1
            j = i + 2
            while j < n and block_depth > 0:
                if j + 1 < n and span[j] == "/" and span[j + 1] == "*":
                    block_depth += 1
                    j += 2
                    continue
                if j + 1 < n and span[j] == "*" and span[j + 1] == "/":
                    block_depth -= 1
                    j += 2
                    continue
                j += 1
            for k in range(i, j):
                if out[k] != "\n":
                    out[k] = " "
            i = j
            continue
        if c == '"':
            # Skip past string literals so a // or /* inside a string
            # isn't blanked. The string body itself stays in `out`.
            j = i + 1
            while j < n:
                cc = span[j]
                if cc == "\\" and j + 1 < n:
                    if span[j + 1] == "(":
                        close_idx = _balanced_close(span, j + 1)
                        if close_idx == -1:
                            break
                        j = close_idx + 1
                        continue
                    j += 2
                    continue
                if cc == '"':
                    j += 1
                    break
                if cc == "\n":
                    break
                j += 1
            i = j
            continue
        i += 1
    return "".join(out)


def _collect_depth_zero_string_literals(span: str) -> set:
    """Return the set of RAW string-literal source spans found at depth
    0 of `span`. Walks character-by-character tracking nesting depth
    and string/comment state; only string literals encountered while
    `depth == 0` are collected.

    "Raw source spans" means the value preserves backslash escapes and
    interpolation segments verbatim — no Swift-level unescaping. For
    `"prefix \\(x) suffix"` the collected element is the literal
    string `prefix \\(x) suffix`. Callers are comparing against
    proposed dep names that they construct as plain identifiers
    (e.g. "InternalCollectionsUtilities"), so the comparison just
    needs both sides to agree on representation. The escape-preserving
    behaviour matches `_swift_string_literal`'s output, which is what
    we'd emit if we ever spliced the same name in.

    Used by `edit_augment_target_dependencies` to test whether a
    proposed dep name is already a member of the array. A naive
    `re.finditer(r'"..."', array_interior)` would falsely match a
    string nested inside `.target(name: "X")` or `.product(name: "Y")`;
    the dependency item there is the WHOLE call, and "X"/"Y" appear at
    depth 1, so they should not count as direct dep names.

    Escape handling: `\\n`, `\\"`, and string-interpolation `\\(...)` are
    consumed as part of the string. Newlines inside an unterminated
    `"..."` end the literal (matches Swift's grammar). Block comments
    nest in Swift; line comments end at `\\n`.
    """
    out: set = set()
    n = len(span)
    i = 0
    depth = 0
    while i < n:
        c = span[i]
        if c == "/" and i + 1 < n and span[i + 1] == "/":
            nl = span.find("\n", i + 2)
            i = nl if nl != -1 else n
            continue
        if c == "/" and i + 1 < n and span[i + 1] == "*":
            block_depth = 1
            j = i + 2
            while j < n and block_depth > 0:
                if j + 1 < n and span[j] == "/" and span[j + 1] == "*":
                    block_depth += 1
                    j += 2
                    continue
                if j + 1 < n and span[j] == "*" and span[j + 1] == "/":
                    block_depth -= 1
                    j += 2
                    continue
                j += 1
            i = j
            continue
        if c == '"':
            j = i + 1
            buf = []
            while j < n:
                cc = span[j]
                if cc == "\\" and j + 1 < n:
                    nxt = span[j + 1]
                    if nxt == "(":
                        close_idx = _balanced_close(span, j + 1)
                        if close_idx == -1:
                            break
                        # Interpolation: opaque to the literal value.
                        buf.append(span[j : close_idx + 1])
                        j = close_idx + 1
                        continue
                    # Other escape sequences: keep them verbatim — the
                    # caller is comparing raw source text against the
                    # dep names it wants to inject, and would have
                    # constructed any escapes the same way.
                    buf.append(span[j : j + 2])
                    j += 2
                    continue
                if cc == '"':
                    j += 1
                    if depth == 0:
                        out.add("".join(buf))
                    break
                if cc == "\n":
                    break
                buf.append(cc)
                j += 1
            i = j
            continue
        if c in "([{":
            depth += 1
            i += 1
            continue
        if c in ")]}":
            if depth > 0:
                depth -= 1
            i += 1
            continue
        i += 1
    return out


def edit_augment_target_dependencies(
    manifest_text: str,
    target_name: str,
    extra_dep_names: Sequence[str],
) -> str:
    """Append string-literal entries to the `dependencies:` array of the
    `.target(name: target_name, ...)` (or `.executableTarget` /
    `.testTarget`) call.

    Used by Execute's dedup-overlap pass to inject "phantom helper"
    deps — internal sibling targets that are in an umbrella's
    transitive dep closure but absent from its direct `dependencies:`
    list. Without the injection, SPM doesn't add the helper's binary
    target slice to the umbrella's `FRAMEWORK_SEARCH_PATHS`, and the
    consumer's compile fails to resolve `import <Helper>` calls
    embedded in another sibling's emitted `.swiftinterface`.

    Canonical case: Apple swift-collections 1.1.4. `Collections` directly
    depends on `[BitCollections, DequeModule, ...]` but each of those
    transitively depends on `InternalCollectionsUtilities` (`kind:
    .hidden`). After dedup-overlap, the siblings become `.binaryTarget`s
    and their `.swiftinterface` files retain `import
    InternalCollectionsUtilities`; SPM only adds slice dirs for binary
    targets in the direct dep list, so `Collections`'s compile can't
    find the helper. Augmenting `Collections`'s `dependencies:` with
    `"InternalCollectionsUtilities"` fixes the search-path gap without
    touching the helper module's own xcframework.

    Idempotent: an entry already present in the array as a quoted
    string literal at depth 0 is skipped. The "depth 0" qualifier matters
    because nested `.target(name: "X")` / `.product(name: "X", ...)`
    forms can mention any name as their own `name:` argument; those
    don't count as members of the outer array. Other forms (a sibling
    referenced as `.target(name: "X")` rather than `"X"`) are NOT
    treated as duplicates — the augmentation appends a plain string
    literal in that case, which SPM accepts alongside the existing
    decorated form.

    Raises `PrepareUserError` if:
      - No `.target(name: target_name, ...)` (or `.executableTarget` /
        `.testTarget`) call exists in the manifest.
      - The target's call has no top-level `dependencies:` argument.
      - The `dependencies:` expression is not an array literal (e.g.
        `dependencies: someComputedArray`) — we don't attempt to
        splice into a name-bound expression.

    Wrapper-style manifests (swift-collections' `CustomTarget.target(
    name:, dependencies:, ...)`) are supported because the regex
    `\.(target|executableTarget|testTarget)\s*\(` matches both
    `CustomTarget.target(` and bare `.target(` calls. The wrapper's
    `dependencies` field is `[Target.Dependency]`-typed, which accepts
    `ExpressibleByStringLiteral` entries the same as a real
    `Target.target` call. The wrapper's `.toTarget()` forwards the list
    verbatim to `Target.target(dependencies:)`, so the injection
    propagates through to SPM's model.
    """
    if not extra_dep_names:
        return manifest_text

    kind_start, close_idx, _kind = _find_target_call_for_name(
        manifest_text, target_name
    )
    if kind_start == -1:
        raise PrepareUserError(
            f"augment_target_dependencies: no `.target(name: {target_name!r}, "
            f"...)` (or .executableTarget/.testTarget) found in the manifest."
        )

    # The call body spans (open_paren+1, close_idx).
    open_idx = manifest_text.index("(", kind_start)
    body_start = open_idx + 1
    body_end = close_idx
    body = manifest_text[body_start:body_end]
    # `_depth_zero_view` blanks string/comment bodies AND nested-scope
    # content while preserving offsets. So a `dependencies:` label
    # nested inside another arg (rare but defensible) cannot false-
    # match, and a label inside a string literal is invisible.
    body_dz = _depth_zero_view(body)

    lm = _DEPENDENCIES_LABEL_RE.search(body_dz)
    if not lm:
        raise PrepareUserError(
            f"augment_target_dependencies: no top-level `dependencies:` "
            f"argument in `.target(name: {target_name!r}, ...)` call."
        )

    # Find the `[` that opens the array literal. Skip whitespace.
    i = lm.end()
    while i < len(body) and body[i] in " \t\n":
        i += 1
    if i >= len(body) or body[i] != "[":
        raise PrepareUserError(
            f"augment_target_dependencies: `dependencies:` expression in "
            f"`.target(name: {target_name!r}, ...)` is not an array literal "
            f"(spotted `{body[i:i+10]!r}` at the position). The injection "
            f"requires a literal `[...]` so it can splice new entries."
        )
    deps_open = i  # relative to body
    deps_close = _balanced_close(body, deps_open)
    if deps_close == -1:
        raise PrepareUserError(
            f"augment_target_dependencies: unmatched `[` for `dependencies:` "
            f"array of `.target(name: {target_name!r}, ...)`."
        )

    # Idempotency: skip entries already present as depth-0 quoted strings.
    # We can't use `_depth_zero_view` here — it blanks string-literal
    # bodies as part of its comment-aware sanitisation, which would
    # leave the regex matching empty strings instead of the actual
    # names. Walk the array interior manually, tracking depth + string/
    # comment state, and capture string literals only at depth 0.
    array_interior = body[deps_open + 1 : deps_close]
    existing_strings = _collect_depth_zero_string_literals(array_interior)

    to_add = [d for d in extra_dep_names if d not in existing_strings]
    if not to_add:
        return manifest_text  # idempotent — all entries already present

    # Pick the right splice shape based on what character sits at the
    # array's logical "tail" (the last non-blank, non-comment char
    # before `]`).
    #   - `[` → empty array; insert `<entries>` (no leading comma needed)
    #   - `,` → trailing comma; insert `<entries>,` (Swift accepts the
    #     extra trailing comma; the existing one provides the separator)
    #   - anything else → content with no trailing comma; insert `,
    #     <entries>` (leading comma supplies the separator)
    #
    # We walk a comment-stripped view of `body` so a trailing line/
    # block comment after the last element doesn't fool the decision.
    # Without the strip, `["A", // note\n]` would land `tail_char='e'`,
    # taking the "anything else" branch — and the inserted ", "B""
    # would land INSIDE the line comment, becoming dead code. Strings
    # stay in the view (a string's closing `"` is a legitimate tail).
    body_for_tail = _strip_comments_to_spaces(body)
    j = deps_close - 1
    while j > deps_open and body_for_tail[j] in " \t\n":
        j -= 1
    tail_char = body_for_tail[j]
    insertion_abs = body_start + j + 1  # right after the last non-blank char

    entries_chunk = ", ".join(
        _swift_string_literal(d) for d in to_add
    )
    if tail_char == "[":
        insertion = entries_chunk
    elif tail_char == ",":
        insertion = " " + entries_chunk + ","
    else:
        insertion = ", " + entries_chunk

    return (
        manifest_text[:insertion_abs]
        + insertion
        + manifest_text[insertion_abs:]
    )


def _find_library_call_for_name(
    text: str, product_name: str
) -> Tuple[int, int]:
    """Locate the `.library(name: "<product_name>", ...)` call whose
    own top-level `name:` argument matches exactly.

    Returns `(open_paren_idx, close_paren_idx)` — the offsets of the
    matching `(` and `)`. Returns `(-1, -1)` if no matching library
    declaration is found.

    Same code-only + depth-0 filtering as `_find_target_call_for_name`
    so a `name:` reference inside a nested `targets:` array, a comment,
    or a string literal cannot false-match.
    """
    code_view = _make_code_token_view(text)
    pos = 0
    while True:
        m = _LIBRARY_CALL_RE.search(code_view, pos)
        if not m:
            return -1, -1
        open_idx = m.end() - 1
        close_idx = _balanced_close(text, open_idx)
        if close_idx == -1:
            raise PrepareUserError(
                f"Could not find balanced `)` for .library( at offset "
                f"{open_idx}; the manifest may be malformed."
            )
        span = text[open_idx + 1 : close_idx]
        if _top_level_name_label(span) == product_name:
            return open_idx, close_idx
        pos = close_idx + 1


_TYPE_DYNAMIC_ARG_RE = re.compile(
    r"(?P<lead>[,\s]*)type\s*:\s*\.dynamic\s*(?P<trail>,?)"
)


def _depth_zero_view(span: str) -> str:
    """Return a view of `span` where every character that is NOT at the
    top level (depth 0) of the span's call body is replaced by a single
    space. Comment bodies and string-literal bodies are also blanked.
    Length and per-character offsets are preserved one-to-one with
    `span`.

    This is the offset-preserving analogue of `_flatten_to_top_level`:
    `flatten` collapses nested scopes into single spaces (losing
    offsets), this preserves alignment so the caller can splice based
    on regex match indices into the ORIGINAL `span`.

    Used by `edit_demote_synthetic_product` to find the `type: .dynamic`
    argument's depth-0 location without false-matching a literal
    `type: .dynamic` that might appear inside a nested `targets:` array
    (defensive — unlikely in practice but cheap to guard against).
    """
    out = list(span)
    n = len(span)
    i = 0
    depth = 0
    while i < n:
        c = span[i]
        if c == "/" and i + 1 < n and span[i + 1] == "/":
            nl = span.find("\n", i + 2)
            end = nl if nl != -1 else n
            for j in range(i, end):
                out[j] = " "
            i = end
            continue
        if c == "/" and i + 1 < n and span[i + 1] == "*":
            block_depth = 1
            j = i + 2
            while j < n and block_depth > 0:
                if j + 1 < n and span[j] == "/" and span[j + 1] == "*":
                    block_depth += 1
                    j += 2
                    continue
                if j + 1 < n and span[j] == "*" and span[j + 1] == "/":
                    block_depth -= 1
                    j += 2
                    continue
                j += 1
            for k in range(i, j):
                out[k] = " "
            i = j
            continue
        if c == '"':
            j = i + 1
            while j < n:
                cc = span[j]
                if cc == "\\" and j + 1 < n:
                    if span[j + 1] == "(":
                        close_idx = _balanced_close(span, j + 1)
                        if close_idx == -1:
                            break
                        j = close_idx + 1
                        continue
                    j += 2
                    continue
                if cc == '"':
                    j += 1
                    break
                if cc == "\n":
                    break
                j += 1
            for k in range(i, j):
                out[k] = " "
            i = j
            continue
        if c in "([{":
            close = _balanced_close(span, i)
            if close == -1:
                # Malformed nesting — bail out cleanly. Subsequent regex
                # search will fail to find a match and the caller will
                # fall through to its idempotent no-op branch.
                break
            # Keep the open/close delimiters themselves at depth 0;
            # blank their interior so any depth-N content is invisible.
            for k in range(i + 1, close):
                if out[k] != "\n":
                    out[k] = " "
            i = close  # process the closing delimiter next iteration
            continue
        if depth != 0 and c != "\n":
            out[i] = " "
        i += 1
    return "".join(out)


def edit_demote_synthetic_product(
    manifest_text: str, product_name: str
) -> str:
    """Strip the `type: .dynamic` argument from the synthetic
    `.library(name: "<product_name>", type: .dynamic, targets: [...])`
    declaration, leaving the "automatic-library" shape
    `.library(name: "<product_name>", targets: [...])`.

    Why we need this: when the planner emits a `synth_dynamic_library`
    edit for product P over target T, then T is built into its own
    xcframework, dedup-overlap wants to rewrite later units'
    `.target(name: T, ...)` references to `.binaryTarget(name: T, ...)`.
    SPM rejects the resulting manifest because the surviving
    `.library(type: .dynamic, targets: [T])` product now points at a
    binary-only target:

        "invalid type for binary product; products referencing only
         binary targets must be executable or automatic library
         products"

    Demoting the product to "automatic library" (no `type:` argument)
    keeps the product alive — its name continues to appear in
    `swift package describe`, downstream consumers can still depend on
    it by product name — and unblocks the binaryTarget substitution.
    The product's emitted linkage becomes whatever SPM decides
    ("automatic"), but the linkage doesn't matter at consumer time:
    the consumer is linking the binary we already produced, not
    re-building T's sources.

    Idempotent: if the product is already in automatic-library shape
    (no top-level `type: .dynamic` argument inside the call body),
    the function returns the text unchanged. Raises `PrepareUserError`
    if no `.library(name: "<product_name>", ...)` is found.

    Parameters:
      manifest_text — full Package.swift text to edit
      product_name  — exact name of the product (the synthetic name,
                      e.g. `FooDynamic`)

    Returns the edited manifest text. Caller writes it back.
    """
    open_idx, close_idx = _find_library_call_for_name(
        manifest_text, product_name
    )
    if open_idx == -1:
        raise PrepareUserError(
            f"demote_synthetic_product: no `.library(name: {product_name!r}, "
            f"...)` declaration found in the manifest."
        )

    span = manifest_text[open_idx + 1 : close_idx]
    # Use the offset-preserving depth-0 view (NOT `_flatten_to_top_level`,
    # which collapses nested scopes into single spaces and breaks
    # offset alignment). A `type: .dynamic` literal nested inside the
    # call body (e.g. a hypothetical defensive case where some user
    # supplies a nested closure argument) won't false-match. The view
    # also blanks string-literal bodies into spaces — so we re-derive
    # the lead text from `span` (not from `m.group`), or the blanked
    # `"<name>"` between the previous arg and `type:` would be spliced
    # back in as raw whitespace.
    view = _depth_zero_view(span)
    m = _TYPE_DYNAMIC_ARG_RE.search(view)
    if m is None:
        return manifest_text  # already automatic-shape; idempotent no-op
    arg_start = m.start()
    arg_end = m.end()
    lead_in_span = span[arg_start : arg_start + len(m.group("lead"))]
    has_trailing_comma = bool(m.group("trail"))
    # Two argument-position cases:
    #
    # 1. `type:` is followed by another sibling (it captured a trailing
    #    comma). The separator BEFORE `type:` (a comma plus indent for
    #    the SPM multiline shape, or a `, ` for a single-line manifest)
    #    must stay — it now precedes the next sibling. We strip the
    #    trailing horizontal whitespace from that lead so the now-empty
    #    line doesn't leave phantom indentation. The comma+newline (and
    #    the preceding argument's text) survive.
    # 2. `type:` is the LAST argument (no trailing comma). The lead
    #    contains the comma that separated `type:` from the previous
    #    sibling — drop the entire lead so the previous sibling
    #    becomes the last argument and gets the closing `)`.
    if has_trailing_comma:
        new_span = (
            span[:arg_start] + lead_in_span.rstrip(" \t") + span[arg_end:]
        )
    else:
        new_span = span[:arg_start] + span[arg_end:]

    return (
        manifest_text[: open_idx + 1] + new_span + manifest_text[close_idx:]
    )


def _swift_toolchain_version() -> Optional[Tuple[int, int, int]]:
    """Return the Swift toolchain `(major, minor, patch)`, or None if it
    can't be parsed.

    Used by `_select_active_manifest` to mirror SPM's manifest-selection
    rule: SPM picks the highest `Package@swift-X.Y[.Z].swift` whose version
    is `<=` the active toolchain version, falling back to `Package.swift`.
    """
    try:
        cp = subprocess.run(
            ["swift", "--version"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
    except (FileNotFoundError, OSError):
        return None
    if cp.returncode != 0:
        return None
    m = re.search(r"Swift version (\d+)\.(\d+)(?:\.(\d+))?", cp.stdout or "")
    if not m:
        return None
    return (int(m.group(1)), int(m.group(2)), int(m.group(3) or 0))


_TOOLS_VERSION_RE = re.compile(
    r"//\s*swift-tools-version[: ]\s*(\d+)(?:\.(\d+))?(?:\.(\d+))?"
)


def _read_declared_tools_version(path: Path) -> Optional[Tuple[int, int, int]]:
    """Parse the `// swift-tools-version: X.Y[.Z]` line from a manifest.

    SPM mandates this line as the very first line of every Package.swift
    (base or version-specific). Returns None on missing/unparseable lines.
    """
    try:
        with path.open("r", encoding="utf-8", errors="replace") as fh:
            for _ in range(8):
                line = fh.readline()
                if not line:
                    break
                m = _TOOLS_VERSION_RE.search(line)
                if m:
                    return (
                        int(m.group(1)),
                        int(m.group(2) or 0),
                        int(m.group(3) or 0),
                    )
    except OSError:
        return None
    return None


def _bump_tools_version_if_below(
    manifest_path: Path, min_version: Tuple[int, int]
) -> Optional[Tuple[int, int, int]]:
    """Rewrite the manifest's `// swift-tools-version: X.Y` line to
    `min_version` if currently below it. Returns the original parsed
    version if a bump was applied, else None.

    Why: `swift package add-product` requires tools-version >= 5.2; SPM's
    own error message recommends bumping to 5.5+. Old packages like
    MBProgressHUD (4.2) use only the manifest-format subset that's
    backward-compatible with 5.5, so bumping doesn't break the build —
    it just unblocks the synthetic-product edit.
    """
    declared = _read_declared_tools_version(manifest_path)
    if declared is None:
        return None
    if declared[:2] >= min_version:
        return None
    try:
        text = manifest_path.read_text(encoding="utf-8")
    except OSError:
        return None
    lines = text.splitlines(keepends=True)
    replacement = f"// swift-tools-version: {min_version[0]}.{min_version[1]}\n"
    for i, line in enumerate(lines[:8]):
        if _TOOLS_VERSION_RE.search(line):
            lines[i] = replacement
            manifest_path.write_text("".join(lines), encoding="utf-8")
            return declared
    return None


def _select_active_manifest(staged_dir: Path) -> Path:
    """Pick the Package.swift file SPM will actually read for this toolchain.

    Mirrors SPM's actual selection rule (SE-0152): for every candidate
    manifest in the package root (`Package.swift` and any sibling
    `Package@swift-X.Y[.Z].swift`), parse the `// swift-tools-version` line
    declared *inside* that file and pick the file whose declared
    tools-version is the highest one still `<=` the active toolchain.

    The filename's `@swift-X.Y` suffix is just a sort hint, not the
    selection key — Alamofire 5.10.2 ships `Package.swift` with
    `swift-tools-version: 6.0` plus `Package@swift-5.10.swift` (5.10) plus
    `Package@swift-5.9.swift` (5.9), and on a 6.x toolchain SPM picks
    `Package.swift` because 6.0 is the highest fitting tools-version.
    Selecting by filename alone — as the original implementation did —
    edits the wrong file and the round-trip validator catches it as a
    silent no-op when `dump-package` re-reads the real active manifest.

    Falls back to `Package.swift` if the toolchain version can't be parsed
    or if no manifest declares a tools-version we can read.
    """
    # Late-bind through the package namespace so tests that monkey-patch
    # `spm_to_xcframework._swift_toolchain_version` are honored at call
    # time. A direct local reference would freeze the toolchain probe
    # into this module's globals and silently ignore the patch.

    base = staged_dir / "Package.swift"
    tc = _swift_toolchain_version()
    if tc is None:
        return base

    candidates: List[Path] = []
    if base.is_file():
        candidates.append(base)
    candidates.extend(sorted(staged_dir.glob("Package@swift-*.swift")))

    best: Optional[Tuple[Tuple[int, int, int], Path]] = None
    for candidate in candidates:
        declared = _read_declared_tools_version(candidate)
        if declared is None:
            continue
        if declared > tc:
            continue
        # Tie-break by declared version, then prefer the un-suffixed
        # `Package.swift` over `Package@swift-X.Y.swift` on identical
        # tools-versions (matches SPM, which treats the base manifest as
        # canonical when both declare the same version).
        if best is None or declared > best[0] or (
            declared == best[0] and candidate.name == "Package.swift"
        ):
            best = (declared, candidate)
    return best[1] if best is not None else base


def _add_product_via_active_manifest_proxy(
    staged_dir: Path,
    active_manifest: Path,
    product_name: str,
    targets: Sequence[str],
) -> None:
    """Run `swift package add-product` so the edit lands in
    `active_manifest`, even when SPM picks a version-specific manifest
    (e.g. Package@swift-5.9.swift) over the base Package.swift.

    Problem: `swift package add-product` is hard-coded to edit
    `Package.swift`. When SPM selects a version-specific manifest as
    active, the call returns 0, edits Package.swift, and leaves the
    active manifest untouched — `dump-package` (which reads the active)
    then shows no product and round-trip validation rejects the edit as
    a silent no-op. Reproduced on Nuke 12.8.0 and swift-dependencies
    1.6.3 (both ship Package.swift + Package@swift-5.9.swift).

    Fix: temporarily put the active manifest's text into Package.swift,
    run add-product (which edits Package.swift in place), then copy the
    edited content back to the active manifest and restore the original
    Package.swift.
    """
    base_manifest = staged_dir / "Package.swift"
    if active_manifest == base_manifest:
        _invoke_swift_add_product(staged_dir, product_name, targets)
        return

    base_existed = base_manifest.is_file()
    base_text_before = base_manifest.read_text() if base_existed else None
    active_text = active_manifest.read_text()
    try:
        base_manifest.write_text(active_text)
        _invoke_swift_add_product(staged_dir, product_name, targets)
        active_manifest.write_text(base_manifest.read_text())
    finally:
        # Restore the original state. If Package.swift didn't exist before
        # (legal per SE-0152: a package may ship only version-specific
        # manifests), unlink the temporary file we wrote so we don't leave
        # a ghost manifest behind that the package never had. Skipping this
        # would change the manifest set the package presents to SPM on the
        # next invocation.
        if base_text_before is not None:
            base_manifest.write_text(base_text_before)
        elif not base_existed and base_manifest.is_file():
            base_manifest.unlink()


def _apply_single_synth_edit(
    staged_dir: Path,
    active_manifest: Path,
    product_name: str,
    targets: Sequence[str],
) -> None:
    """Add one synthetic dynamic library via add-product, falling back to
    manual text surgery if SPM rejects the manifest's `products:` shape.

    SPM's add-product requires `products: [ ... ]` to be a literal array
    expression in the source. swift-collections (and other packages that
    build their product list programmatically) instead write something
    like `products: _products`, which SPM rejects with "unable to find
    array literal for 'products' argument". In that case we fall through
    to `edit_append_synth_product_to_package`, which appends the
    synthetic entry via a `+ [...]` expression that works for both
    literal arrays and non-literal expressions.
    """
    try:
        _add_product_via_active_manifest_proxy(
            staged_dir, active_manifest, product_name, targets
        )
        return
    except PrepareBug as exc:
        if "unable to find array literal" not in str(exc).lower():
            raise
        info(
            f"  swift add-product can't edit non-literal `products:`; "
            f"falling back to manual surgery for {product_name}"
        )

    edited = edit_append_synth_product_to_package(
        active_manifest.read_text(), product_name, targets
    )
    active_manifest.write_text(edited)


def _invoke_swift_add_product(
    staged_dir: Path, product_name: str, targets: Sequence[str]
) -> None:
    """Call `swift package add-product <name> --type dynamic-library --targets t1 t2 ...`
    in `staged_dir`.

    The targets argv must be SPACE-separated, NOT comma-separated. SwiftPM's
    `--targets <targets> ...` declaration is a variadic value list, so
    `--targets A,B,C` is parsed as the single literal `"A,B,C"` and ends up
    written to Package.swift as `targets: ["A,B,C"]`, which then fails
    `swift package resolve` with "no such target". `--targets A B C`
    produces `targets: ["A", "B", "C"]`, which is what we want.

    Failure surface: the subprocess can fail for several reasons — the
    package's tools-version is too old to support `add-product`, a product
    with the requested name already exists, or the manifest is malformed.
    We surface stderr verbatim so the user can read the SPM error.

    Tools-version-too-old is the one failure mode the user can fix
    without filing a planner bug (bump the package's
    `swift-tools-version:` line, or fall back to the legacy regex-based
    surgery on an older spm-to-xcframework). That case is routed as
    `PrepareUserError` so the CLI renders the clean
    `Error (prepare): ...` envelope instead of a Python traceback.
    Everything else stays `PrepareBug`. (Grok final-review Low #2.)
    """
    argv = [
        "swift",
        "package",
        "add-product",
        product_name,
        "--type",
        "dynamic-library",
        "--targets",
        *list(targets),
    ]
    cp = subprocess.run(
        argv,
        cwd=str(staged_dir),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    if cp.returncode != 0:
        tail = "\n".join((cp.stderr or "").rstrip().splitlines()[-15:])
        stderr_lower = (cp.stderr or "").lower()
        if (
            "unknown command 'add-product'" in stderr_lower
            or "unknown subcommand 'add-product'" in stderr_lower
            or ("add-product" in stderr_lower and "requires" in stderr_lower)
            or ("tools-version" in stderr_lower and "add-product" in stderr_lower)
        ):
            raise PrepareUserError(
                f"`swift package add-product` is not available in this "
                f"toolchain for {staged_dir}. The package's "
                f"swift-tools-version may be too old (add-product was added "
                f"in 5.2) — bump the manifest to a supported version, or "
                f"pin to an older spm-to-xcframework that used regex-based "
                f"Package.swift edits.\n" + (tail or "  (no stderr)")
            )
        raise PrepareBug(
            f"`swift package add-product {product_name}` failed in "
            f"{staged_dir}:\n" + (tail or "  (no stderr)")
        )


def apply_package_swift_edits(staged_dir: Path, plan: Plan) -> str:
    """Apply `plan.package_swift_edits` to the active Package.swift in
    `staged_dir`.

    "Active" means the manifest SPM actually reads for this toolchain —
    if the package ships a `Package@swift-X.Y.swift` whose version is
    `<=` the active Swift toolchain, that file is mutated *instead of*
    `Package.swift`. This matches what `swift package dump-package` and
    `xcodebuild` see, so the planner's edit decisions (which were derived
    from the same dump) line up with the file we mutate.

    All synth_* edits are applied by shelling out to `swift package
    add-product`, which mutates the active manifest in place. We snapshot
    the original first so the round-trip validator can render a unified
    diff on failure.

    Side effects:
      - Writes `.original-<basename>` next to the active manifest as a
        debugging artifact (only if not already present from a prior run).
      - Invokes `swift package add-product` once per synth_* edit.

    Returns the original (pre-edit) manifest text. The caller passes that
    to `validate_prepared_manifest` so a validation failure can render a
    diff against the same baseline this function used.
    """
    manifest_path = _select_active_manifest(staged_dir)
    if not manifest_path.is_file():
        raise PrepareBug(f"No Package.swift at {manifest_path}")

    original_text = manifest_path.read_text()
    # Sanity check: the manifest must not use Swift constructs the
    # `replace_with_binary_target` walker can't reason about. Even though
    # the synth_* edits run through `swift package add-product` (which
    # parses the manifest properly), Execute may later apply a
    # `replace_with_binary_target` edit using our balanced-paren walker,
    # so we still need to gate raw strings / triple-quotes / interpolation
    # up front and abort with a clear message.
    _assert_no_unsupported_swift_constructs(original_text)

    # Snapshot the original for debugging. Don't clobber a prior snapshot:
    # if a previous run failed mid-Prepare, the .original from that run is
    # the *real* original and overwriting it would lose information.
    snapshot_path = manifest_path.parent / f".original-{manifest_path.name}"
    if not snapshot_path.exists():
        snapshot_path.write_text(original_text)

    # `swift package add-product` rejects manifests below tools-version
    # 5.2 (SPM's own error message recommends 5.5). Old packages like
    # MBProgressHUD (4.2) work fine under 5.5's manifest format — just
    # bump the line before invoking add-product. Only relevant when the
    # plan actually has synth edits.
    has_synth = any(
        edit.kind in ("synth_dynamic_library", "synth_library")
        for edit in plan.package_swift_edits
    )
    if has_synth:
        bumped_from = _bump_tools_version_if_below(manifest_path, (5, 5))
        if bumped_from is not None:
            info(
                f"  Bumped swift-tools-version "
                f"{bumped_from[0]}.{bumped_from[1]} → 5.5 "
                f"in {manifest_path.name} (required for add-product)"
            )

    # Apply edits in plan order so the post-edit products array reflects
    # planner sequencing. synth_dynamic_library and synth_library are both
    # implemented by the same `swift package add-product` call; the only
    # difference is naming policy at plan time. Routed through a
    # base-manifest proxy because add-product is hard-coded to edit
    # Package.swift even when SPM is reading Package@swift-X.Y.swift,
    # and through a surgery fallback when the manifest's `products:` is
    # not a literal array.
    for edit in plan.package_swift_edits:
        if edit.kind in ("synth_dynamic_library", "synth_library"):
            _apply_single_synth_edit(
                staged_dir, manifest_path, edit.product_name, edit.targets
            )

    return original_text


def validate_prepared_manifest(
    staged_dir: Path,
    plan: Plan,
    original_text: str,
) -> Tuple[dict, List[Product], List[Target], List[Platform], str, str]:
    """Round-trip the edited Package.swift through `swift package dump-package`
    and assert every planner-requested edit landed correctly.

    On success, returns the parsed dump shards (the same shape `dump_package`
    returns) so the caller can build a Package model with whatever schemes
    list it wants attached. On failure, raises PrepareError.

    Asserts (per design §5.3):
      1. The dump still parses (handled by raising InspectError → caught
         and re-raised as PrepareError with diff context).
      2. Every `synth_dynamic_library` / `synth_library` edit produced a
         product with the synthetic name, linkage DYNAMIC, and the
         requested target list.
      3. Every build unit the planner intends to archive (i.e. not a
         copy-artifact) corresponds to a present product in the dumped
         manifest — looked up by `unit.scheme` because that is the name
         xcodebuild actually builds. For `synth_dynamic_library` units,
         `scheme` is the synthetic product name; the framework rename to
         `unit.framework_name` happens in Execute, not here.

    On any failure, raises PrepareError with the failed assertion(s), a
    unified diff between the pre-edit and post-edit manifests, and a JSON
    snapshot of any directly-implicated post-edit products.
    """
    manifest_path = _select_active_manifest(staged_dir)
    edited_text = manifest_path.read_text() if manifest_path.is_file() else ""

    try:
        raw, products, targets, platforms, name, tools_version = dump_package(staged_dir)
    except InspectError as exc:
        diff = _unified_diff(original_text, edited_text, label=manifest_path.name)
        raise PrepareBug(
            f"Round-trip validation failed: edited {manifest_path.name} no longer "
            f"parses through `swift package dump-package`.\n\nUnderlying "
            f"error:\n  {exc}\n\nUnified diff (original → edited):\n{diff}"
        ) from exc

    products_by_name = {p.name: p for p in products}
    failures: List[str] = []
    implicated: List[Product] = []

    for edit in plan.package_swift_edits:
        if edit.kind not in ("synth_dynamic_library", "synth_library"):
            continue
        prod = products_by_name.get(edit.product_name)
        if prod is None:
            failures.append(
                f"{edit.kind}: product {edit.product_name!r} is absent from "
                f"the post-edit dumped manifest (the synthetic .library() "
                f"entry didn't take effect)"
            )
            continue
        if prod.linkage != Linkage.DYNAMIC:
            failures.append(
                f"{edit.kind}: product {edit.product_name!r} has linkage "
                f"{prod.linkage!r}; expected {Linkage.DYNAMIC!r}"
            )
            implicated.append(prod)
        expected_targets = list(edit.targets)
        if list(prod.targets) != expected_targets:
            failures.append(
                f"{edit.kind}: product {edit.product_name!r} targets are "
                f"{prod.targets!r}; expected {expected_targets!r}"
            )
            implicated.append(prod)

    # Cross-check: every non-copy-artifact build unit must correspond to a
    # present product. Try `unit.framework_name` first (the original
    # product name, present for already-dynamic units and still present
    # alongside the synthetic for synth_dynamic_library units). Fall back
    # to `unit.scheme` so synth_library units (where the new product
    # equals the requested target name) and synth_dynamic_library units
    # (where the synthetic product is what xcodebuild actually builds)
    # are both accepted. For non-synth units whose scheme is the
    # `<product>-Package` variant, the framework_name branch already
    # matched; the scheme fallback never trips on those.
    for unit in plan.build_units:
        if unit.archive_strategy == "copy-artifact":
            continue
        if unit.framework_name in products_by_name:
            continue
        if unit.scheme in products_by_name:
            continue
        failures.append(
            f"build_unit {unit.name!r}: neither framework_name "
            f"{unit.framework_name!r} nor scheme {unit.scheme!r} is "
            f"present in the post-edit dumped manifest (planner expected "
            f"this product to exist)"
        )

    if failures:
        diff = _unified_diff(original_text, edited_text, label=manifest_path.name)
        impl_block = ""
        if implicated:
            seen = set()
            unique = []
            for p in implicated:
                if p.name in seen:
                    continue
                seen.add(p.name)
                unique.append(p)
            impl_lines = [
                f"  - {p.name}: linkage={p.linkage}, targets={p.targets}"
                for p in unique
            ]
            impl_block = "\n\nImplicated post-edit products:\n" + "\n".join(impl_lines)
        bullet = "\n".join(f"  - {f}" for f in failures)
        raise PrepareBug(
            "Round-trip validation failed:\n"
            + bullet
            + impl_block
            + "\n\nUnified diff (original → edited):\n"
            + diff
        )

    # Re-resolve dependencies whenever Prepare added a synthetic library
    # — new products can pull new transitive deps that need
    # .build/checkouts. Both synth_dynamic_library and synth_library
    # qualify.
    if any(
        e.kind in ("synth_dynamic_library", "synth_library")
        for e in plan.package_swift_edits
    ):
        cp = subprocess.run(
            ["swift", "package", "resolve"],
            cwd=str(staged_dir),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
        )
        if cp.returncode != 0:
            tail = "\n".join((cp.stderr or "").rstrip().splitlines()[-10:])
            raise PrepareBug(
                "swift package resolve failed after Prepare added synthetic "
                "libraries:\n" + (tail or "  (no stderr)")
            )

    return raw, products, targets, platforms, name, tools_version


def _unified_diff(original: str, edited: str, label: str = "Package.swift") -> str:
    """Render a unified diff between two manifest texts. Used in
    PrepareError messages so users (and the test harness) can see exactly
    what surgery Prepare attempted.

    Imported lazily because difflib is rarely needed at runtime — the
    happy path doesn't render diffs at all.
    """
    import difflib

    return "".join(
        difflib.unified_diff(
            original.splitlines(keepends=True),
            edited.splitlines(keepends=True),
            fromfile=f"{label} (pre-edit)",
            tofile=f"{label} (post-edit)",
            n=3,
        )
    )


def prepare(staged_dir: Path, plan: Plan, *, verbose: bool = False) -> PreparedPlan:
    """Top-level Prepare entry point.

    Applies the planner's whitelisted edits to `staged_dir/Package.swift`
    and runs the mandatory round-trip validator. Returns a PreparedPlan
    that wraps the original Plan and the post-edit Package model. Schemes
    from the inspect-time discovery are preserved on the returned Package
    (synthetic libraries don't need pre-discovered schemes — xcodebuild
    auto-generates them at archive time against our clean staged dir).
    """
    info("Preparing Package.swift edits...")
    active_manifest = _select_active_manifest(staged_dir)
    if active_manifest.name != "Package.swift":
        verbose_log(
            verbose,
            f"  Active manifest: {active_manifest.name} (selected by toolchain)",
        )
    no_op = not plan.package_swift_edits
    if no_op:
        verbose_log(verbose, "  No Package.swift edits requested by planner.")
        # Re-dump anyway so PreparedPlan.package reflects whatever the
        # current manifest says — Execute reads it for diagnostic context.
        raw, products, targets, platforms, name, tv = dump_package(staged_dir)
        return PreparedPlan(
            plan=plan,
            package=Package(
                name=name,
                tools_version=tv,
                platforms=platforms,
                products=products,
                targets=targets,
                schemes=[],
                raw_dump=raw,
                staged_dir=staged_dir,
            ),
        )

    for edit in plan.package_swift_edits:
        if edit.kind in ("synth_dynamic_library", "synth_library"):
            verbose_log(
                verbose,
                f"  edit: {edit.kind} {edit.product_name} → "
                f"targets={edit.targets}",
            )

    original = apply_package_swift_edits(staged_dir, plan)
    raw, products, targets, platforms, name, tv = validate_prepared_manifest(
        staged_dir, plan, original
    )
    success(f"  Prepare validated {len(plan.package_swift_edits)} edit(s) ✓")
    return PreparedPlan(
        plan=plan,
        package=Package(
            name=name,
            tools_version=tv,
            platforms=platforms,
            products=products,
            targets=targets,
            # The schemes the planner saw at inspect time still describe the
            # pre-edit manifest, but synthetic-library schemes are
            # auto-generated by xcodebuild at archive time against our clean
            # staged dir, so the build unit's `scheme` field is what Execute
            # actually consumes. We leave schemes empty here rather than
            # carrying a stale list across the Prepare boundary.
            schemes=[],
            raw_dump=raw,
            staged_dir=staged_dir,
        ),
    )


# ============================================================================
# --- prune_child.py --------------------------------------------------------
# ============================================================================


import json
import os
import re
import stat
import subprocess
from pathlib import Path
from typing import Dict, List, Optional, Set, Tuple



def _identity_from_url(url: str) -> str:
    """SPM identity = last URL path component, `.git` stripped, lowercased.

    SPM normalises identities this way internally for `.product(name:,
    package: <identity>)` references, so this mirrors the matching used
    elsewhere in the codebase (e.g. `_discover_transitive_packages`
    in inspect.py).
    """
    s = url.strip().rstrip("/")
    if not s:
        return ""
    last = s.rsplit("/", 1)[-1]
    if last.endswith(".git"):
        last = last[:-4]
    return last.lower()


def _is_word_boundary(text: str, idx: int) -> bool:
    """True iff `idx` is past end-of-text or the char there isn't an
    identifier continuation char. Used to confirm `#if` isn't actually
    the start of `#iffoo` or `#ifdef` (the latter doesn't exist in
    Swift but a defensive check is cheap).
    """
    if idx >= len(text):
        return True
    c = text[idx]
    return not (c.isalnum() or c == "_")


def _scan_keyword_after_hash(view: str, hash_idx: int) -> Tuple[str, int]:
    """Given a `#` at view[hash_idx], return (keyword, end_idx) where
    `keyword` is the directive keyword (e.g. "if", "endif", "elseif")
    and `end_idx` points one past the keyword. Skips whitespace between
    `#` and the keyword. Returns ("", hash_idx + 1) on no match.
    """
    j = hash_idx + 1
    n = len(view)
    while j < n and view[j] in " \t":
        j += 1
    start = j
    while j < n and (view[j].isalnum() or view[j] == "_"):
        j += 1
    return view[start:j], j


def _find_matching_endif(view: str, hash_idx: int) -> int:
    """Given a `#if` at `view[hash_idx]`, return the index of the matching
    `#endif`'s `#`. Handles nested `#if`/`#elseif`/`#else`/`#endif`.
    Returns -1 if not found.
    """
    n = len(view)
    kw, i = _scan_keyword_after_hash(view, hash_idx)
    if kw != "if":
        return -1
    nesting = 1
    while i < n:
        if view[i] != "#":
            i += 1
            continue
        kw, after = _scan_keyword_after_hash(view, i)
        if kw == "if":
            nesting += 1
            i = after
            continue
        if kw == "endif":
            nesting -= 1
            if nesting == 0:
                return i
            i = after
            continue
        # else / elseif keep nesting, skip past.
        i = after if after > i else i + 1
    return -1


def _strip_top_level_package_mutation_blocks(source: str) -> Tuple[str, List[str]]:
    """Pass A: drop top-level `#if … #endif` blocks whose body mentions
    `package.dependencies` or `package.targets`.

    Returns (edited_source, removal_reasons). Reasons are human-readable
    strings the caller can verbose-log.
    """
    view = _make_code_token_view(source)
    n = len(view)
    depth = 0
    i = 0
    spans: List[Tuple[int, int, str]] = []  # (start, end_exclusive, reason)
    while i < n:
        c = view[i]
        if c in "({[":
            depth += 1
            i += 1
            continue
        if c in ")}]":
            depth -= 1
            i += 1
            continue
        if c == "#" and depth == 0:
            kw, after = _scan_keyword_after_hash(view, i)
            if kw == "if" and _is_word_boundary(view, after):
                endif_idx = _find_matching_endif(view, i)
                if endif_idx == -1:
                    i += 1
                    continue
                # Slice the body from the source (use source to inspect, since
                # _make_code_token_view blanks strings/comments but keeps
                # identifiers). We want to know if the body references
                # `package.dependencies` or `package.targets` as code.
                body_end = _scan_keyword_after_hash(view, endif_idx)[1]
                body_view = view[after:endif_idx]
                if (
                    "package.dependencies" in body_view
                    or "package.targets" in body_view
                ):
                    # Compute the actual removal span in `source`, swallowing
                    # the trailing newline (and the leading newline if the
                    # `#if` started its own line) to keep the file tidy.
                    start = i
                    if start > 0 and source[start - 1] == "\n":
                        start -= 1
                    end = body_end
                    if end < len(source) and source[end] == "\n":
                        end += 1
                    spans.append(
                        (start, end, f"#if block mutating package.* (at offset {i})")
                    )
                    i = body_end
                    continue
        i += 1

    if not spans:
        return source, []

    out_parts: List[str] = []
    reasons: List[str] = []
    cursor = 0
    for start, end, reason in spans:
        out_parts.append(source[cursor:start])
        cursor = end
        reasons.append(reason)
    out_parts.append(source[cursor:])
    return "".join(out_parts), reasons


def _find_package_call(source: str) -> Optional[Tuple[int, int]]:
    """Locate the top-level `Package(...)` constructor call. Returns
    (open_paren_idx, close_paren_idx_inclusive) or None if not found.
    """
    view = _make_code_token_view(source)
    # Look for `Package` token at file scope. Be tolerant of leading
    # whitespace between identifier and `(`.
    for m in re.finditer(r"\bPackage\b", view):
        j = m.end()
        n = len(view)
        while j < n and view[j] in " \t\r\n":
            j += 1
        if j < n and view[j] == "(":
            close = _balanced_close(source, j)
            if close != -1:
                return (j, close)
    return None


def _find_dependencies_array_in_package_call(
    source: str,
) -> Optional[Tuple[int, int]]:
    """Within the top-level `Package(...)`, find the `dependencies: [...]`
    argument array. Returns (open_bracket_idx, close_bracket_idx_inclusive)
    or None if the argument isn't present.
    """
    pkg_call = _find_package_call(source)
    if not pkg_call:
        return None
    open_paren, close_paren = pkg_call
    view = _make_code_token_view(source)
    inside_start = open_paren + 1
    inside_end = close_paren  # exclusive of `)`
    depth = 0
    i = inside_start
    while i < inside_end:
        c = view[i]
        if c in "({[":
            depth += 1
            i += 1
            continue
        if c in ")}]":
            depth -= 1
            i += 1
            continue
        if depth == 0:
            # Match `dependencies:` label at the start of an arg position.
            if (
                view.startswith("dependencies", i)
                and (i + 12 >= inside_end or not (view[i + 12].isalnum() or view[i + 12] == "_"))
            ):
                j = i + 12
                while j < inside_end and view[j] in " \t\r\n":
                    j += 1
                if j < inside_end and view[j] == ":":
                    j += 1
                    while j < inside_end and view[j] in " \t\r\n":
                        j += 1
                    if j < inside_end and view[j] == "[":
                        close = _balanced_close(source, j)
                        if close == -1:
                            return None
                        return (j, close)
                    return None
        i += 1
    return None


_PACKAGE_ENTRY_URL_RE = re.compile(r'url\s*:\s*"([^"]+)"')


def _prune_top_level_package_entries(
    source: str, needed_identities: Set[str]
) -> Tuple[str, List[str]]:
    """Pass C: in the top-level `Package(...) dependencies: [...]`,
    drop `.package(url:)` entries whose identity isn't in
    `needed_identities`.

    Returns (edited_source, removal_reasons). If the dependencies array
    isn't found, no-op.
    """
    arr = _find_dependencies_array_in_package_call(source)
    if not arr:
        return source, []
    open_b, close_b = arr  # close_b points at the `]`
    view = _make_code_token_view(source)
    inside_start = open_b + 1
    inside_end = close_b

    spans: List[Tuple[int, int, str]] = []
    depth = 0
    i = inside_start
    while i < inside_end:
        c = view[i]
        if c in "({[":
            depth += 1
            i += 1
            continue
        if c in ")}]":
            depth -= 1
            i += 1
            continue
        if depth == 0 and c == ".":
            # Looking for `.package(`
            j = i + 1
            while j < inside_end and view[j] in " \t\r\n":
                j += 1
            if view.startswith("package", j) and (
                j + 7 >= inside_end or not (view[j + 7].isalnum() or view[j + 7] == "_")
            ):
                k = j + 7
                while k < inside_end and view[k] in " \t\r\n":
                    k += 1
                if k < inside_end and view[k] == "(":
                    close_paren = _balanced_close(source, k)
                    if close_paren == -1 or close_paren >= inside_end:
                        i += 1
                        continue
                    entry_src = source[i : close_paren + 1]
                    m = _PACKAGE_ENTRY_URL_RE.search(entry_src)
                    if m:
                        identity = _identity_from_url(m.group(1))
                        if identity and identity not in needed_identities:
                            # Determine removal span: entry + trailing comma
                            # + trailing newline + leading whitespace if the
                            # entry was on its own line.
                            entry_end = close_paren + 1
                            scan = entry_end
                            while scan < inside_end and source[scan] in " \t":
                                scan += 1
                            if scan < inside_end and source[scan] == ",":
                                entry_end = scan + 1
                            scan2 = entry_end
                            while scan2 < inside_end and source[scan2] in " \t":
                                scan2 += 1
                            if scan2 < inside_end and source[scan2] == "\n":
                                entry_end = scan2 + 1
                            line_start = source.rfind("\n", inside_start, i) + 1
                            if source[line_start:i].strip() == "":
                                entry_start = line_start
                            else:
                                entry_start = i
                            spans.append(
                                (entry_start, entry_end, f".package({identity})")
                            )
                    i = close_paren + 1
                    continue
        i += 1

    if not spans:
        return source, []

    out_parts: List[str] = []
    reasons: List[str] = []
    cursor = 0
    for start, end, reason in spans:
        out_parts.append(source[cursor:start])
        cursor = end
        reasons.append(reason)
    out_parts.append(source[cursor:])
    return "".join(out_parts), reasons


def _dump_package_json(dir_path: Path) -> dict:
    """Local wrapper around `swift package dump-package` that returns
    parsed JSON or raises PrepareUserError on any non-zero exit / parse
    failure. Inspect's `dump_package` does the same thing but returns
    typed shards; here we just need the raw JSON to walk product/target
    closures.
    """
    cp = subprocess.run(
        ["swift", "package", "dump-package"],
        cwd=str(dir_path),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    if cp.returncode != 0:
        tail = "\n".join((cp.stderr or "").rstrip().splitlines()[-5:])
        raise PrepareUserError(
            "prune-child: swift package dump-package failed:\n"
            + (tail or "  (no stderr)")
        )
    try:
        return json.loads(cp.stdout)
    except json.JSONDecodeError as exc:
        raise PrepareUserError(
            f"prune-child: could not parse dump-package JSON: {exc}"
        ) from exc


def _collect_needed_identities(
    raw_dump: dict, allowed_products: List[str]
) -> Set[str]:
    """From the child's dump-package, walk
        allowed_products → product.targets → target.dependencies (`product` shape)
        and recursively into internal target deps (`byName`, `target`)
        → external identity
    Return the lowercased identity set the child genuinely needs.
    """
    targets_by_name: Dict[str, dict] = {}
    for t in raw_dump.get("targets", []) or []:
        if isinstance(t, dict) and isinstance(t.get("name"), str):
            targets_by_name[t["name"]] = t

    allowed_lower = {p.lower() for p in allowed_products if isinstance(p, str)}
    needed: Set[str] = set()
    visited: Set[str] = set()

    def visit(tname: str) -> None:
        if tname in visited:
            return
        visited.add(tname)
        t = targets_by_name.get(tname)
        if not t:
            return
        for dep in t.get("dependencies", []) or []:
            if not isinstance(dep, dict):
                continue
            prod = dep.get("product")
            if isinstance(prod, list) and len(prod) >= 2 and isinstance(prod[1], str):
                needed.add(prod[1].lower())
                continue
            for key in ("byName", "target"):
                v = dep.get(key)
                if isinstance(v, list) and v and isinstance(v[0], str):
                    visit(v[0])

    for prod in raw_dump.get("products", []) or []:
        if not isinstance(prod, dict):
            continue
        name = prod.get("name")
        if not isinstance(name, str):
            continue
        # Empty allowed list = no filter (build all products). Honor that
        # so a buggy caller doesn't accidentally strip every dep.
        if allowed_lower and name.lower() not in allowed_lower:
            continue
        for tn in prod.get("targets", []) or []:
            if isinstance(tn, str):
                visit(tn)
    return needed


def prune_child_manifest_for_products(
    pre_staged_dir: Path,
    allowed_products: List[str],
    *,
    verbose: bool = False,
) -> None:
    """Apply Pass A then Pass C to `pre_staged_dir/Package.swift` in place.

    Validation contract: every write is followed by a `dump-package`
    round-trip. If a pass produces a manifest SPM rejects, we restore
    the manifest to the most recent validated state (Pass-A's output if
    Pass C fails; the original text if Pass A fails) and raise
    PrepareUserError so the orchestrator can decide whether to abort or
    skip-with-warning (per `--best-effort-transitives`). Keeping Pass
    A's output on a Pass-C failure preserves a strictly-better manifest
    for any post-mortem of the pre-staged dir, and the orchestrator
    abandons the dir anyway in the raise-path so there's no
    downstream-state risk to the partial rollback.
    """
    pkg_swift = pre_staged_dir / "Package.swift"
    if not pkg_swift.is_file():
        return
    # `pre_staged_dir` is copied from `.build/checkouts/<pkg>/`, which SPM
    # makes read-only. Re-chmod Package.swift before we try to rewrite it.
    try:
        pkg_swift.chmod(pkg_swift.stat().st_mode | stat.S_IWUSR)
    except OSError:
        pass
    raw = pkg_swift.read_text()

    # Bail (no-op) if the manifest uses constructs the walker can't reason
    # about — better to ship the foreign package's deps as-is than to
    # produce a silently-broken edit.
    try:
        _assert_no_unsupported_swift_constructs(raw)
    except PrepareUserError as exc:
        verbose_log(
            verbose,
            f"  prune-child: skipping prune (unsupported manifest construct: {exc})",
        )
        return

    original = raw

    # Pass A: strip top-level #if blocks mutating package.dependencies/targets.
    after_a, reasons_a = _strip_top_level_package_mutation_blocks(raw)
    if reasons_a:
        pkg_swift.write_text(after_a)
        try:
            raw_dump = _dump_package_json(pre_staged_dir)
        except PrepareUserError:
            pkg_swift.write_text(original)
            raise
        for r in reasons_a:
            verbose_log(verbose, f"  prune-child: pass-A stripped {r}")
    else:
        raw_dump = _dump_package_json(pre_staged_dir)

    # Pass C: drop unused .package(url:) entries.
    needed = _collect_needed_identities(raw_dump, allowed_products)
    after_c, reasons_c = _prune_top_level_package_entries(after_a, needed)
    if reasons_c:
        pkg_swift.write_text(after_c)
        try:
            _dump_package_json(pre_staged_dir)
        except PrepareUserError:
            # Roll back to the Pass-A result, since that one validated.
            pkg_swift.write_text(after_a)
            raise
        for r in reasons_c:
            verbose_log(verbose, f"  prune-child: pass-C stripped {r}")


# ============================================================================
# --- execute/archive.py ----------------------------------------------------
# ============================================================================


import collections
import concurrent.futures
import json
import subprocess
import shutil
import sys
from pathlib import Path
from typing import Dict, List, Optional, Sequence, Tuple



def _archive_framework_path(archive_path: Path, framework_name: str) -> Optional[Path]:
    """Return the path of `<framework_name>.framework` inside `archive_path`'s
    Products tree, or None if it isn't there.

    SPM-driven archives drop frameworks in different places depending on the
    package's setup:
      - Apps with embedded frameworks land in `Products/Library/Frameworks/`.
      - Standalone library archives (the common case here) land in
        `Products/usr/local/lib/<X>.framework` because xcodebuild uses
        `INSTALL_PATH=/usr/local/lib` by default for SPM library targets.
      - A few packages move things further (custom Xcode projects, etc.).

    Rather than maintain a hardcoded list, we walk the Products tree once
    and look for an exact `<framework_name>.framework` directory. The
    legacy bash spm-to-xcframework uses the same `find Products -name
    *.framework` strategy at lines 1094, 1168, 1248. Returns the first
    match (sorted) or None if no `.framework` bundle exists at all.
    """
    products = archive_path / "Products"
    if not products.is_dir():
        return None
    matches = sorted(products.rglob(f"{framework_name}.framework"))
    for m in matches:
        if m.is_dir():
            return m
    return None


def run_xcodebuild_archive(
    *,
    staged_dir: Path,
    scheme: str,
    slice: PlatformSlice,
    deployment_target: str,
    archive_path: Path,
    dd_path: Path,
    result_bundle_path: Path,
    log_path: Path,
    verbose: bool,
) -> int:
    """Run `xcodebuild archive` for one (build unit, slice) combination.

    Captures combined stdout+stderr into `log_path`. In verbose mode the
    output is also tee'd to the terminal as it streams; non-verbose mode
    only writes to the log file. Returns the xcodebuild exit code (does
    not raise).

    The flag set is exactly the one specified in REWRITE_DESIGN.md §5.4:

        BUILD_LIBRARY_FOR_DISTRIBUTION=YES
        SKIP_INSTALL=NO
        <slice.deployment_target_var>=<deployment_target>
        GCC_TREAT_WARNINGS_AS_ERRORS=NO
        SWIFT_TREAT_WARNINGS_AS_ERRORS=NO
        OTHER_SWIFT_FLAGS=-no-verify-emitted-module-interface
        -skipPackagePluginValidation
        -skipMacroValidation

    There is **no MACH_O_TYPE=mh_dylib**. Dynamic linkage is handled at
    the Package.swift layer in Prepare; never at the xcodebuild CLI layer.
    The whole point of the rewrite is that the synthetic
    `.library(type: .dynamic)` plumbing in Prepare replaces the global
    `mh_dylib` override that the bash tool used.
    """
    # Make sure parent dirs exist for the archive / dd / xcresult / log paths.
    archive_path.parent.mkdir(parents=True, exist_ok=True)
    dd_path.mkdir(parents=True, exist_ok=True)
    result_bundle_path.parent.mkdir(parents=True, exist_ok=True)
    log_path.parent.mkdir(parents=True, exist_ok=True)
    # `xcodebuild archive` refuses to overwrite an existing archive, and
    # similarly will refuse a pre-existing result bundle. Clear them so
    # retries work.
    if archive_path.exists():
        shutil.rmtree(archive_path, ignore_errors=True)
    if result_bundle_path.exists():
        shutil.rmtree(result_bundle_path, ignore_errors=True)

    cmd = [
        "xcodebuild",
        "archive",
        "-scheme", scheme,
        "-destination", slice.destination,
        "-archivePath", str(archive_path),
        "-derivedDataPath", str(dd_path),
        "-resultBundlePath", str(result_bundle_path),
        "BUILD_LIBRARY_FOR_DISTRIBUTION=YES",
        "SKIP_INSTALL=NO",
        f"{slice.deployment_target_var}={deployment_target}",
        "GCC_TREAT_WARNINGS_AS_ERRORS=NO",
        "SWIFT_TREAT_WARNINGS_AS_ERRORS=NO",
        "OTHER_SWIFT_FLAGS=-no-verify-emitted-module-interface",
        "-skipPackagePluginValidation",
        "-skipMacroValidation",
    ]

    verbose_log(verbose, f"  $ (cd {staged_dir} && {' '.join(cmd)})")

    if verbose:
        # Stream output line-by-line to both the log file and stdout. Using
        # Popen with text=True keeps line buffering on the file objects.
        with open(log_path, "w") as logf:
            proc = subprocess.Popen(
                cmd,
                cwd=str(staged_dir),
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                bufsize=1,
            )
            assert proc.stdout is not None
            for line in proc.stdout:
                sys.stdout.write(line)
                sys.stdout.flush()
                logf.write(line)
            return proc.wait()
    else:
        with open(log_path, "w") as logf:
            cp = subprocess.run(
                cmd,
                cwd=str(staged_dir),
                stdout=logf,
                stderr=subprocess.STDOUT,
                text=True,
            )
            return cp.returncode


def _parse_xcresult_build_results(data: dict, limit: int = 5) -> List[dict]:
    """Pure parser for the JSON returned by `xcrun xcresulttool get
    build-results`. Extracted from `read_xcresult_errors` so the unit
    tests can exercise it without invoking xcrun.

    The Xcode 16+ schema (verified against `xcrun xcresulttool get
    build-results --schema` on Xcode 26.2) shapes errors as:

        {
          "errors": [
            {
              "issueType": "...",
              "message": "...",
              "targetName": "...",   // optional
              "sourceURL": "...",    // optional
              "className": "..."     // optional
            },
            ...
          ],
          ...
        }

    Returns a list of dicts shaped like
    `{"target": str, "message": str, "source": str, "issueType": str}`.
    Bad shapes are silently dropped — the diagnostic is best-effort and
    must never blow up Execute's error path.
    """
    if not isinstance(data, dict):
        return []
    errors = data.get("errors")
    if not isinstance(errors, list):
        return []
    out: List[dict] = []
    for err in errors:
        if len(out) >= limit:
            break
        if not isinstance(err, dict):
            continue
        out.append({
            "target": str(err.get("targetName") or ""),
            "message": str(err.get("message") or ""),
            "source": str(err.get("sourceURL") or ""),
            "issueType": str(err.get("issueType") or ""),
        })
    return out


def read_xcresult_errors(result_bundle_path: Path, limit: int = 5) -> List[dict]:
    """Read up to `limit` build errors from an xcresult bundle.

    Uses the Xcode 16+ `xcresulttool get build-results` API exclusively
    (no `--legacy`, no `get object`). Returns an empty list on any failure
    — the bundle is a diagnostic, not a contract, and Execute's error
    handling must still surface the underlying xcodebuild failure even if
    we can't parse the bundle.
    """
    if not result_bundle_path.exists():
        return []
    cp = subprocess.run(
        [
            "xcrun", "xcresulttool", "get", "build-results",
            "--path", str(result_bundle_path),
        ],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    if cp.returncode != 0:
        return []
    try:
        data = json.loads(cp.stdout)
    except json.JSONDecodeError:
        return []
    return _parse_xcresult_build_results(data, limit=limit)


def _format_execute_error(unit_name: str, log_path: Path, errors: List[dict]) -> str:
    """Build a human-readable ExecuteError message body for one failed
    build unit. Pulled out so the parallelization work in Session 4 can
    reuse it without re-deriving the format."""
    lines = [f"xcodebuild archive failed for build unit {unit_name!r}."]
    if errors:
        lines.append(f"Top {len(errors)} error(s) from xcresult:")
        for i, err in enumerate(errors, start=1):
            target = err.get("target") or "(unknown target)"
            msg = err.get("message") or "(no message)"
            src = err.get("source") or ""
            head = f"  [{i}] [{target}] {msg}"
            lines.append(head)
            if src:
                lines.append(f"      at {src}")
    else:
        lines.append("(xcresult bundle did not parse or contained no errors — "
                     "fall back to the build log)")
    lines.append(f"Build log: {log_path}")
    return "\n".join(lines)


def _slice_paths(work_dir: Path, unit_name: str, slice_id: str) -> Tuple[Path, Path, Path, Path]:
    """Pure path computation for one (build unit, slice). Centralised so
    the parallel scheduler and the post-build framework lookup agree on
    where each artifact lives.

    `slice_id` is the platform-prefixed identifier from
    `PlatformSlice.slice_id` (e.g. `ios-arm64`, `ios-simulator`, `macos`).
    Returns (archive_path, dd_path, result_bundle_path, log_path).
    """
    archive_path = work_dir / "archives" / f"{unit_name}-{slice_id}.xcarchive"
    dd_path = work_dir / "dd" / unit_name / slice_id
    result_bundle_path = work_dir / "results" / f"{unit_name}-{slice_id}.xcresult"
    log_path = work_dir / f".build-output-{unit_name}-{slice_id}"
    return archive_path, dd_path, result_bundle_path, log_path


def _archive_one_slice(
    unit: BuildUnit,
    *,
    platform_slice: PlatformSlice,
    deployment_target: str,
    staged_dir: Path,
    work_dir: Path,
    verbose: bool,
) -> Tuple[ArchiveSlice, int]:
    """Run xcodebuild archive once for one (build unit, slice) combination
    and return the slice metadata plus the xcodebuild return code.

    Does NOT raise on xcodebuild failure — the caller (`_archive_all_parallel`)
    needs all futures to settle so it can tail every log and surface a
    consolidated error. Locating the framework / static lib also happens
    here so the caller can decide whether to trigger static promotion
    without re-walking the archive.

    Pure with respect to module-level state: thread-safe under
    `ThreadPoolExecutor`. If xcodebuild exits 0 but no
    `{unit.scheme}.framework` lands under `<archive>/Products/`, the
    returned slice has `framework_path = None` and the caller raises an
    ExecuteError — the synth_dynamic_library product must produce a
    real framework bundle for the rename + injection passes to consume.
    """
    archive_path, dd_path, result_bundle_path, log_path = _slice_paths(
        work_dir, unit.name, platform_slice.slice_id
    )
    rc = run_xcodebuild_archive(
        staged_dir=staged_dir,
        scheme=unit.scheme,
        slice=platform_slice,
        deployment_target=deployment_target,
        archive_path=archive_path,
        dd_path=dd_path,
        result_bundle_path=result_bundle_path,
        log_path=log_path,
        verbose=verbose,
    )
    framework_path = None
    if rc == 0:
        # Look up the framework by `unit.scheme` — that is the name
        # xcodebuild actually emits. For non-synth units the scheme
        # equals the framework_name; for `synth_dynamic_library` units
        # the scheme is the synthetic product name (e.g.
        # `AlamofireDynamic`) and the run-unit driver renames the bundle
        # to `unit.framework_name` after this returns.
        framework_path = _archive_framework_path(archive_path, unit.scheme)

    slice_obj = ArchiveSlice(
        arch_suffix=platform_slice.slice_id,
        sdk_name=platform_slice.sdk_name,
        archive_path=archive_path,
        dd_path=dd_path,
        log_path=log_path,
        result_bundle_path=result_bundle_path,
        framework_path=framework_path,
    )
    return slice_obj, rc


def _tail_log(log_path: Path, n: int = 5) -> str:
    """Return the last `n` lines of a log file as a single string. Empty
    string if the file is missing or unreadable. Used for the post-build
    summary tails after both parallel slices settle (avoids interleaving
    output during the build itself)."""
    if not log_path.is_file():
        return ""
    try:
        with open(log_path, "r", errors="replace") as f:
            lines = f.readlines()
    except OSError:
        return ""
    return "".join(lines[-n:])


def _archive_all_parallel(
    unit: BuildUnit,
    *,
    selected: Sequence[Tuple[PlatformSlice, str]],
    staged_dir: Path,
    work_dir: Path,
    verbose: bool,
) -> "collections.OrderedDict[str, ArchiveSlice]":
    """Build every requested (platform_slice, deployment_target) archive
    for one build unit in parallel via `ThreadPoolExecutor`.

    All futures must settle before this function returns — the caller
    needs the consolidated state to decide whether the unit succeeded
    completely, partially, or failed. Slice logs are captured to separate
    files (`_slice_paths` enforces uniqueness via the platform-prefixed
    `slice_id`) and tailed only after every future settles, so output
    never interleaves on the user's terminal.

    Raises ExecuteError if any slice's xcodebuild call exited non-zero,
    with the parsed xcresult diagnostics for whichever slice(s) failed.
    On success, returns an `OrderedDict` keyed by `slice_id` in the same
    order as `selected` so downstream consumers (create-xcframework merge,
    dry-run summary) see a stable ordering.
    """
    slice_labels = ", ".join(ps.slice_id for ps, _v in selected)
    info(f"  Building {unit.name} — {slice_labels} (parallel)...")

    # Cap pool size at 4 so a high-platform invocation (iOS + macOS +
    # Catalyst + tvOS + visionOS) doesn't oversubscribe the host's xcodebuild
    # licenses or DerivedData I/O. Two-wide for the default --min-ios case
    # — identical to the legacy two-pool behaviour.
    max_workers = min(4, max(1, len(selected)))
    with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as pool:
        futures: Dict[concurrent.futures.Future, PlatformSlice] = {}
        for platform_slice, deployment_target in selected:
            fut = pool.submit(
                _archive_one_slice,
                unit,
                platform_slice=platform_slice,
                deployment_target=deployment_target,
                staged_dir=staged_dir,
                work_dir=work_dir,
                verbose=verbose,
            )
            futures[fut] = platform_slice
        results: Dict[str, Tuple[ArchiveSlice, int]] = {}
        for fut in concurrent.futures.as_completed(futures):
            platform_slice = futures[fut]
            try:
                slice_obj, rc = fut.result()
            except Exception as exc:  # pragma: no cover — defensive
                # Any unexpected exception (a missing xcodebuild on PATH,
                # a permissions error, etc.) is reported as an
                # ExecuteError tagged to the slice that blew up.
                raise ExecuteError(
                    f"unexpected failure during {unit.name} "
                    f"{platform_slice.slice_id} archive: {exc}"
                ) from exc
            results[platform_slice.slice_id] = (slice_obj, rc)

    # Re-order results to match `selected` order (`as_completed` shuffles
    # them by finish time, which would make logs unreliable).
    ordered: "collections.OrderedDict[str, ArchiveSlice]" = collections.OrderedDict()
    for platform_slice, _v in selected:
        ordered[platform_slice.slice_id] = results[platform_slice.slice_id][0]

    # Tail every log after every slice settles. Interleaved live output is
    # unreadable, so non-verbose mode defers summaries until everything
    # exits. Verbose mode already streams everything live so we skip the
    # extra tail there to avoid double-printing.
    if not verbose:
        for slice_obj in ordered.values():
            tail = _tail_log(slice_obj.log_path)
            if tail:
                sys.stdout.write(tail)
                if not tail.endswith("\n"):
                    sys.stdout.write("\n")
        sys.stdout.flush()

    failed: List[ArchiveSlice] = []
    for platform_slice, _v in selected:
        _slice_obj, rc = results[platform_slice.slice_id]
        if rc != 0:
            failed.append(_slice_obj)
    if failed:
        sections: List[str] = []
        for slice_obj in failed:
            errors = read_xcresult_errors(slice_obj.result_bundle_path, limit=5)
            slice_label = f"{unit.name} ({slice_obj.arch_suffix})"
            sections.append(_format_execute_error(slice_label, slice_obj.log_path, errors))
        raise ExecuteError("\n\n".join(sections))

    return ordered


# ============================================================================
# --- execute/rename_framework.py -------------------------------------------
# ============================================================================


import plistlib
import shutil
import subprocess
from pathlib import Path
from typing import Optional



def _is_versioned_bundle(fw_path: Path) -> bool:
    """True iff `fw_path` is a macOS-style versioned bundle (real
    `Versions/A/` at the root, not a symlink)."""
    versions_a = fw_path / "Versions" / "A"
    return versions_a.is_dir() and not versions_a.is_symlink()


def _read_plist_string(plist_path: Path, key: str) -> Optional[str]:
    """Return the top-level string entry at `key`, or None if the file
    is missing, malformed, or the key isn't a string. Used to inspect
    the original CFBundleIdentifier before deciding whether to rewrite
    it — see the rename step in `rename_framework_bundle`.
    """
    if not plist_path.is_file():
        return None
    try:
        with plist_path.open("rb") as fh:
            data = plistlib.load(fh)
    except (plistlib.InvalidFileException, OSError, ValueError):
        return None
    if not isinstance(data, dict):
        return None
    v = data.get(key)
    return v if isinstance(v, str) else None


def _set_plist_string(plist_path: Path, key: str, value: str) -> None:
    """Set a top-level string entry in a (binary or XML) plist. Uses
    `plistlib` rather than PlistBuddy so we don't depend on the
    `/usr/libexec/PlistBuddy` binary being on PATH and so we can write
    binary plists back in the same format we read.
    """
    if not plist_path.is_file():
        raise ExecuteError(f"Info.plist missing at {plist_path}")
    with plist_path.open("rb") as fh:
        data = plistlib.load(fh)
    # Preserve the original format (binary vs XML). plistlib re-derives
    # this from the file header when reading; on write we need to
    # request it explicitly.
    fmt = plistlib.FMT_XML
    with plist_path.open("rb") as fh:
        head = fh.read(8)
        if head.startswith(b"bplist"):
            fmt = plistlib.FMT_BINARY
    if not isinstance(data, dict):
        raise ExecuteError(f"Info.plist at {plist_path} is not a dict")
    data[key] = value
    with plist_path.open("wb") as fh:
        plistlib.dump(data, fh, fmt=fmt)


def _run(cmd: list, *, verbose: bool, label: str) -> None:
    verbose_log(verbose, f"  $ {' '.join(cmd)}")
    cp = subprocess.run(
        cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True
    )
    if cp.returncode != 0:
        tail = "\n".join((cp.stdout or "").rstrip().splitlines()[-10:])
        raise ExecuteError(
            f"{label} failed (exit {cp.returncode}):\n" + (tail or "  (no output)")
        )


def rename_framework_bundle(
    fw_path: Path,
    *,
    new_name: str,
    verbose: bool,
) -> Path:
    """Rename a framework bundle and its inner executable + metadata in
    place, returning the path to the renamed bundle.

    Steps:
      1. Rename the inner Mach-O (`Versions/A/<old>` on macOS, `<old>`
         at the root on iOS et al.) to the new name.
      2. Rewrite the binary's `LC_ID_DYLIB` to
         `@rpath/<new>.framework/<new>` via `install_name_tool -id`.
      3. Update `Info.plist` (`Versions/A/Resources/Info.plist` on
         macOS, `Info.plist` at the root otherwise): CFBundleExecutable
         and CFBundleName become `<new>`. CFBundleIdentifier is
         rewritten only when its existing value mentions the old
         scheme name (xcodebuild's default `org.swift.<scheme>` shape),
         to avoid clobbering a custom PRODUCT_BUNDLE_IDENTIFIER.
      4. Rename the framework bundle directory itself
         (`<old>.framework` → `<new>.framework`).
      5. On macOS only, replace the root symlink that pointed at the
         old executable name with one pointing at the new name; same
         for the root Resources symlink (no rename needed) and
         Versions/Current (already "A").
      6. Re-codesign ad-hoc (`codesign --force --sign -`). xcodebuild
         signs the framework during archive with whatever identity the
         destination requires (`-` for simulator/macOS); re-signing
         after any binary or bundle mutation is mandatory or downstream
         consumers (codesign --verify, dyld signature checks on real
         devices) reject the framework.

    Returns the new framework path (`<parent>/<new>.framework`).
    """
    if not fw_path.is_dir():
        raise ExecuteError(f"rename: framework path not a directory: {fw_path}")
    old_name = fw_path.stem
    if old_name == new_name:
        return fw_path  # nothing to do

    versioned = _is_versioned_bundle(fw_path)
    dim(f"  Renaming {old_name}.framework → {new_name}.framework")

    # Step 1: inner executable rename.
    if versioned:
        inner_dir = fw_path / "Versions" / "A"
    else:
        inner_dir = fw_path
    old_exec = inner_dir / old_name
    new_exec = inner_dir / new_name
    if not old_exec.is_file():
        raise ExecuteError(
            f"rename: inner executable {old_exec} not found"
        )
    if new_exec.exists():
        # Defensive: a prior failed rename may have left a stale
        # destination. Remove it so the rename below doesn't fail.
        new_exec.unlink()
    old_exec.rename(new_exec)

    # Step 2: rewrite LC_ID_DYLIB. Flat install_name form so both iOS
    # and macOS use the same shape; the macOS top-level symlink
    # resolves it.
    _run(
        [
            "install_name_tool",
            "-id",
            f"@rpath/{new_name}.framework/{new_name}",
            str(new_exec),
        ],
        verbose=verbose,
        label="install_name_tool -id",
    )

    # Step 3: Info.plist updates.
    if versioned:
        plist = inner_dir / "Resources" / "Info.plist"
    else:
        plist = fw_path / "Info.plist"
    _set_plist_string(plist, "CFBundleExecutable", new_name)
    _set_plist_string(plist, "CFBundleName", new_name)
    # Only rewrite CFBundleIdentifier if xcodebuild produced the
    # default SPM-shaped identifier (`org.swift.<scheme>`) — that's
    # the one case where the old scheme name is structural and the
    # rename target name must follow it. Packages that set their own
    # PRODUCT_BUNDLE_IDENTIFIER or INFO_PLIST entry end up with an
    # identifier that's user-chosen and unrelated to the scheme;
    # rewriting it would silently lose that state. We also exclude
    # custom identifiers that happen to mention the old scheme name
    # (e.g. `com.acme.FooDynamic.module`) — Codex round-2 Low.
    old_id = _read_plist_string(plist, "CFBundleIdentifier")
    if old_id is not None and old_id.startswith("org.swift.") and old_name in old_id:
        new_id = old_id.replace(old_name, new_name)
        _set_plist_string(plist, "CFBundleIdentifier", new_id)

    # Step 4: rename the bundle directory itself.
    new_fw_path = fw_path.parent / f"{new_name}.framework"
    if new_fw_path.exists():
        # Same defensive cleanup as the executable case.
        shutil.rmtree(new_fw_path)
    fw_path.rename(new_fw_path)

    # Step 5: on macOS, swap the root symlink that pointed at the old
    # executable name for one pointing at the new name. `Versions/Current`
    # (-> A) and the Resources root symlink don't need renaming — they're
    # already content-shaped.
    if versioned:
        old_root_link = new_fw_path / old_name
        if old_root_link.is_symlink():
            old_root_link.unlink()
        new_root_link = new_fw_path / new_name
        if new_root_link.exists() or new_root_link.is_symlink():
            new_root_link.unlink()
        new_root_link.symlink_to(Path("Versions") / "Current" / new_name)

    # Step 6: ad-hoc re-codesign. Required after any binary or bundle
    # mutation — without it `codesign --verify` and on-device dyld
    # signature checks fail.
    _run(
        ["codesign", "--force", "--sign", "-", str(new_fw_path)],
        verbose=verbose,
        label="codesign --force --sign -",
    )

    return new_fw_path


# ============================================================================
# --- execute/inject_swiftmodule.py -----------------------------------------
# ============================================================================


import os
import re
import shutil
from pathlib import Path
from typing import Optional, Sequence, Tuple



# SPM passes `-package-name <pkg>` to every target in a Swift package so
# `package`-access symbols work between siblings. The flag gets recorded in
# the emitted `.swiftinterface` header — any consumer Swift module that
# imports this framework AND also gets `-package-name <pkg>` (i.e., happens
# to live in an SPM package with the same name) will require a matching
# `.package.swiftinterface` and refuse to load the public one. Since an
# `.xcframework` is an external artifact, no consumer should treat it as
# in-package; we strip the flag so the loaded interface is unambiguously
# non-package and Swift falls back to the normal public-import path.
#
# Triggers seen in the matrix: Nuke 12.x — Nuke and NukeUI both live in
# `staged`, so NukeUI fails to load Nuke.framework's interface with
# "Module 'Nuke' is in package 'staged' but was built from a non-package
# interface" unless we strip.
#
# The rewrite is scoped to the `// swift-module-flags[-ignorable]:` header
# comment lines only. A blind file-wide substitution would silently corrupt
# any public API whose body contains a string literal with the substring
# " -package-name X" — unlikely, but exactly the class of "silently
# producing a broken xcframework" we explicitly want to avoid.
_PACKAGE_NAME_FLAG_RE = re.compile(r"[ \t]+-package-name[ \t]+\S+")
_MODULE_FLAGS_PREFIX_RE = re.compile(
    r"^//\s*swift-module-flags(?:-ignorable)?\s*:"
)


def _strip_package_name_from_swiftinterfaces(swiftmod_dir: Path) -> None:
    for iface in swiftmod_dir.glob("*.swiftinterface"):
        try:
            text = iface.read_text(encoding="utf-8")
        except OSError:
            continue
        lines = text.splitlines(keepends=True)
        changed = False
        for idx, line in enumerate(lines):
            if not _MODULE_FLAGS_PREFIX_RE.match(line):
                continue
            stripped = _PACKAGE_NAME_FLAG_RE.sub("", line)
            if stripped != line:
                lines[idx] = stripped
                changed = True
        if changed:
            iface.write_text("".join(lines), encoding="utf-8")


def _find_swiftmodule_in_dd(
    dd_path: Path,
    fw_name: str,
    scheme: str,
    extra_module_names: Sequence[str] = (),
) -> Optional[Tuple[Path, str]]:
    """Locate a `<name>.swiftmodule` directory under DerivedData.

    Search order:
      1. `*/<fw_name>.swiftmodule` anywhere under DerivedData.
      2. `ArchiveIntermediates/<scheme>/BuildProductsPath/*/<fw_name>.swiftmodule`
         (legacy bash 1296-1301 fallback for scheme/product name mismatch).
      3. For each name in extra_module_names (typically the underlying
         source targets), the same two passes. This handles cases like
         GRDB-dynamic, where the framework binary is named "GRDB-dynamic"
         but the Swift module the targets actually emit is "GRDB".

    Returns (path, module_name) so the caller knows which name to use
    for the destination directory inside the framework's Modules/.
    """

    def _find_for(name: str) -> Optional[Path]:
        target = f"{name}.swiftmodule"
        if dd_path.is_dir():
            for path in dd_path.rglob(target):
                if path.is_dir():
                    return path
        if scheme != name and dd_path.is_dir():
            intermediate = (
                dd_path / "Build" / "Intermediates.noindex"
                / "ArchiveIntermediates" / scheme / "BuildProductsPath"
            )
            if intermediate.is_dir():
                for path in intermediate.rglob(target):
                    if path.is_dir():
                        return path
        return None

    found = _find_for(fw_name)
    if found is not None:
        return found, fw_name
    for name in extra_module_names:
        if name == fw_name:
            continue
        found = _find_for(name)
        if found is not None:
            return found, name
    return None


# macOS frameworks ship in the "versioned bundle" layout: real content lives
# under `Versions/A/` and the framework root holds only `Versions/` plus
# convenience symlinks (`Foo -> Versions/Current/Foo`, etc.). Apple's
# codesigning rejects any framework that has real (non-symlink) directories
# at the root other than `Versions/` — "unsealed contents present in the
# root directory of an embedded framework."
#
# `xcodebuild archive` emits a macOS framework already in versioned layout
# (binary + Resources/Info.plist under Versions/A), but it does NOT pre-
# create Modules/ or Headers/ (xcodebuild's archive output doesn't include
# swiftinterface or public ObjC headers — those come from DerivedData and
# our injection passes). Our injectors therefore must write under Versions/A
# and create root symlinks themselves, otherwise they'd lay a real Modules/
# at the framework root and break codesigning downstream.
#
# iOS / tvOS / watchOS / visionOS / Mac Catalyst all use the flat layout
# (no Versions/ directory; everything at the framework root), and these
# helpers no-op on those slices — `_framework_content_root` returns
# fw_path itself, and `_ensure_root_symlink` returns without touching
# anything.


def _framework_content_root(fw_path: Path) -> Path:
    """Return the directory under a framework bundle where real injected
    content should live.

    Versioned (macOS-style) bundles: `<fw>/Versions/A`. Flat (iOS-style)
    bundles: `fw_path` itself. Detected by presence of a real (non-symlink)
    `Versions/A` directory at the framework root.
    """
    versions_a = fw_path / "Versions" / "A"
    if versions_a.is_dir() and not versions_a.is_symlink():
        return versions_a
    return fw_path


def _ensure_root_symlink(fw_path: Path, name: str) -> None:
    """For a versioned framework, ensure `<fw>/<name>` is a symlink to
    `Versions/Current/<name>`. No-op for flat frameworks.

    If a real (non-symlink) directory squats at the root path — typically
    the result of a prior injection that wrote in flat-layout style on a
    macOS framework — it is migrated to `Versions/A/<name>` and the
    symlink takes its place. Migration is the only reliable repair: a
    leftover real directory at the root will cause the codesigning
    rejection this whole machinery exists to prevent.
    """
    versions_a = fw_path / "Versions" / "A"
    if not (versions_a.is_dir() and not versions_a.is_symlink()):
        return  # flat (iOS-style) framework — nothing to symlink.
    link = fw_path / name
    target = Path("Versions") / "Current" / name
    if link.is_symlink():
        if os.readlink(link) == str(target):
            return
        link.unlink()
    elif link.exists():
        # Migrate a real root directory left over from a prior injection
        # into the versioned location, then drop the symlink in place.
        dest = versions_a / name
        if dest.exists():
            shutil.rmtree(dest)
        shutil.move(str(link), str(dest))
    link.symlink_to(target)


def inject_swiftmodule(
    *,
    fw_path: Path,
    fw_name: str,
    scheme: str,
    dd_path: Path,
    variant: str,
    verbose: bool,
    extra_module_names: Sequence[str] = (),
) -> bool:
    """Copy `.swiftmodule/.swiftinterface` files from DerivedData into a
    framework's Modules directory if they're missing.

    `extra_module_names` lets the caller pass underlying source target
    names so that frameworks whose binary name doesn't match the actual
    Swift module name (e.g. GRDB-dynamic.framework whose module is
    `GRDB`) can still get their interfaces injected.

    Returns True iff anything was injected. Idempotent: if any
    `Modules/<X>.swiftmodule/` already contains `.swiftinterface` files
    this is a no-op.

    Versioned (macOS) frameworks: writes under `Versions/A/Modules/` and
    ensures `<fw>/Modules` is a symlink. See `_framework_content_root`
    for the rationale.
    """
    modules_dir = _framework_content_root(fw_path) / "Modules"
    if modules_dir.is_dir():
        for sm in modules_dir.glob("*.swiftmodule"):
            if sm.is_dir():
                for child in sm.iterdir():
                    if child.suffix == ".swiftinterface":
                        verbose_log(verbose, f"  Swift interfaces present in {variant} framework")
                        return False

    found = _find_swiftmodule_in_dd(dd_path, fw_name, scheme, extra_module_names)
    if found is None:
        verbose_log(
            verbose,
            f"  No Swift module found in DerivedData for {fw_name} ({variant})",
        )
        return False
    swiftmod, module_name = found

    dim(f"  Injecting Swift module interfaces ({variant})")
    modules_dir.mkdir(parents=True, exist_ok=True)
    dest = modules_dir / f"{module_name}.swiftmodule"
    if dest.exists():
        shutil.rmtree(dest)
    shutil.copytree(swiftmod, dest)
    _strip_package_name_from_swiftinterfaces(dest)
    _ensure_root_symlink(fw_path, "Modules")
    return True


# ============================================================================
# --- execute/inject_objc.py ------------------------------------------------
# ============================================================================


import os
import shutil
from pathlib import Path
from typing import Dict, List, Optional, Set




def _has_h_files_recursive(path: Path) -> bool:
    """True iff `path` contains at least one `.h` file at any depth.

    Used to filter out directories that exist but contain only Swift
    sources or subdirectories with no public ObjC surface — those
    aren't real header roots even when they happen to be named `include`
    or carry an explicit `publicHeadersPath`.
    """
    for _root, _dirs, files in os.walk(path):
        for name in files:
            if name.endswith(".h"):
                return True
    return False


def _find_objc_headers_dir(
    package: Package,
    product_name: str,
    fw_name: str,
) -> Optional[Path]:
    """Find a directory of public ObjC headers for the named product.

    Priority (matches legacy bash 1352-1397):
      1. A direct product target whose name == fw_name with a
         publicHeadersPath that exists and contains *.h files.
      2. A direct product target whose name == product_name.
      3. Any direct product target with headers.
      4. First-level dependencies of direct product targets, with the
         same fw_name > product_name > anything-with-headers priority.

    Returns the absolute path of the public-headers directory, or None.
    """
    raw_targets_by_name: Dict[str, dict] = {}
    for raw_t in package.raw_dump.get("targets", []) or []:
        if isinstance(raw_t, dict) and isinstance(raw_t.get("name"), str):
            raw_targets_by_name[raw_t["name"]] = raw_t

    product_targets: List[str] = []
    for raw_p in package.raw_dump.get("products", []) or []:
        if isinstance(raw_p, dict) and raw_p.get("name") == product_name:
            tlist = raw_p.get("targets")
            if isinstance(tlist, list):
                product_targets = [t for t in tlist if isinstance(t, str)]
            break
    if not product_targets and product_name in raw_targets_by_name:
        product_targets = [product_name]
    if not product_targets:
        return None

    # Targets that any product in this package exposes as part of its
    # own xcframework. Used to gate implicit-layout fallback in the dep
    # walk: a dep that backs another product is "separately packaged"
    # — its public surface lives in that product's xcframework, so
    # bleeding its `include/` or umbrella header up into the parent
    # frame would leak headers across xcframework boundaries
    # (Stripe3DS2 → StripePayments). A dep that no product references
    # is "internal" — only ever folded into the parent — so its
    # default-layout headers belong to the parent.
    separately_packaged: Set[str] = set()
    for raw_p in package.raw_dump.get("products", []) or []:
        if not isinstance(raw_p, dict):
            continue
        tlist = raw_p.get("targets")
        if not isinstance(tlist, list):
            continue
        for t in tlist:
            if isinstance(t, str):
                separately_packaged.add(t)

    def headers_dir_for(target_name: str, allow_implicit_layouts: bool) -> Optional[Path]:
        target = package.target_by_name(target_name)
        if target is None:
            return None
        target_path = target.path or _default_target_path(target.name, target.kind)
        if not target_path:
            return None
        target_dir = package.staged_dir / target_path
        # 1. Explicit `publicHeadersPath` always wins (the legacy contract).
        if target.public_headers_path:
            full_path = target_dir / target.public_headers_path
            if full_path.is_dir() and _has_h_files_recursive(full_path):
                return full_path
            return None
        # 2. Implicit layouts are gated by the caller. Direct product
        #    targets always opt in. Deps opt in only when the dep is
        #    not separately packaged — i.e. no product in this package
        #    exposes it as its own xcframework. A separately-packaged
        #    dep (Stripe3DS2 underneath StripePayments) ships its
        #    public surface in its own xcframework, so accepting an
        #    `include/` or umbrella here would duplicate-leak those
        #    headers into the parent.
        if not allow_implicit_layouts:
            return None
        # 2a. SPM default for ObjC targets: `<target_path>/include/`.
        include_dir = target_dir / "include"
        if include_dir.is_dir() and _has_h_files_recursive(include_dir):
            return include_dir
        # 2b. Umbrella-header-at-target-root pattern. Stripe ships every
        #    product this way: e.g. `StripePayments.h` sits at the top of
        #    `StripePayments/StripePayments/` with no `include/` subdir,
        #    next to ~220 .swift files. Even when the umbrella itself is
        #    a stub (just FOUNDATION_EXPORT version constants), the
        #    Headers/ + module.modulemap surface is what lets ObjC
        #    consumers `#import <StripePayments/StripePayments.h>` —
        #    skipping this branch for Swift-classified targets would
        #    silently drop that surface. Accept the two umbrella forms
        #    only — `<TargetName>.h` (the common Stripe target pattern)
        #    and `<TargetName>-umbrella.h` (used by the Stripe product
        #    target itself). Anything else risks over-injection:
        #    `inject_objc_headers` walks the returned dir recursively
        #    and copies every .h, so accepting a generic non-`-Swift.h`
        #    would leak private/internal top-level headers into the
        #    framework's public surface.
        for candidate in (f"{target.name}.h", f"{target.name}-umbrella.h"):
            if (target_dir / candidate).is_file():
                return target_dir
        return None

    product_match: Optional[Path] = None
    any_match: Optional[Path] = None
    for tname in product_targets:
        d = headers_dir_for(tname, allow_implicit_layouts=True)
        if d is None:
            continue
        if tname == fw_name:
            return d
        if tname == product_name:
            if product_match is None:
                product_match = d
        else:
            if any_match is None:
                any_match = d
    if product_match is not None:
        return product_match
    if any_match is not None:
        return any_match

    # First-level dependencies of direct product targets. Accepts both
    # `byName` and `target` dep shapes — the GRDB-style `.target()`
    # form would otherwise go unvisited and public headers from
    # depended-on ObjC targets would be missed (Codex [P1]). Implicit
    # layouts are gated by `separately_packaged`: a dep that backs its
    # own product gets its own xcframework, so we require an explicit
    # `publicHeadersPath` to opt those headers into the parent (this is
    # what stops Stripe3DS2's `include/` from leaking up into
    # StripePayments). An internal-only dep — one no product
    # references — gets the same `include/` and umbrella fallbacks as
    # a direct product target, since the parent is the only place it
    # ships.
    dep_fw_match: Optional[Path] = None
    dep_product_match: Optional[Path] = None
    dep_any_match: Optional[Path] = None
    seen_deps: Set[str] = set()
    for tname in product_targets:
        raw = raw_targets_by_name.get(tname)
        if raw is None:
            continue
        for dep_name in _raw_internal_dep_names(raw):
            if dep_name in seen_deps:
                continue
            seen_deps.add(dep_name)
            allow_implicit = dep_name not in separately_packaged
            d = headers_dir_for(dep_name, allow_implicit_layouts=allow_implicit)
            if d is None:
                continue
            if dep_name == fw_name and dep_fw_match is None:
                dep_fw_match = d
            elif dep_name == product_name and dep_product_match is None:
                dep_product_match = d
            elif dep_any_match is None:
                dep_any_match = d
    if dep_fw_match is not None:
        return dep_fw_match
    if dep_product_match is not None:
        return dep_product_match
    return dep_any_match


def _generate_modulemap(fw_path: Path, fw_name: str) -> None:
    """Write `Modules/module.modulemap` for a framework that has ObjC
    headers but no module map. Uses an umbrella header if `<fw_name>.h`
    exists, otherwise lists every header explicitly. Same shape as the
    legacy bash 1430-1450.
    """
    content_root = _framework_content_root(fw_path)
    modules_dir = content_root / "Modules"
    modules_dir.mkdir(parents=True, exist_ok=True)
    headers_dir = content_root / "Headers"
    umbrella = headers_dir / f"{fw_name}.h"
    if umbrella.is_file():
        # The `module * { export * }` line tells Clang to walk the
        # Headers/ tree on its own, so nested layouts work without
        # having to enumerate every file here.
        text = (
            f"framework module {fw_name} {{\n"
            f"  umbrella header \"{fw_name}.h\"\n"
            f"  export *\n"
            f"  module * {{ export * }}\n"
            f"}}\n"
        )
    else:
        # Walk recursively so nested headers (e.g. Headers/Sub/Foo.h)
        # land in the modulemap too — otherwise Clang only sees the
        # top-level .h files and `#import <Module/Sub/Foo.h>` fails to
        # resolve at bind time. Relative paths are POSIX-style to
        # match Clang's own module-map syntax.
        header_rel_paths = sorted(
            p.relative_to(headers_dir).as_posix()
            for p in headers_dir.rglob("*.h")
            if p.is_file()
        )
        lines = [f"framework module {fw_name} {{"]
        for rel in header_rel_paths:
            lines.append(f"  header \"{rel}\"")
        lines.append("  export *")
        lines.append("}")
        text = "\n".join(lines) + "\n"
    (modules_dir / "module.modulemap").write_text(text)


def inject_objc_headers(
    *,
    package: Package,
    product_name: str,
    fw_name: str,
    fw_path: Path,
    verbose: bool,
) -> bool:
    """Copy public ObjC headers + a generated modulemap into a framework
    bundle. No-op if the framework already has `*.h` headers (excluding
    the auto-generated `*-Swift.h` bridge header).

    Returns True iff anything was injected.
    """
    headers_target = _framework_content_root(fw_path) / "Headers"
    if headers_target.is_dir():
        for p in headers_target.glob("*.h"):
            if not p.name.endswith("-Swift.h"):
                verbose_log(verbose, "  Public headers already present in framework")
                return False

    headers_dir = _find_objc_headers_dir(package, product_name, fw_name)
    if headers_dir is None:
        verbose_log(verbose, f"  No ObjC public headers found in source tree for {fw_name}")
        return False

    dim(f"  Injecting ObjC headers ({fw_name})")
    headers_target.mkdir(parents=True, exist_ok=True)

    # SPM convention (legacy 1411-1420): headers may live in a
    # subdirectory named after the module (e.g., Public/FirebaseCore/*.h)
    # or directly in the public headers dir. Pick the scan base
    # accordingly, then walk it recursively and copy each header into
    # `Headers/<relative path>` — preserving subdirectories is required
    # because (a) `#import <Module/Sub/Header.h>` needs the physical
    # path to exist inside Headers/, and (b) a flat copy would silently
    # overwrite same-named headers that live in different subfolders
    # (Codex [P2]).
    module_subdir = headers_dir / fw_name
    scan_base = module_subdir if module_subdir.is_dir() else headers_dir
    copied = 0
    for h in sorted(scan_base.rglob("*.h")):
        if not h.is_file():
            continue
        rel = h.relative_to(scan_base)
        dest = headers_target / rel
        dest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(h, dest)
        copied += 1

    if copied == 0:
        verbose_log(verbose, f"  No headers copied from {headers_dir}")
        return False

    _generate_modulemap(fw_path, fw_name)
    _ensure_root_symlink(fw_path, "Headers")
    _ensure_root_symlink(fw_path, "Modules")
    verbose_log(verbose, f"  Injected {copied} header(s) + modulemap")
    return True


# ============================================================================
# --- execute/inject_clang_system.py ----------------------------------------
# ============================================================================


import re
import shutil
from pathlib import Path
from typing import Dict, List, Optional, Sequence, Set, Tuple



_SYSTEM_SHIM_SENTINEL = ".spm-to-xcframework-system-shim"


def _walk_system_library_target_deps(
    package: Package,
    source_targets: Sequence[str],
) -> List[Target]:
    """Return every transitive `.systemLibrary` target reachable from
    `source_targets` via internal `byName` / `target` dependency edges.

    Walks the raw dump rather than `Target.dependencies` because the typed
    list flattens out the `byName` vs `target` shapes — same convention as
    `_find_objc_headers_dir`. Result order is the discovery order (BFS)
    to keep diagnostics deterministic.
    """
    raw_targets_by_name: Dict[str, dict] = {}
    for raw_t in package.raw_dump.get("targets", []) or []:
        if isinstance(raw_t, dict) and isinstance(raw_t.get("name"), str):
            raw_targets_by_name[raw_t["name"]] = raw_t

    found: List[Target] = []
    seen: Set[str] = set()
    queue: List[str] = list(source_targets)
    while queue:
        name = queue.pop(0)
        if name in seen:
            continue
        seen.add(name)
        target = package.target_by_name(name)
        if target is None:
            continue
        if target.kind == TargetKind.SYSTEM:
            found.append(target)
            # System targets do not transitively depend on other targets
            # in any shape we care about — they are leaves by SPM design.
            continue
        raw = raw_targets_by_name.get(name)
        if raw is None:
            continue
        for dep_name in _raw_internal_dep_names(raw):
            if dep_name not in seen:
                queue.append(dep_name)
    return found


def _system_target_source_dir(target: Target, staged_dir: Path) -> Optional[Path]:
    """Locate the on-disk source directory for a `.systemLibrary` target.

    SPM convention: `Sources/<TargetName>/` unless `path:` is set
    explicitly. `_default_target_path` only returns paths for regular /
    executable / test kinds, so we duplicate the system-target convention
    here rather than widening that helper.
    """
    if target.path:
        full = staged_dir / target.path
    else:
        full = staged_dir / "Sources" / target.name
    return full if full.is_dir() else None


def _promote_modulemap_to_framework_form(modulemap_text: str) -> str:
    """Rewrite an SPM `.systemLibrary` modulemap so it can live inside a
    `.framework/Modules/module.modulemap` and be discovered via swiftc's
    `-F` framework search.

    Input  (SPM systemLibrary):  `module Foo [system] { header "shim.h" link "x" export * }`
    Output (framework module):   `framework module Foo [system] { header "shim.h" link "x" export * }`

    The only required change is the `framework ` qualifier on the
    top-level `module` declaration. Modern swiftc accepts plain `header`
    inside a framework module — `umbrella header` is not required when
    the framework has a single shim header (verified empirically against
    Swift 6.2.3, Xcode 26.2 simulator SDK).
    """
    return re.sub(
        r"(?m)^(\s*)module(\s+\w+)",
        r"\1framework module\2",
        modulemap_text,
        count=1,
    )


def inject_system_clang_modules(
    *,
    xcframework_path: Path,
    package: Package,
    source_targets: Sequence[str],
    verbose: bool,
) -> int:
    """Bundle every transitive `.systemLibrary` Clang module that the
    primary framework depends on as a sibling shim framework inside each
    xcframework slice. No-op if `source_targets` has no system deps.

    Background: when a regular Swift target depends on a `.systemLibrary`
    target (e.g. GRDB → GRDBSQLite, which wraps `<sqlite3.h>`), the
    Swift compiler always emits `import GRDBSQLite` into the framework's
    `.swiftinterface`. Any consumer that has to rebuild GRDB from its
    textual interface — every consumer whose Swift compiler version
    differs from the build-time one — needs `GRDBSQLite` to resolve as a
    Clang module, or the import fails with `error: no such module
    'GRDBSQLite'` and the framework is unconsumable.

    The system product itself is correctly dropped at planning time
    (`_is_system_only_product`) because there is no Mach-O to build, but
    its modulemap+headers must travel with the parent framework so the
    Clang module can be loaded at consumer compile time. We bundle them
    as a binary-less sibling `<Name>.framework` inside each slice
    directory of the xcframework. swiftc auto-discovers it via `-F`
    framework search — no extra `-I` / `-Xcc` flags required on the
    consumer side, including non-spm-to-xcframework consumers like
    plain Xcode app projects.

    Returns the number of system shims injected (counted once per
    distinct system target, not per slice). Idempotent: existing
    `<Name>.framework` siblings are skipped.
    """
    if not xcframework_path.is_dir():
        return 0

    system_targets = _walk_system_library_target_deps(package, source_targets)
    if not system_targets:
        return 0

    # Discover slice directories. The xcframework Info.plist lists them
    # under AvailableLibraries[].LibraryIdentifier, but we don't need to
    # parse it — every direct subdirectory of the xcframework other than
    # Info.plist is a slice. This avoids a plistlib import in the hot
    # path and matches what xcframework consumers do.
    slice_dirs = [
        p for p in sorted(xcframework_path.iterdir())
        if p.is_dir()
    ]
    if not slice_dirs:
        return 0

    injected = 0
    for sys_target in system_targets:
        src_dir = _system_target_source_dir(sys_target, package.staged_dir)
        if src_dir is None:
            warn(
                f"  System target {sys_target.name!r} has no resolvable "
                f"source dir under {package.staged_dir}; consumers will "
                f"fail to import {sys_target.name}"
            )
            continue
        modulemap = src_dir / "module.modulemap"
        if not modulemap.is_file():
            warn(
                f"  System target {sys_target.name!r} source dir {src_dir} "
                f"has no module.modulemap; skipping shim injection"
            )
            continue
        # Headers are every `.h` file under the system-target source
        # dir, walked recursively. SPM `.systemLibrary` targets usually
        # park a single `shim.h` next to the modulemap, but the modulemap
        # text (which we preserve verbatim aside from the framework
        # qualifier) is free to `header "Sub/foo.h"` into a nested path.
        # We must preserve those relative paths into the shim's Headers/
        # tree so the modulemap's references still resolve at consumer
        # compile time (Codex [P2] follow-up — flat copy silently
        # produced broken shims for nested layouts).
        headers: List[Tuple[Path, Path]] = []
        for p in sorted(src_dir.rglob("*.h")):
            if not p.is_file():
                continue
            rel = p.relative_to(src_dir)
            headers.append((p, rel))
        framework_modulemap = _promote_modulemap_to_framework_form(
            modulemap.read_text()
        )

        any_slice_injected = False
        for slice_dir in slice_dirs:
            shim_fw = slice_dir / f"{sys_target.name}.framework"
            if shim_fw.exists():
                continue  # idempotent — second run is a no-op
            shim_fw_modules = shim_fw / "Modules"
            shim_fw_headers = shim_fw / "Headers"
            shim_fw_modules.mkdir(parents=True, exist_ok=True)
            shim_fw_headers.mkdir(parents=True, exist_ok=True)
            (shim_fw_modules / "module.modulemap").write_text(framework_modulemap)
            for src_header, rel in headers:
                dest = shim_fw_headers / rel
                dest.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src_header, dest)
            # Sentinel file used by `_is_system_shim_framework` to skip
            # this directory during language classification and
            # surface-check walks. Invisible to Xcode/swiftc consumers.
            (shim_fw / _SYSTEM_SHIM_SENTINEL).write_text(
                "spm-to-xcframework injected this framework as a Clang "
                "module shim for a .systemLibrary SPM target. Do not "
                "delete; removing it makes language classification "
                "misclassify the parent xcframework.\n"
            )
            any_slice_injected = True

        if any_slice_injected:
            injected += 1
            dim(
                f"  Injected system Clang module shim: "
                f"{sys_target.name}.framework (× {len(slice_dirs)} slice(s))"
            )

    return injected


# ============================================================================
# --- execute/inject_clang_bridge.py ----------------------------------------
# ============================================================================


import re
import shutil
from pathlib import Path
from typing import List, Optional, Set, Tuple




_PACKAGE_MODULEMAP_LINE_RE = re.compile(
    r"(?m)^\s*(?:framework\s+)?(?:explicit\s+)?module\s+([A-Za-z_][\w.]*)"
)
_SWIFTINTERFACE_IMPORT_RE = re.compile(r"^\s*import\s+([A-Za-z_][\w]*)(?:\.[A-Za-z_][\w]*)*\s*$")
_MODULEMAP_UMBRELLA_HEADER_RE = re.compile(r'umbrella\s+header\s+"([^"]+)"')
_MODULEMAP_UMBRELLA_DIR_RE = re.compile(r'umbrella\s+"([^"]+)"')
_MODULEMAP_HEADER_RE = re.compile(r'(?:^|\s)header\s+"([^"]+)"')


# Swift compiler built-in imports that always appear in swiftinterfaces
# but never need a shim — they're served by the consumer's toolchain.
_BUILTIN_SWIFT_IMPORTS: Set[str] = {
    "Swift",
    "SwiftOnoneSupport",
    "Foundation",
    "ObjectiveC",
    "Darwin",
    "Dispatch",
}


def _scan_swiftinterface_imports(fw_path: Path) -> Set[str]:
    """Collect every top-level `import X` from every swiftinterface inside
    the framework's `Modules/<Name>.swiftmodule/` directory. Both the
    public `<arch>.swiftinterface` and the `<arch>.private.swiftinterface`
    are scanned — both are emitted by `xcodebuild archive` for a Swift
    framework with library evolution enabled, and both must succeed when
    consumers rebuild the interface, so missing-module checks have to
    union both. Submodule imports (`import X.Sub`) are normalized to the
    top-level module name (`X`); a downstream pass that injects shims
    needs the top-level name to match what's declared in the project's
    own `module.modulemap`.
    """
    modules_dir = _framework_content_root(fw_path) / "Modules"
    if not modules_dir.is_dir():
        return set()
    imports: Set[str] = set()
    for iface in modules_dir.rglob("*.swiftinterface"):
        try:
            text = iface.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        for line in text.splitlines():
            m = _SWIFTINTERFACE_IMPORT_RE.match(line)
            if m:
                imports.add(m.group(1))
    return imports


def _modules_declared_in_modulemap(modulemap_text: str) -> Set[str]:
    """Top-level module names declared by a `module.modulemap`. Submodules
    (`module M.Sub { ... }`) are recorded under the dotted name as
    written; the caller compares against swiftinterface imports which we
    pre-normalize to top-level names, so submodule names won't false-
    positive a match."""
    return set(_PACKAGE_MODULEMAP_LINE_RE.findall(modulemap_text))


def _find_project_modulemap_for_module(
    package: Package, module_name: str
) -> Optional[Tuple[Path, List[Tuple[Path, Path]]]]:
    """Search the staged package source tree for a `module.modulemap`
    that declares a top-level Clang module named `module_name`. Returns
    the modulemap path plus a list of `(absolute_header_path,
    header_path_relative_to_modulemap_dir)` tuples for every `.h` file
    that belongs to the module (umbrella header sibling set, umbrella
    directory walk, or explicit `header` references), or None when no
    project-shipped modulemap matches.

    Relative paths preserve directory structure under the modulemap's
    parent so the bridge-shim copier can mirror them under
    `Headers/<rel>` and the modulemap's textual references (e.g.
    `umbrella header "include/U.h"`, `header "sub/A.h"`) still resolve
    at consumer compile time. Flattening to basenames here would silently
    produce broken shims for any modulemap with nested header layouts.

    Resolves `umbrella header "X"` by copying every `.h` in the same
    directory as `X` (clang's umbrella-header semantics: the named
    header is the apex, but every sibling header is implicitly part of
    the module). Resolves `umbrella "dir"` by walking that directory
    recursively. Resolves explicit `header "X"` references one file at a
    time. Skips `.modulemap` files inside `TOXIC_NAMES` directories
    (`.git`, `.build`, etc.) so we only consider source-tree modulemaps.
    """
    if not package.staged_dir.is_dir():
        return None
    for modulemap_path in sorted(package.staged_dir.rglob("module.modulemap")):
        # Skip any modulemap living inside a directory we'd otherwise
        # consider toxic for the staged tree (already pruned at fetch
        # time, but defensive — covers downstream regen of `.build/`).
        if any(_is_toxic_entry(part) for part in modulemap_path.relative_to(package.staged_dir).parts):
            continue
        try:
            text = modulemap_path.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        if module_name not in _modules_declared_in_modulemap(text):
            continue

        modulemap_dir = modulemap_path.parent
        headers: List[Tuple[Path, Path]] = []
        seen_rel: Set[str] = set()

        # Umbrella header: copy the named header + all sibling .h in the
        # same directory (matches clang's umbrella-header expansion).
        # Use logical paths (no Path.resolve()) so umbrella headers that
        # are themselves symlinks pointing into a sibling directory don't
        # take us out of the umbrella's directory — WCDB ships
        # bridge/include/WCDBBridging.h as a symlink to ../WCDBBridging.h
        # while the 64 sibling .h are also symlinks into other subdirs;
        # the entire shim is meant to mirror bridge/include/, not bridge/.
        # Drop entries that don't resolve to a readable file: WCDB's
        # `bridge/include/` ships a few dangling symlinks pointing into
        # `bridge/tests/`, which SwiftPM-style staging excludes from the
        # source tree, and those test-only headers aren't part of any
        # public umbrella include chain.
        for um in _MODULEMAP_UMBRELLA_HEADER_RE.finditer(text):
            umbrella_rel = um.group(1)
            umbrella_path = modulemap_dir / umbrella_rel
            umbrella_dir = umbrella_path.parent
            if umbrella_dir.is_dir():
                for h in sorted(umbrella_dir.glob("*.h")):
                    if not h.is_file():
                        continue  # dangling symlink — nothing to copy
                    rel = h.relative_to(modulemap_dir)
                    rel_key = str(rel)
                    if rel_key not in seen_rel:
                        seen_rel.add(rel_key)
                        headers.append((h, rel))

        # Umbrella directory: walk recursively for .h files.
        for ud in _MODULEMAP_UMBRELLA_DIR_RE.finditer(text):
            # Skip if this match is actually `umbrella header "..."` —
            # the umbrella-header regex above already handled that.
            if 'umbrella header' in text[max(0, ud.start() - 20):ud.end() + 1]:
                continue
            dir_path = modulemap_dir / ud.group(1)
            if dir_path.is_dir():
                for h in sorted(dir_path.rglob("*.h")):
                    if not h.is_file():
                        continue  # dangling symlink — nothing to copy
                    rel = h.relative_to(modulemap_dir)
                    rel_key = str(rel)
                    if rel_key not in seen_rel:
                        seen_rel.add(rel_key)
                        headers.append((h, rel))

        # Explicit `header "X"` declarations.
        for hd in _MODULEMAP_HEADER_RE.finditer(text):
            header_rel = hd.group(1)
            header_path = modulemap_dir / header_rel
            if header_path.is_file():
                rel = Path(header_rel)
                rel_key = str(rel)
                if rel_key not in seen_rel:
                    seen_rel.add(rel_key)
                    headers.append((header_path, rel))

        if not headers:
            # Modulemap claims this module but we can't resolve any
            # headers from it (malformed, or all references point
            # outside the package). Better to surface than to silently
            # ship an empty shim.
            warn(
                f"  Found {modulemap_path.name} declaring {module_name!r} "
                f"but resolved no headers; cannot inject shim"
            )
            return None
        return (modulemap_path, headers)
    return None


def inject_bridge_clang_modules(
    *,
    xcframework_path: Path,
    package: Package,
    fw_name: str,
    verbose: bool,
) -> int:
    """Bundle every clang module the primary framework's swiftinterface
    imports but doesn't declare itself, sourced from a project-shipped
    `module.modulemap` in the package staged source tree.

    Mirrors `inject_system_clang_modules` for the project-shipped case.
    Without this, `import WCDB_Private` (and similar non-system modules
    a Swift target depends on via a custom modulemap) fails to resolve
    when the consumer's swiftc version differs from the build-time one
    and has to rebuild the swiftinterface.

    Returns the number of distinct shim frameworks injected (counted
    once per module name, not per slice). Idempotent: existing
    `<Name>.framework` siblings are skipped.
    """
    if not xcframework_path.is_dir():
        return 0

    slice_dirs = [p for p in sorted(xcframework_path.iterdir()) if p.is_dir()]
    if not slice_dirs:
        return 0

    # Pick the first slice's primary framework to scan swiftinterfaces
    # — every slice's swiftinterface has the same import set (Swift's
    # textual interface is target-triple-agnostic at the import level).
    primary_fw = slice_dirs[0] / f"{fw_name}.framework"
    if not primary_fw.is_dir():
        return 0

    imports = _scan_swiftinterface_imports(primary_fw)
    if not imports:
        return 0

    fw_modulemap = primary_fw / "Modules" / "module.modulemap"
    declared = (
        _modules_declared_in_modulemap(fw_modulemap.read_text(encoding="utf-8", errors="replace"))
        if fw_modulemap.is_file() else set()
    )
    # The framework itself is the most common "declared elsewhere"
    # case when its modulemap is absent (pure-Swift framework). Always
    # exclude the framework's own name + the swift built-ins.
    declared.add(fw_name)

    candidates = sorted(imports - declared - _BUILTIN_SWIFT_IMPORTS)
    if not candidates:
        return 0

    injected = 0
    for module_name in candidates:
        # Skip system modules: anything starting with `_` (Swift compiler
        # internals like `_Concurrency`, `_StringProcessing`,
        # `_SwiftConcurrencyShims`) is a stdlib-side import that doesn't
        # need a shim. System frameworks (Foundation, UIKit, …) won't
        # have a project-shipped modulemap and will fall through to the
        # `find` step returning None.
        if module_name.startswith("_"):
            continue
        match = _find_project_modulemap_for_module(package, module_name)
        if match is None:
            # Either a system framework (correctly skipped — consumers
            # link the SDK) or a genuinely missing dep we can't fix
            # from this layer. Stay quiet on the system case (most
            # candidates after dedup are systems) and only warn when
            # the modulemap WAS found but headers couldn't resolve
            # (handled inside the finder).
            continue
        modulemap_path, headers = match
        framework_modulemap = _promote_modulemap_to_framework_form(
            modulemap_path.read_text(encoding="utf-8", errors="replace")
        )

        any_slice_injected = False
        for slice_dir in slice_dirs:
            shim_fw = slice_dir / f"{module_name}.framework"
            if shim_fw.exists():
                continue  # idempotent
            shim_fw_modules = shim_fw / "Modules"
            shim_fw_headers = shim_fw / "Headers"
            shim_fw_modules.mkdir(parents=True, exist_ok=True)
            shim_fw_headers.mkdir(parents=True, exist_ok=True)
            (shim_fw_modules / "module.modulemap").write_text(framework_modulemap)
            # Preserve the modulemap-relative path under Headers/ so any
            # `umbrella header "include/U.h"` or `header "sub/A.h"` in the
            # original modulemap text still resolves against the shim's
            # header tree at consumer compile time. Mirrors the system-shim
            # path's relative-path preservation (see inject_system_clang_modules).
            for src_header, rel in headers:
                dest = shim_fw_headers / rel
                dest.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src_header, dest)
            (shim_fw / _SYSTEM_SHIM_SENTINEL).write_text(
                "spm-to-xcframework injected this framework as a Clang "
                "module shim for a project-shipped module.modulemap that "
                "the Swift target imports but xcodebuild didn't propagate "
                "into the primary framework. Do not delete; removing it "
                "makes language classification misclassify the parent "
                "xcframework.\n"
            )
            any_slice_injected = True

        if any_slice_injected:
            injected += 1
            dim(
                f"  Injected bridge Clang module shim: "
                f"{module_name}.framework (× {len(slice_dirs)} slice(s)) "
                f"from {modulemap_path.relative_to(package.staged_dir)}"
            )

    return injected


