# --- execute/dedup.py ------------------------------------------------------
# ============================================================================


import os
from pathlib import Path
from typing import Dict, Iterable, List, Mapping, Sequence, Set, Tuple



def _synth_dynamic_protected_targets(
    edits: Iterable[PackageSwiftEdit],
) -> Set[str]:
    """Return every target referenced by a synthetic dynamic-library
    edit — BOTH `synth_dynamic_library` (re-export of an existing
    non-dynamic product) AND `synth_library` (`--target T` escape
    hatch). Both kinds are applied through `_invoke_swift_add_product`,
    which always passes `--type dynamic-library`; the resulting product
    is `.library(name: …, type: .dynamic, targets: […])`.

    Rewriting one of these targets to `.binaryTarget(...)` mid-run
    would leave that surviving dynamic-library product pointing at a
    binary-only target — SPM rejects that shape at the next archive's
    manifest parse with:

        "invalid type for binary product; products referencing only
         binary targets must be executable or automatic library
         products"

    (See the matching comment block at `plan._is_binary_only_product`.)
    """
    protected: Set[str] = set()
    for edit in edits:
        if edit.kind in ("synth_dynamic_library", "synth_library"):
            protected.update(edit.targets)
    return protected


def _compute_dedup_substitutions(
    *,
    unit: BuildUnit,
    target_to_unit: Mapping[str, BuildUnit],
    built_by_unit: Mapping[str, ExecutedUnit],
    target_deps: Mapping[str, Set[str]],
    synth_dynamic_protected: Iterable[str] = (),
) -> List[Tuple[str, Path]]:
    """Pure helper: derive `(target_name, xcframework_path)` pairs to
    rewrite in `Package.swift` before `unit` builds.

    A substitution is emitted for each transitively-imported internal
    target T owned by a sibling build unit, when:

      1. T is not part of `unit.source_targets` (own targets are
         linked normally — substituting them would build them out of
         the wrong source).
      2. The sibling build unit owns T (and only T) — i.e. its
         `source_targets == [T]`. The xcframework that unit emits is
         named after the product (e.g. `StripeIssuing.xcframework`
         for a single-target product), so the binary's contained
         module IS T and re-pointing `.target(name: T)` at it is a
         clean 1:1 swap. Multi-target sibling units (e.g.
         `.library(name: "Kit", targets: ["A", "B"])` → one
         `Kit.xcframework` whose framework binary is the product, not
         the individual target) are SKIPPED — re-pointing
         `.target(name: "A")` at `Kit.xcframework` would cross
         module boundaries silently, and assigning the same path to
         both A and B is malformed in SPM. Codex P2 r5 regression.
      3. The sibling has already finished building (so we have a
         path to point at). If the sibling hasn't run yet — cycle in
         the unit graph, or filtered out of this run — leaving the
         source target alone is the safe fallback.
      4. T is NOT currently in `synth_dynamic_protected`. The set
         starts with every target wrapped by a planner-injected synth
         (`synth_dynamic_library` or `synth_library`) and shrinks
         after each synth unit finishes — `execute_source_plan`
         demotes the now-built synth product to automatic-library
         shape (strips `type: .dynamic`) and drops the unit's targets
         from the set. While T is still protected (its owning synth
         hasn't built yet), rewriting `.target(name: T)` to
         `.binaryTarget` would leave a still-`.dynamic` product
         pointing at a binary-only target — SPM rejects that at the
         next manifest parse. Skipping here is the conservative
         fallback; once protection drops, the next round's dedup
         pass picks T up normally. (Codex round-3 High.)

    Returned pairs are deduplicated and emitted in deterministic
    sort order (the inner loop walks `sorted(target_deps[src_t])`),
    so the audit log is stable across runs.
    """
    substitutions: List[Tuple[str, Path]] = []
    seen: Set[str] = set()
    own = set(unit.source_targets)
    protected = set(synth_dynamic_protected)
    for src_t in unit.source_targets:
        for dep_t in sorted(target_deps.get(src_t, set())):
            if dep_t in own or dep_t in seen:
                continue
            sibling = target_to_unit.get(dep_t)
            if sibling is None or sibling.name == unit.name:
                continue
            # Multi-target sibling units don't participate: their
            # xcframework was built as the product (one framework
            # binary), not as the individual target T, so it isn't a
            # valid 1:1 stand-in for `.target(name: T, ...)`. Falling
            # through here means the consumer keeps `.target(...)`
            # for T and SPM statically embeds T's symbols (legacy
            # behavior). (Codex P2 r5 regression.)
            if list(sibling.source_targets) != [dep_t]:
                continue
            sibling_executed = built_by_unit.get(sibling.name)
            if sibling_executed is None:
                continue
            if dep_t in protected:
                # The synth product that wraps dep_t hasn't been
                # demoted yet (its owning unit hasn't finished
                # building, or we're being called out of topo order).
                # Rewriting dep_t to .binaryTarget right now would
                # invalidate the surviving .library(type: .dynamic,
                # targets: [dep_t]) product — SPM rejects binary-only
                # dynamic products at the next manifest parse. The
                # post-build demote in `execute_source_plan` removes
                # dep_t from `protected` once its synth unit
                # completes; the next iteration's pass picks it up
                # then. (Codex round-3 High.)
                continue
            substitutions.append((dep_t, sibling_executed.xcframework_path))
            seen.add(dep_t)
    return substitutions


def _apply_dedup_overlap_substitutions(
    *,
    staged_dir: Path,
    substitutions: Sequence[Tuple[str, Path]],
    unit_name: str,
    verbose: bool,
) -> None:
    """Mutate the active Package.swift in `staged_dir` so each
    `(target_name, xcframework_path)` pair becomes a `.binaryTarget`
    declaration before the next unit's `xcodebuild archive` runs.

    Edits are idempotent — a target already shaped as `.binaryTarget`
    is left alone — and applied in stable order so the audit log is
    deterministic across runs. The active manifest is the same file
    `apply_package_swift_edits` chose during Prepare; we re-resolve it
    here rather than caching the path on `Config`, so a toolchain
    change between Prepare and Execute (vanishingly unlikely, but
    cheap to defend against) wouldn't desync the two phases.

    Side effect: writes the edited manifest text. The previous
    `apply_package_swift_edits` snapshot at `.original-Package.swift`
    is left untouched — that's the user's recovery handle if a
    dedup-overlap edit is later reported to be wrong.
    """
    manifest_path = _select_active_manifest(staged_dir)
    if not manifest_path.is_file():
        raise ExecuteError(
            f"dedup-overlap substitution: cannot read active manifest at "
            f"{manifest_path} for unit {unit_name!r}"
        )
    text = manifest_path.read_text()
    # Re-assert the unsupported-construct guard here. `apply_package_swift_edits`
    # would have run it during Prepare — but only if the planner emitted at least
    # one edit. When Prepare takes its no-op path (no package_swift_edits), the
    # guard is skipped, and an Execute-time dedup edit on a manifest with
    # triple-quoted strings, `#"..."#` raw strings, or `\(...)` interpolation
    # would silently mis-parse via `_make_code_token_view` (which only tracks
    # `"..."` strings). Running the guard here closes that gap.
    # (Codex P2 round-4 regression.)
    try:
        _assert_no_unsupported_swift_constructs(text)
    except PrepareUserError as exc:
        raise ExecuteError(
            f"dedup-overlap substitution failed for unit {unit_name!r}: "
            f"the active Package.swift uses a Swift construct the dedup-overlap "
            f"editor can't reason about. {exc} Re-run with --no-dedup-overlap to "
            f"disable the inter-unit binaryTarget rewrite for this package."
        ) from exc
    # SPM's `.binaryTarget(path: ...)` rejects two shapes that look
    # superficially fine: ABSOLUTE paths ("path expected to be relative
    # to package root") and paths resolved against the wrong base. We
    # have an absolute xcframework path (resolved at CLI parse time)
    # and a staged manifest in a tempdir; bridge the two with
    # `os.path.relpath`, which produces `../../..` chains as needed.
    # `dump-package` and `xcodebuild archive` both accept upward
    # `../`-relative paths (verified against `stripe-ios --target
    # StripeCore --product Stripe` smoke). Use the resolved staged_dir
    # as the base so symlinks in either direction don't desync the
    # rel-path computation.
    staged_root = staged_dir.resolve()
    rel_subs: List[Tuple[str, Path, str]] = [
        (
            name,
            Path(xcfw).resolve(),
            os.path.relpath(Path(xcfw).resolve(), staged_root),
        )
        for name, xcfw in substitutions
    ]

    # Route between two edit strategies:
    #
    #   1. The default in-place `.target → .binaryTarget` rewrite, which
    #      relies on locating `.target(name: T, ...)` calls in the
    #      manifest and substituting the call in place. Fast, leaves the
    #      manifest looking close to original, doesn't introduce new
    #      symbols.
    #
    #   2. The overlay edit, which injects a sentinel-wrapped
    #      `_SPM2XC_OVERLAY_TARGETS: [Target]` block before the
    #      `Package(...)` call and post-processes its `targets:`
    #      argument expression with a `filter + append`. Used when
    #      the in-place rewrite would mis-fire — chiefly manifests
    #      that build their target list through a user-defined wrapper
    #      type whose `.target(name:, ...)` shadows `Target.target`,
    #      so the textual finder would rewrite the wrapper call and
    #      produce `CustomTarget.binaryTarget(...)` which doesn't
    #      compile. The canonical case is swift-collections'
    #      `CustomTarget` + `toTarget()` pattern.
    #
    # Detection is the same `_CUSTOM_TARGET_WRAPPER_SIGNALS` check the
    # planner uses (`plan._manifest_uses_custom_target_wrapper_text`).
    # If the overlay is already in place (sentinel present), keep using
    # the overlay path so a previously-injected wrap is grown instead of
    # being shadowed by a parallel in-place edit on the same manifest.
    use_overlay = (
        _manifest_uses_custom_target_wrapper_text(text)
        or _OVERLAY_SENTINEL_BEGIN in text
    )

    if use_overlay:
        delta = [(name, rel) for name, _abs, rel in rel_subs]
        try:
            edited = edit_inject_or_extend_overlay_binary_targets(text, delta)
        except PrepareUserError as exc:
            raise ExecuteError(
                f"dedup-overlap substitution failed for unit {unit_name!r}: "
                f"{exc}"
            ) from exc
        if edited != text:
            manifest_path.write_text(edited)
            applied = [f"{name} -> {abs_path.name}" for name, abs_path, _ in rel_subs]
            info(
                f"  {unit_name}: dedup-overlap (overlay) added "
                f"{len(applied)} sibling target(s) to the overlay: "
                + ", ".join(applied)
            )
        else:
            verbose_log(
                verbose,
                f"  {unit_name}: dedup-overlap (overlay) no-op — all "
                f"{len(rel_subs)} target(s) already present in the overlay",
            )
        return

    edited = text
    applied: List[str] = []
    skipped: List[str] = []
    for target_name, abs_path, rel_path in rel_subs:
        try:
            new_text = edit_replace_with_binary_target(edited, target_name, rel_path)
        except PrepareUserError as exc:
            raise ExecuteError(
                f"dedup-overlap substitution failed for unit {unit_name!r} "
                f"target {target_name!r}: {exc}"
            ) from exc
        if new_text != edited:
            applied.append(f"{target_name} -> {abs_path.name}")
            edited = new_text
        else:
            skipped.append(target_name)
    if edited != text:
        manifest_path.write_text(edited)
    if applied:
        info(
            f"  {unit_name}: dedup-overlap rewrote "
            f"{len(applied)} sibling target(s) to .binaryTarget: "
            + ", ".join(applied)
        )
    if skipped:
        verbose_log(
            verbose,
            f"  {unit_name}: dedup-overlap left {len(skipped)} target(s) "
            f"unchanged (already .binaryTarget): " + ", ".join(skipped),
        )


def _compute_phantom_helper_deps(
    *,
    unit: BuildUnit,
    package: Package,
    substituted_target_names: Set[str],
    target_deps: Mapping[str, Set[str]],
) -> Dict[str, List[str]]:
    """Return `{source_target: [phantom_helper_name, ...]}` for `unit`.

    A "phantom helper" is a sibling target that:
      1. Is being binary-substituted on this dedup-overlap pass (or was
         on a prior pass — i.e. it's in `substituted_target_names`).
      2. Is in `source_target`'s **transitive** dep closure
         (`target_deps[source_target]`).
      3. Is NOT in `source_target`'s **direct** manifest-declared
         dependencies.

    These are the deps SPM needs to discover for the consumer's compile
    to resolve sibling `.swiftinterface` imports, but doesn't because
    binary targets are opaque to SPM's source-level dep graph walker.
    Canonical case: Apple swift-collections — `Collections`'s direct
    deps are `[BitCollections, ..., _RopeModule]`, all six siblings
    transitively depend on `InternalCollectionsUtilities` (`kind:
    .hidden`), and once the siblings become `.binaryTarget`s the
    `InternalCollectionsUtilities` slice dir never makes it onto
    `Collections`'s `FRAMEWORK_SEARCH_PATHS`. The fix: augment
    `Collections`'s `dependencies:` array with the helper name so SPM
    rediscovers the binary target through the normal dep-walk machinery.

    Returns an empty dict when the unit has no phantom helpers — i.e.
    every substituted sibling is already a direct dep, or the unit
    isn't an umbrella. The caller skips the augmentation pass in that
    case (no-op manifest read avoided).
    """

    raw_targets_by_name: Dict[str, dict] = {}
    for raw_t in package.raw_dump.get("targets", []) or []:
        if isinstance(raw_t, dict):
            nm = raw_t.get("name")
            if isinstance(nm, str):
                raw_targets_by_name[nm] = raw_t

    result: Dict[str, List[str]] = {}
    for src_t in unit.source_targets:
        raw_t = raw_targets_by_name.get(src_t)
        if raw_t is None:
            continue
        direct = set(_raw_internal_dep_names(raw_t))
        transitive = target_deps.get(src_t, set())
        phantoms = [
            n for n in sorted(transitive & substituted_target_names)
            if n not in direct and n != src_t
        ]
        if phantoms:
            result[src_t] = phantoms
    return result


def _apply_phantom_helper_dep_augmentation(
    *,
    staged_dir: Path,
    phantom_helpers: Mapping[str, Sequence[str]],
    unit_name: str,
    verbose: bool,
) -> None:
    """For each `(source_target, [phantom_name, ...])` pair, append the
    phantom names to the source target's `dependencies:` array in the
    active Package.swift.

    No-op (and silent) if `phantom_helpers` is empty. Otherwise reads
    the active manifest, applies one `edit_augment_target_dependencies`
    call per source target, writes once at the end. Idempotent: the
    underlying edit skips already-present entries, so re-running on a
    manifest with the phantom already declared is a no-op.

    Raises `ExecuteError` if the augmentation fails for a source target
    that we know is in the manifest — that means our planner's view of
    the package and the manifest text disagree, which is a hard
    inconsistency the caller can't recover from without operator
    intervention.
    """
    if not phantom_helpers:
        return
    manifest_path = _select_active_manifest(staged_dir)
    if not manifest_path.is_file():
        raise ExecuteError(
            f"phantom-helper augmentation: cannot read active manifest at "
            f"{manifest_path} for unit {unit_name!r}"
        )
    text = manifest_path.read_text()
    try:
        _assert_no_unsupported_swift_constructs(text)
    except PrepareUserError as exc:
        raise ExecuteError(
            f"phantom-helper augmentation failed for unit {unit_name!r}: "
            f"{exc} Re-run with --no-dedup-overlap to disable the phantom-"
            f"helper dep injection (and inter-unit binaryTarget rewrite) "
            f"for this package."
        ) from exc

    edited = text
    applied: List[str] = []
    for src_t, phantoms in phantom_helpers.items():
        try:
            new_text = edit_augment_target_dependencies(
                edited, src_t, list(phantoms)
            )
        except PrepareUserError as exc:
            raise ExecuteError(
                f"phantom-helper augmentation failed for unit {unit_name!r} "
                f"target {src_t!r}: {exc}"
            ) from exc
        if new_text != edited:
            applied.append(f"{src_t}: +{','.join(phantoms)}")
            edited = new_text
    if edited != text:
        manifest_path.write_text(edited)
    if applied:
        info(
            f"  {unit_name}: dedup-overlap added phantom helper dep(s) to "
            f"umbrella target(s): " + "; ".join(applied)
        )
    else:
        verbose_log(
            verbose,
            f"  {unit_name}: phantom-helper augmentation no-op (all helper "
            f"deps already declared)",
        )


def _demote_synth_product_in_manifest(
    *,
    staged_dir: Path,
    product_name: str,
    unit_name: str,
    verbose: bool,
) -> bool:
    """Strip `type: .dynamic` from the planner-injected
    `.library(name: <product_name>, ...)` declaration in the active
    Package.swift. Returns True iff the manifest was actually mutated
    (False on idempotent re-entry, when the product is already in
    automatic-library shape).

    Called immediately AFTER a synth unit finishes archiving. The
    surviving automatic-library product keeps the consumer-visible
    product name alive (downstream consumers still depend on it by
    name) but no longer forces `.dynamic` linkage — which unblocks
    the next unit's `replace_with_binary_target` substitution for the
    same target. (See Codex round-3 High: simply skipping dedup for
    protected targets violated the duplicate-symbol-prevention
    invariant.)

    Idempotent: if the product is already automatic-shape (manual
    re-run, prior demote, etc.) the function returns False without
    touching the file. Raises `ExecuteError` if the demote helper
    can't locate the product or finds it in a malformed state.
    """
    manifest_path = _select_active_manifest(staged_dir)
    if not manifest_path.is_file():
        raise ExecuteError(
            f"synth-product demote: cannot read active manifest at "
            f"{manifest_path} for unit {unit_name!r}"
        )
    text = manifest_path.read_text()
    try:
        _assert_no_unsupported_swift_constructs(text)
    except PrepareUserError as exc:
        raise ExecuteError(
            f"synth-product demote failed for unit {unit_name!r}: "
            f"the active Package.swift uses a Swift construct the editor "
            f"can't reason about. {exc} Re-run with --no-dedup-overlap to "
            f"disable post-build product demotion (and inter-unit "
            f"binaryTarget substitution) for this package."
        ) from exc
    try:
        edited = edit_demote_synthetic_product(text, product_name)
    except PrepareUserError as exc:
        raise ExecuteError(
            f"synth-product demote failed for unit {unit_name!r} "
            f"product {product_name!r}: {exc}"
        ) from exc
    if edited == text:
        verbose_log(
            verbose,
            f"  {unit_name}: synth product {product_name!r} already "
            f"automatic-shape (no demote needed)",
        )
        return False
    manifest_path.write_text(edited)
    info(
        f"  {unit_name}: demoted synthetic product {product_name!r} to "
        f"automatic library (unblocks dedup-overlap for its target(s))"
    )
    return True


# ============================================================================
# --- execute/run_unit.py ---------------------------------------------------
# ============================================================================


from pathlib import Path
from typing import Dict, List, Set



# Swift's "Switch covers known cases, but X may have additional unknown values"
# diagnostic. Fires at module-emit time when an umbrella does an exhaustive
# switch (no `@unknown default`) over an enum imported from a now-resilient
# binary sibling. Library-evolution mode treats the rewritten `.binaryTarget`
# as a fully resilient external module, so cases that were exhaustive while
# the sibling was a same-package `.target` become non-exhaustive once
# dedup-overlap has rewritten it. The diagnostic text is stable across the
# Swift versions we currently target (5.9..6.2); update here if Apple ever
# rewords it.
_RESILIENCE_DIAGNOSTIC_PATTERN = "may have additional unknown values"


def _is_resilience_diagnostic(error_message: str) -> bool:
    """Return True iff the formatted ExecuteError text contains the Swift
    library-evolution switch-exhaustiveness diagnostic that dedup-overlap's
    `.target → .binaryTarget` rewrite can introduce.

    Pure string match against `_format_execute_error`'s rendered errors[]
    block. Cheap, defensive (only triggers the auto-rollback when the
    failure signature actually matches), and easy to extend with additional
    patterns if more dedup-induced failure modes are discovered.
    """
    return _RESILIENCE_DIAGNOSTIC_PATTERN in error_message


def _run_one_unit(
    unit: BuildUnit,
    *,
    prepared: PreparedPlan,
    config: Config,
) -> ExecutedUnit:
    """End-to-end Execute pipeline for a single source-mode build unit.

    1. Parallel archive for every enabled platform slice.
    2. For synth_dynamic_library units (scheme != framework_name),
       rename each slice's framework bundle from the synthetic scheme
       to the final framework name.
    3. Inject swiftmodule + ObjC headers + resource bundles per slice.
    4. Merge all slices via `xcodebuild -create-xcframework`.
    5. (Optional) walk dependency frameworks if `--include-deps` is set
       — iOS-only in v1; non-iOS slices don't carry dep artifacts.
    """
    assert config.work_dir is not None
    work_dir = config.work_dir
    staged_dir = prepared.package.staged_dir

    selected = _selected_slices(config)
    if not selected:
        raise ExecuteError(
            "no platforms selected; pass --min-ios / --min-macos / "
            "--min-tvos / --min-maccatalyst / --min-watchos / --min-visionos"
        )

    archive_slices = _archive_all_parallel(
        unit,
        selected=selected,
        staged_dir=staged_dir,
        work_dir=work_dir,
        verbose=config.verbose,
    )

    for sid, s in archive_slices.items():
        if s.framework_path is None:
            raise ExecuteError(
                f"{unit.name}: {sid} archive completed but "
                f"{unit.scheme}.framework not found under "
                f"{s.archive_path}/Products/. The synthetic dynamic-library "
                f"product did not produce a framework bundle."
            )

    # synth_dynamic_library rename: xcodebuild emitted
    # `<scheme>.framework` for each slice; consumers expect
    # `<framework_name>.framework`. Rename in place before any injection
    # pass runs so downstream code sees the final name.
    if unit.scheme != unit.framework_name:
        for sid, s in archive_slices.items():
            s.framework_path = rename_framework_bundle(
                s.framework_path,
                new_name=unit.framework_name,
                verbose=config.verbose,
            )

    primary_id, primary_slice = next(iter(archive_slices.items()))
    fw_name = primary_slice.framework_path.stem
    success(
        f"  {unit.name}: {primary_id} "
        f"{primary_slice.framework_path.relative_to(primary_slice.archive_path.parent)}"
    )

    # Injection passes — every slice. The `variant` label is the slice_id
    # so user-visible logs identify which platform the diagnostic
    # belongs to.
    for sid, s in archive_slices.items():
        inject_swiftmodule(
            fw_path=s.framework_path,
            fw_name=fw_name,
            scheme=unit.scheme,
            dd_path=s.dd_path,
            variant=sid,
            verbose=config.verbose,
            extra_module_names=unit.source_targets,
        )
        inject_objc_headers(
            package=prepared.package,
            product_name=unit.name,
            fw_name=fw_name,
            fw_path=s.framework_path,
            verbose=config.verbose,
        )
        inject_resource_bundles(
            fw_path=s.framework_path,
            fw_name=fw_name,
            dd_path=s.dd_path,
            variant=sid,
            verbose=config.verbose,
        )

    output_xcframework = config.output_dir / f"{unit.name}.xcframework"
    info(f"  Creating {unit.name}.xcframework...")
    create_xcframework(
        output_xcframework=output_xcframework,
        frameworks=[s.framework_path for s in archive_slices.values()],
        verbose=config.verbose,
    )
    # Bundle any `.systemLibrary` Clang modules the build unit depends on
    # as binary-less sibling shim frameworks inside each xcframework
    # slice. This is what makes GRDB-style packages (regular Swift target
    # → .systemLibrary wrapper around <sqlite3.h>) consumable: without
    # the shim, swiftc fails to rebuild the framework's swiftinterface
    # because `import GRDBSQLite` cannot resolve. See
    # `inject_system_clang_modules` for the full rationale.
    inject_system_clang_modules(
        xcframework_path=output_xcframework,
        package=prepared.package,
        source_targets=unit.source_targets,
        verbose=config.verbose,
    )
    # Bundle any project-shipped clang modules the swiftinterface imports
    # but the primary framework's modulemap doesn't declare (e.g. WCDB's
    # `WCDB_Private` shipped via `src/bridge/module.modulemap`). Distinct
    # from the `.systemLibrary` pass above: that one walks the parsed
    # SPM model, this one matches by parsing the framework's emitted
    # swiftinterface against modulemaps actually shipped in the package
    # source tree.
    inject_bridge_clang_modules(
        xcframework_path=output_xcframework,
        package=prepared.package,
        fw_name=fw_name,
        verbose=config.verbose,
    )
    fw_type = detect_framework_type(output_xcframework)
    success(f"  {unit.name}.xcframework ready [{fw_type}]")

    dep_xcframeworks: List[DependencyXcframework] = []
    if prepared.plan.include_deps:
        ios_dev = archive_slices.get("ios-arm64")
        ios_sim = archive_slices.get("ios-simulator")
        if ios_dev is not None and ios_sim is not None:
            dep_xcframeworks = _build_dependency_xcframeworks(
                unit=unit,
                package=prepared.package,
                device_slice=ios_dev,
                sim_slice=ios_sim,
                primary_fw_name=fw_name,
                output_dir=config.output_dir,
                verbose=config.verbose,
            )
        else:
            # iOS not selected — main() already rejects this case before
            # Execute runs, so reaching here is a programmer error.
            warn(
                f"  {unit.name}: --include-deps skipped (iOS device + "
                "simulator slices not in this build)"
            )

    return ExecutedUnit(
        name=unit.name,
        slices=list(archive_slices.values()),
        xcframework_path=output_xcframework,
        framework_name=fw_name,
        framework_type=fw_type,
        expected_language=unit.language,
        expected_slice_classes=_expected_slice_classes(config),
        dependency_xcframeworks=dep_xcframeworks,
    )


def execute_source_plan(
    prepared: PreparedPlan,
    config: Config,
) -> List[ExecutedUnit]:
    """Run the full Execute pipeline for every source-mode unit in the
    plan. Sequential across units (each unit's slices already build in
    parallel internally).

    Skips any unit with `archive_strategy == "copy-artifact"` — binary
    mode is handled by `execute_binary_plan` below. Returns the list of
    ExecutedUnits in plan order. Raises `ExecuteError` on the first
    failure (later units are not attempted, matching Session 3's
    fail-fast contract).

    Build-unit ordering: when dedup-overlap is enabled (default), units
    are walked in topological order over their internal target deps so
    each leaf builds before any sibling that imports it. Between unit
    builds, already-built siblings get rewritten in `Package.swift` from
    `.target(...)` to `.binaryTarget(path: ...)` pointing at the freshly
    produced xcframework. The umbrella product (e.g. Stripe) then links
    dynamically against the sibling xcframeworks instead of statically
    embedding their Mach-O. See REWRITE_DESIGN.md §5.4 dedup-overlap.

    `--no-dedup-overlap` reverts to the legacy behavior: planner-order
    walk, no inter-unit manifest mutation, sibling targets get statically
    re-compiled into every umbrella product that imports them.
    """
    if config.work_dir is None:
        raise ExecuteError("internal error: config.work_dir was not allocated before Execute")
    archive_units = [u for u in prepared.plan.build_units if u.archive_strategy != "copy-artifact"]
    if not archive_units:
        return []

    if config.no_dedup_overlap:
        ordered_units: List[BuildUnit] = list(archive_units)
    else:
        ordered_units = topo_order_units(archive_units, prepared.package)

    target_to_unit: Dict[str, BuildUnit] = {}
    for u in ordered_units:
        for t in u.source_targets:
            target_to_unit.setdefault(t, u)

    target_deps = (
        compute_internal_target_deps(prepared.package)
        if not config.no_dedup_overlap
        else {}
    )
    # Mutable: starts populated from the planner's synth_* edits, then
    # shrinks every time a synth unit finishes building (and we demote
    # its product to automatic-library shape, removing the SPM
    # binary-only-product invariant violation that previously blocked
    # `.binaryTarget` substitution for its targets). See Codex round-3
    # High: a static "never dedup protected targets" rule left
    # duplicate-symbol consumer links unfixed.
    synth_dynamic_protected = (
        _synth_dynamic_protected_targets(prepared.plan.package_swift_edits)
        if not config.no_dedup_overlap
        else set()
    )
    # Build the unit → planner-injected synth product mapping once.
    # synth_dynamic_library edits: unit.scheme == edit.product_name
    # (and unit.framework_name is the original product name, post-
    # rename). synth_library (--target T) edits: unit.synthetic and
    # unit.scheme == edit.product_name == T. Either way, the planner
    # never emits two synth edits for one unit, so an "encounter the
    # match, break" loop suffices.
    unit_to_synth_product: Dict[str, str] = {}
    unit_to_synth_targets: Dict[str, List[str]] = {}
    if not config.no_dedup_overlap:
        edits_by_product = {
            e.product_name: e for e in prepared.plan.package_swift_edits
            if e.kind in ("synth_dynamic_library", "synth_library")
        }
        for u in ordered_units:
            edit = edits_by_product.get(u.scheme)
            if edit is not None:
                unit_to_synth_product[u.name] = edit.product_name
                unit_to_synth_targets[u.name] = list(edit.targets)

    bold(f"\nExecuting {len(ordered_units)} build unit(s)...")
    config.output_dir.mkdir(parents=True, exist_ok=True)
    results: List[ExecutedUnit] = []
    built_by_unit: Dict[str, ExecutedUnit] = {}
    staged_dir = prepared.package.staged_dir
    # Set of every sibling target name that has been binary-substituted on
    # any prior unit's dedup-overlap pass. Used by the phantom-helper
    # augmentation: a helper that was promoted to a sibling xcframework
    # by an earlier unit needs to be added to the current unit's umbrella
    # deps even if it isn't part of THIS pass's substitutions list (the
    # pass dedupes same-name re-substitutions, so an InternalCollections-
    # Utilities that became a binary target two units ago doesn't show up
    # again — but it's still a sibling whose slice the umbrella needs).
    substituted_target_names: Set[str] = set()

    # Lazy import: keep `prepare` out of the top-of-module import graph
    # (the dedup helpers already do this same lazy pattern for symmetric
    # reasons — see `_apply_dedup_overlap_substitutions`).

    for unit in ordered_units:
        # Snapshot the per-unit fallback state. On a successful first
        # archive these snapshots are discarded; on the Swift
        # library-evolution switch-exhaustiveness diagnostic they're
        # used to put both the on-disk manifest AND the in-memory
        # `substituted_target_names` set back to their exact pre-unit
        # values before a single retry. The rollback only fires when:
        #   1. dedup-overlap is enabled globally,
        #   2. this unit's archive actually failed,
        #   3. this unit applied at least one NEW substitution (no-op
        #      re-proposals of names already substituted by an earlier
        #      unit don't count — the manifest text is unchanged and
        #      rolling back would be misleading), AND
        #   4. the formatted error message contains the resilience
        #      diagnostic — narrow gate so unrelated build failures
        #      still surface promptly with the original error.
        # See `_is_resilience_diagnostic` for the canonical Swift text.
        manifest_path = _select_active_manifest(staged_dir)
        pre_unit_manifest_text = (
            manifest_path.read_text() if manifest_path.is_file() else None
        )
        # Snapshot the set wholesale rather than tracking "this unit
        # added X" — `_compute_dedup_substitutions` re-emits names
        # already substituted by prior units (the apply helper is
        # idempotent at the manifest-text level), so a per-tuple
        # `.discard` would corrupt the set when a name was in it
        # before this unit's pass started. (Codex r1 P1 #1.)
        pre_unit_substituted_target_names = set(substituted_target_names)
        # True iff THIS unit's substitution pass actually mutated the
        # manifest (i.e. produced at least one novel `.target` →
        # `.binaryTarget` rewrite). Re-proposing a name that was
        # already substituted by a prior unit leaves the manifest
        # text untouched; in that case there's nothing for the
        # fallback to undo for this unit, so the warning would be
        # misleading and the retry would fail identically.
        unit_applied_new_substitution = False
        unit_applied_substitution_names: List[str] = []

        if not config.no_dedup_overlap:
            substitutions = _compute_dedup_substitutions(
                unit=unit,
                target_to_unit=target_to_unit,
                built_by_unit=built_by_unit,
                target_deps=target_deps,
                synth_dynamic_protected=synth_dynamic_protected,
            )
            if substitutions:
                # The apply helper writes only when at least one
                # `.target` was actually rewritten — detect the same
                # condition by comparing manifest text before/after.
                pre_apply_text = (
                    manifest_path.read_text() if manifest_path.is_file() else ""
                )
                _apply_dedup_overlap_substitutions(
                    staged_dir=staged_dir,
                    substitutions=substitutions,
                    unit_name=unit.name,
                    verbose=config.verbose,
                )
                post_apply_text = (
                    manifest_path.read_text() if manifest_path.is_file() else ""
                )
                if post_apply_text != pre_apply_text:
                    unit_applied_new_substitution = True
                    # Only the names that weren't already substituted by
                    # a prior unit are novel this pass — listing the
                    # idempotent no-op re-proposals in the fallback
                    # warning would overstate the rollback scope and
                    # mislead operators. (Codex r2 P3.)
                    unit_applied_substitution_names = [
                        name for name, _ in substitutions
                        if name not in pre_unit_substituted_target_names
                    ]
                for name, _path in substitutions:
                    substituted_target_names.add(name)
            # Inject "phantom helper" deps on the umbrella's source
            # target — substituted sibling targets that are in the
            # transitive but not the direct dep closure. Without this,
            # SPM doesn't add the helper's binary-target slice to the
            # umbrella's `FRAMEWORK_SEARCH_PATHS`, and the umbrella
            # compile fails to resolve `import <Helper>` calls embedded
            # in sibling `.swiftinterface` files. Runs unconditionally
            # (even when this unit had zero new substitutions): the
            # umbrella may still need helpers that were registered on
            # earlier units' passes. See
            # `_compute_phantom_helper_deps` for the predicate.
            phantom_helpers = _compute_phantom_helper_deps(
                unit=unit,
                package=prepared.package,
                substituted_target_names=substituted_target_names,
                target_deps=target_deps,
            )
            if phantom_helpers:
                _apply_phantom_helper_dep_augmentation(
                    staged_dir=staged_dir,
                    phantom_helpers=phantom_helpers,
                    unit_name=unit.name,
                    verbose=config.verbose,
                )

        try:
            executed = _run_one_unit(unit, prepared=prepared, config=config)
        except ExecuteError as exc:
            # Only retry when dedup-overlap is the plausible cause: this
            # unit applied at least one NEW substitution this pass AND
            # the error text matches the canonical Swift resilience
            # diagnostic. Otherwise the original error surfaces
            # unchanged — unrelated build failures must not be masked
            # by a second silent rebuild.
            if (
                not config.no_dedup_overlap
                and unit_applied_new_substitution
                and pre_unit_manifest_text is not None
                and _is_resilience_diagnostic(str(exc))
            ):
                substituted_names = ", ".join(unit_applied_substitution_names)
                warn(
                    f"  {unit.name}: dedup-overlap fallback — Swift "
                    f"library-evolution flagged exhaustive switch over "
                    f"resilient enum(s) from substituted sibling(s) "
                    f"({substituted_names}). Restoring the manifest and "
                    f"re-archiving without the substitution for this unit. "
                    f"Trade-off: {unit.name}'s framework will statically "
                    f"embed those sibling target(s) — a consumer linking "
                    f"both this xcframework AND the sibling xcframework "
                    f"will see duplicate symbols. Pass --no-dedup-overlap "
                    f"globally to silence this auto-recovery."
                )
                manifest_path.write_text(pre_unit_manifest_text)
                # Restore the in-memory set wholesale rather than
                # discarding the unit's names — a re-proposal that was
                # idempotent on the manifest must remain present in the
                # set so later units' phantom-helper computation stays
                # consistent with the still-substituted manifest text.
                # (Codex r1 P1 #1.)
                substituted_target_names.clear()
                substituted_target_names.update(pre_unit_substituted_target_names)
                # The manifest restore also reverted this unit's
                # phantom-helper augmentation. Recompute against the
                # restored set (which captures every still-substituted
                # sibling from prior units) and re-apply so the retry's
                # umbrella sees the correct `dependencies:` edges for
                # any persistent `.binaryTarget` siblings. Augmentation
                # is idempotent (the underlying edit skips already-
                # present entries), so this is safe even when nothing
                # changed. (Codex r1 P1 #2.)
                phantom_helpers_retry = _compute_phantom_helper_deps(
                    unit=unit,
                    package=prepared.package,
                    substituted_target_names=substituted_target_names,
                    target_deps=target_deps,
                )
                if phantom_helpers_retry:
                    _apply_phantom_helper_dep_augmentation(
                        staged_dir=staged_dir,
                        phantom_helpers=phantom_helpers_retry,
                        unit_name=unit.name,
                        verbose=config.verbose,
                    )
                try:
                    executed = _run_one_unit(
                        unit, prepared=prepared, config=config
                    )
                except ExecuteError as retry_exc:
                    # Preserve the original resilience-diagnostic
                    # failure alongside the retry failure — masking
                    # the first error makes triage harder when both
                    # attempts fail for different reasons.
                    # (Codex r1 P2 #4.)
                    raise ExecuteError(
                        f"{retry_exc}\n\n"
                        f"(dedup-overlap fallback retry also failed for "
                        f"unit {unit.name!r}; the original library-"
                        f"evolution diagnostic that triggered the "
                        f"fallback was:\n{exc})"
                    ) from retry_exc
            else:
                raise

        results.append(executed)
        built_by_unit[unit.name] = executed

        # Post-build: if this unit owns a planner-injected synth
        # product, demote it from `.dynamic` to automatic-library and
        # drop its targets from the protected set so the NEXT unit's
        # dedup pass can substitute them with `.binaryTarget`. The
        # demote is what makes the manifest valid for binary-only
        # products — without it, the surviving
        # `.library(type: .dynamic, targets: [T])` would crash SPM's
        # next manifest parse the moment we rewrite T to .binaryTarget.
        if not config.no_dedup_overlap and unit.name in unit_to_synth_product:
            _demote_synth_product_in_manifest(
                staged_dir=staged_dir,
                product_name=unit_to_synth_product[unit.name],
                unit_name=unit.name,
                verbose=config.verbose,
            )
            for t in unit_to_synth_targets[unit.name]:
                synth_dynamic_protected.discard(t)
    return results


# ============================================================================
# --- execute/binary_promote.py ---------------------------------------------
# ============================================================================


import os
import plistlib
import shutil
import subprocess
from pathlib import Path
from typing import List, Optional



def _lipo_archs(static_lib: Path) -> List[str]:
    """Return the architectures present in a Mach-O archive, via
    `lipo -archs`. Empty list on failure (lipo missing, file is not a
    Mach-O object, etc.) — the caller treats that as "can't promote".
    """
    cp = subprocess.run(
        ["lipo", "-archs", str(static_lib)],
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    if cp.returncode != 0:
        return []
    return [a for a in cp.stdout.strip().split() if a]


def _slice_minimum_deployment_target(
    available_entry: dict,
    platform: str,
) -> str:
    """Pull the slice's `MinimumOSVersion`/`MinimumDeploymentTarget` out
    of an xcframework `AvailableLibraries[]` entry. Falls back to a
    permissive low version per platform when the plist doesn't carry one
    — clang only uses it to set the load command, and the
    `-undefined dynamic_lookup` safety net means the link itself does not
    depend on the precise minimum.
    """
    for key in ("MinimumOSVersion", "MinimumDeploymentTarget"):
        v = available_entry.get(key)
        if isinstance(v, str) and v.strip():
            return v.strip()
    return {
        "ios": "13.0",
        "macos": "11.0",
        "maccatalyst": "13.0",
        "tvos": "13.0",
        "watchos": "6.0",
        "visionos": "1.0",
    }.get(platform, "13.0")


def _platform_slice_for_library_identifier(lid: str) -> Optional[PlatformSlice]:
    """Map an xcframework `LibraryIdentifier` (e.g. `ios-arm64`,
    `ios-arm64_x86_64-simulator`) onto the matching `PlatformSlice` so we
    can pick the right SDK + clang min-version flag template. Returns
    None for identifiers we don't recognise; the caller treats that as
    "can't promote, surface the original verifier error".
    """
    platform = _platform_from_library_identifier(lid)
    if platform is None:
        return None
    variant = _variant_from_library_identifier(lid)
    for s in _PLATFORM_SLICES.get(platform, ()):
        if _variant_for_platform_slice(s) == variant:
            return s
    return None


def _filter_xcframework_slices_to_requested_platforms(
    xcframework_path: Path,
    requested_platforms: List[str],
    *,
    verbose: bool = False,
) -> List[str]:
    """Drop slices whose platform the user didn't request via `--min-*`.

    Vendor xcframeworks routinely ship more platforms than any one
    consumer asks for — Sentry 8.x ships ios+ios-simulator+ios-maccatalyst
    +macos+tvos+tvos-simulator+watchos+visionos. If the user only asked
    for `--min-ios`, the unrequested slices contribute nothing to their
    build, and worse: a static maccatalyst slice triggers a
    `-mtargetos=ios<ver>-macabi` clang invocation in
    `promote_binary_xcframework_static_to_dynamic` that not every
    installed clang accepts.

    Mutates the xcframework in place: deletes each unrequested slice
    directory and rewrites `Info.plist`'s `AvailableLibraries` to match.
    Returns the list of identifiers removed (empty list when the vendor
    xcframework already matches the requested set, including binary-only
    auto-detect where the requested set was derived from the slices
    themselves).

    Errors:
      - If requested_platforms is empty (defensive — caller should have
        validated this before binary execute starts), no filtering runs.
      - If the filter would leave zero slices, raise ExecuteError with
        the requested-vs-available breakdown so the user knows the vendor
        xcframework doesn't cover what they asked for.
    """
    if not requested_platforms:
        return []
    info_plist = xcframework_path / "Info.plist"
    if not info_plist.is_file():
        return []
    try:
        with info_plist.open("rb") as fh:
            data = plistlib.load(fh)
    except (plistlib.InvalidFileException, OSError, ValueError):
        return []
    available = data.get("AvailableLibraries")
    if not isinstance(available, list):
        return []

    requested = set(requested_platforms)
    kept: List[dict] = []
    removed: List[str] = []
    seen_platforms: set[str] = set()
    for entry in available:
        if not isinstance(entry, dict):
            kept.append(entry)
            continue
        identifier = entry.get("LibraryIdentifier")
        if not isinstance(identifier, str):
            kept.append(entry)
            continue
        platform = _platform_from_library_identifier(identifier)
        if platform is None:
            # Unrecognised — keep, let Verify surface the oddity rather
            # than silently dropping something we don't understand.
            kept.append(entry)
            continue
        seen_platforms.add(platform)
        if platform in requested:
            kept.append(entry)
        else:
            removed.append(identifier)
            slice_dir = xcframework_path / identifier
            if slice_dir.is_dir():
                shutil.rmtree(slice_dir, ignore_errors=True)

    if not kept:
        avail = ", ".join(sorted(seen_platforms)) or "(none recognisable)"
        req = ", ".join(sorted(requested))
        raise ExecuteError(
            f"Filtering {xcframework_path.name} to requested platforms "
            f"left zero slices. Requested: {req}. Vendor xcframework ships: "
            f"{avail}."
        )

    if removed:
        data["AvailableLibraries"] = kept
        with info_plist.open("wb") as fh:
            plistlib.dump(data, fh)
        verbose_log(
            verbose,
            f"  Dropped {len(removed)} unrequested slice(s) from "
            f"{xcframework_path.name}: {', '.join(removed)}",
        )
    return removed


def promote_binary_xcframework_static_to_dynamic(
    xcframework_path: Path,
    *,
    verbose: bool = False,
) -> List[str]:
    """Re-link every static-archive slice binary in a vendor xcframework as
    a dynamic Mach-O, in place. Returns the list of `LibraryIdentifier`s
    that were promoted (empty list when every slice is already dynamic).

    Why this exists: some upstream SDKs (Kidoz, others) ship xcframeworks
    whose `<slice>/<X>.framework/<X>` files are `current ar archive`
    static libraries rather than dynamically-linked Mach-O. Apple's
    xcframework spec tolerates this layout, but downstream consumers
    that need to `dlopen` the framework — notably .NET P/Invoke in the
    swift-bindings pipeline — cannot load a static archive. We rewrite
    each slice's binary into a real dynamic library using `clang
    -dynamiclib + -Xlinker -all_load + -Xlinker -undefined
    dynamic_lookup`, and drop the now-stale `_CodeSignature/` (Xcode
    resigns on embed; the user can also `codesign --force` post-hoc).

    System framework discovery is out of reach here — we don't have the
    Package.swift target to scan, only an opaque set of object files.
    The `-undefined dynamic_lookup` safety net handles that: any UIKit
    / Foundation / SDK symbol the static archive references is resolved
    at runtime by dyld instead of at link time.

    Side effects (per slice that needs promotion):
      - Replace `<slice>/<lib>/<X>` with a freshly-linked dynamic Mach-O.
      - Delete `<slice>/<lib>/_CodeSignature/` (no longer matches bytes).
      - macOS versioned bundles: same operation under `Versions/A/`.

    Raises `ExecuteError` if any slice promotion fails. Mid-loop
    failures leave already-promoted slices in their new state — Verify
    will surface the remaining static one and the run reports a clean
    failure.
    """
    # Late-bind `_check_binary_dynamic` through the package namespace so
    # tests that monkey-patch `spm_to_xcframework._check_binary_dynamic`
    # are honored at call time. A `from ..verify import _check_binary_dynamic`
    # at module top would freeze the original function reference into this
    # module's globals and tests' patches would be silently ignored.
    #
    # Side benefit: this is also what makes the single-file
    # concatenated form (`build_single_file.py`) work. The function
    # `_check_binary_dynamic` is defined in `verify.py`, which pastes
    # AFTER this module in `MODULE_ORDER`. A module-top `from ..verify
    # import` would translate to nothing in the single file (the
    # stripper drops it), and any top-level reference here would
    # `NameError` at import time. The function-body late-bind defers
    # the lookup until call time, by which point the entire script
    # has executed top-to-bottom and the global is bound. If you add a
    # new cross-phase private dep, keep the reference inside a function
    # body for the same reason.
    info_plist = xcframework_path / "Info.plist"
    if not info_plist.is_file():
        return []
    try:
        with info_plist.open("rb") as fh:
            data = plistlib.load(fh)
    except (plistlib.InvalidFileException, OSError, ValueError):
        return []
    available = data.get("AvailableLibraries")
    if not isinstance(available, list):
        return []

    promoted: List[str] = []
    for entry in available:
        if not isinstance(entry, dict):
            continue
        identifier = entry.get("LibraryIdentifier")
        library_path = entry.get("LibraryPath")
        binary_path_field = entry.get("BinaryPath")
        if not isinstance(identifier, str) or not isinstance(library_path, str):
            continue

        # Reconstruct the binary path the same way the verifier does — so
        # both agree on which file represents the slice executable.
        if isinstance(binary_path_field, str) and binary_path_field:
            binary_rel = binary_path_field
        else:
            lib_basename = os.path.basename(library_path.rstrip("/"))
            if not lib_basename.endswith(".framework"):
                # `.a`-as-library or other non-framework layout. Promotion
                # only knows about framework-wrapped statics; leave it to
                # the verifier to flag.
                continue
            stem = lib_basename[: -len(".framework")]
            binary_rel = f"{library_path.rstrip('/')}/{stem}"

        binary = xcframework_path / identifier / binary_rel
        if not binary.is_file():
            continue
        if _check_binary_dynamic(binary):
            continue

        platform = _platform_from_library_identifier(identifier)
        if platform is None:
            raise ExecuteError(
                f"static-archive slice {identifier!r} in "
                f"{xcframework_path.name}: unrecognised platform suffix; "
                "cannot map to an SDK to re-link as a dynamic library."
            )
        platform_slice = _platform_slice_for_library_identifier(identifier)
        if platform_slice is None:
            raise ExecuteError(
                f"static-archive slice {identifier!r} in "
                f"{xcframework_path.name}: no matching PlatformSlice for "
                f"platform {platform!r}; cannot promote to dynamic."
            )

        archs = _lipo_archs(binary)
        if not archs:
            raise ExecuteError(
                f"static-archive slice {identifier!r} in "
                f"{xcframework_path.name}: lipo could not enumerate "
                f"architectures of {binary}."
            )

        deployment_target = _slice_minimum_deployment_target(entry, platform)
        min_ver_flag = platform_slice.clang_min_flag_template.format(
            version=deployment_target
        )
        # `install_name` is derived from the binary basename (not from
        # LibraryPath's framework stem) because that's the name we will
        # actually write the dylib under. Apple framework bundle
        # conventions require the executable name inside a `.framework`
        # to match the bundle stem, so for any well-formed xcframework
        # the two are equal — and if they diverge, the upstream artefact
        # was already unloadable as a framework before promotion. This
        # mirrors how Verify reconstructs `BinaryPath` from `LibraryPath`.
        product = binary.name
        framework_dir = binary.parent  # `<...>.framework` (or `Versions/A`)
        tmp_out = binary.with_name(binary.name + ".dyn.tmp")

        info(
            f"  Promoting static archive → dynamic: "
            f"{xcframework_path.name}/{identifier} "
            f"({platform_slice.sdk_name}: {' '.join(archs)})"
        )

        cmd: List[str] = [
            "xcrun", "--sdk", platform_slice.sdk_name, "clang", "-dynamiclib",
        ]
        for a in archs:
            cmd.extend(["-arch", a])
        cmd.extend([
            min_ver_flag,
            "-install_name", f"@rpath/{product}.framework/{product}",
            "-Xlinker", "-all_load",
            str(binary),
            "-Xlinker", "-undefined", "-Xlinker", "dynamic_lookup",
            "-o", str(tmp_out),
        ])
        verbose_log(verbose, f"  $ {' '.join(cmd)}")

        cp = subprocess.run(
            cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True
        )
        if cp.returncode != 0:
            if tmp_out.exists():
                try:
                    tmp_out.unlink()
                except OSError:
                    pass
            tail = "\n".join(
                ((cp.stderr or cp.stdout or "").rstrip().splitlines())[-10:]
            )
            raise ExecuteError(
                f"Failed to re-link static archive "
                f"{binary.relative_to(xcframework_path)} as a dynamic "
                f"library (sdk={platform_slice.sdk_name}, archs="
                f"{' '.join(archs)}):\n" + (tail or "  (no output)")
            )

        try:
            os.replace(str(tmp_out), str(binary))
        except OSError as exc:
            # Best-effort tmp cleanup so a failed replace doesn't leave
            # `<X>.dyn.tmp` next to the live binary forever — a second
            # run would skip promotion (the old static archive is still
            # in place and `_check_binary_dynamic` returns False), but
            # subsequent reruns shouldn't accumulate orphan tmpfiles.
            if tmp_out.exists():
                try:
                    tmp_out.unlink()
                except OSError:
                    pass
            raise ExecuteError(
                f"Failed to replace static archive at {binary}: {exc}"
            )

        # The prior `_CodeSignature/` no longer matches the new binary.
        # Drop it; Xcode re-signs on embed. Check both the framework root
        # (iOS-style flat layout) AND `Versions/A/` (macOS versioned
        # bundles) — `binary.parent` already points at whichever one
        # holds the executable, so removing `_CodeSignature` there is
        # correct for both layouts. Soft-fail with a warning here: at
        # this point the binary is already promoted and usable; a stale
        # signature is a downstream embed warning, not a build break.
        codesig = framework_dir / "_CodeSignature"
        if codesig.is_dir():
            try:
                shutil.rmtree(codesig)
            except OSError as exc:
                warn(
                    f"Could not remove stale code signature at {codesig} "
                    f"after promoting {identifier} (binary itself was "
                    f"successfully re-linked): {exc}"
                )

        promoted.append(identifier)

    return promoted


def execute_binary_plan(
    plan: Plan,
    config: Config,
) -> List[ExecutedUnit]:
    """Copy each `copy-artifact` build unit's xcframework into
    `config.output_dir`.

    The artifact paths come from the planner (which got them from
    `discover_binary_artifacts` during Fetch — same code path Execute
    would otherwise reach for, so the two phases never disagree about
    which xcframeworks exist). The Execute-side responsibilities are
    the copy itself, a paranoia guard against `__MACOSX` slipping in,
    and a static→dynamic promotion pass for any slice whose framework
    binary turns out to be a `current ar archive` rather than a
    dynamically-linked Mach-O (some vendors ship xcframeworks in that
    shape; downstream P/Invoke consumers cannot dlopen them).
    """
    config.output_dir.mkdir(parents=True, exist_ok=True)
    copy_units = [u for u in plan.build_units if u.archive_strategy == "copy-artifact"]
    if not copy_units:
        return []
    bold(f"\nCopying {len(copy_units)} binary artifact(s)...")
    results: List[ExecutedUnit] = []
    for unit in copy_units:
        if unit.artifact_path is None:
            raise ExecuteError(
                f"binary build unit {unit.name!r} has no artifact_path — "
                f"plan_binary_build did not record one. This is a bug."
            )
        src = unit.artifact_path
        if "__MACOSX" in src.parts:
            raise ExecuteError(
                f"refusing to copy ghost xcframework from {src} (path contains __MACOSX)"
            )
        if not src.is_dir():
            raise ExecuteError(f"binary artifact missing on disk: {src}")
        dest = config.output_dir / src.name
        if "__MACOSX" in dest.parts:
            raise ExecuteError(f"refusing to write to {dest} (path contains __MACOSX)")
        if dest.exists():
            shutil.rmtree(dest)
        info(f"  Copying {src.name}...")
        shutil.copytree(src, dest, symlinks=True)
        # Filter to user-requested platforms first. Two reasons: (a) the
        # source-mode contract is "you got what you asked for via
        # --min-*"; binary mode should behave the same, (b) keeping an
        # unrequested slice can crash the promotion pass below (Sentry's
        # maccatalyst slice → an unsupported `-mtargetos=ios<ver>-macabi`
        # clang invocation on some installed toolchains).
        requested_platforms = _enabled_platforms(config)
        dropped = _filter_xcframework_slices_to_requested_platforms(
            dest, requested_platforms, verbose=config.verbose,
        )
        if dropped:
            info(
                f"  Dropped {len(dropped)} unrequested slice(s) from "
                f"{dest.name}: {', '.join(dropped)}"
            )
        # Promote any static-archive slices to dynamic in place. No-op
        # for the common case of vendor xcframeworks that already ship
        # dynamic binaries — `_check_binary_dynamic` short-circuits the
        # per-slice work. Failures raise ExecuteError so the user gets
        # a clean phase error instead of a confusing Verify rejection
        # downstream.
        promoted = promote_binary_xcframework_static_to_dynamic(
            dest, verbose=config.verbose
        )
        if promoted:
            success(
                f"  Promoted {len(promoted)} static slice(s) to dynamic: "
                + ", ".join(promoted)
            )
        # `detect_framework_type` classifies by header / swiftinterface
        # presence, not by binary linkage, so promotion never changes its
        # answer. Call it after any on-disk mutation in this loop anyway
        # so the printed label is always derived from the final layout —
        # cheap, and survives any future mutation that *would* affect the
        # classification.
        fw_type = detect_framework_type(dest)
        success(f"  {dest.name} ready [{fw_type}]")
        results.append(
            ExecutedUnit(
                name=unit.name,
                xcframework_path=dest,
                framework_name=src.stem,
                framework_type=fw_type,
                # Binary mode never has an expected language — the plan
                # copied pre-built bytes without inspecting them. Leaving
                # this empty makes Verify fall back to post-hoc detection
                # for binary units, which is the only thing it can do.
                expected_language=Language.NA,
                expected_slice_classes=_expected_slice_classes(config),
                is_binary_copy=True,
            )
        )
    return results


